LINUX_INC_DIR = SYS_DIR / "kernel" / "include" / "linux"
LINUX_SOURCE_DIR = SYS_DIR / "kernel" / "linux_source"
CACHE_DIR = WORKSPACE_ROOT / ".dep_cache"

# Manifest of all required sources with prioritized fallback mirrors
DEPENDENCIES = {
    "lwip": {
