        __bss_start = .;
        *(.bss .bss.*)
        *(COMMON)
        __bss_end = .;
    }

    /* Capture the absolute upper memory limit marker of your compiled image footprint */
    . = ALIGN(4096);
    __kernel_end = .;

    /* --------------------------------------------------------------------------
     * 5. STRIP UNRECOGNIZED Monolithic METADATA DEBUG BLOCKS
