}

bool sys_register_vault_restriction(const char* ext, uint32_t sandbox_tier) {
    if (g_ext_vault.total_registered_rules >= MAX_VAULT_RULES || strlen(ext) >= 8) return false;

    uint32_t idx = g_ext_vault.total_registered_rules;
    ExtensionRuleNode* rule = &g_ext_vault.rule_database[idx];
    
    strncpy(rule->extension_string, ext, 7);
    rule->required_sandbox_tier = sandbox_tier;
    rule->is_restricted = true;
    g_ext_vault.total_registered_rules++;
    
    printf("[Extension Vault]: Sealed format boundary constraint: '%s' bound to Sandbox Tier %d\\n", ext, sandbox_tier);
    return true;
}

bool verify_vfs_extension_compliance(const char* target_file_path, uint32_t process_sandbox_tier) {
    if (!g_ext_vault.is_vault_enforcing || !target_file_path) return true;

    // Isolate and extract file extension suffix from path strings
    const char* extension_dot = strrchr(target_file_path, '.');
    if (!extension_dot) return true; // File lacks extension tracking strings, bypass

    for (uint32_t i = 0; i < g_ext_vault.total_registered_rules; i++) {
        ExtensionRuleNode* rule = &g_ext_vault.rule_database[i];
        if (rule->is_restricted && strcmp(rule->extension_string, extension_dot) == 0) {
            
            // POLICY BOUNDARY CHECK: Evaluate application tier capabilities against extension vault laws
            if (process_sandbox_tier < rule->required_sandbox_tier) {
                char alert_desc[128];
                snprintf(alert_desc, sizeof(alert_desc), "VAULT BREACH BLOCKED: Process Tier %u denied opening '%s'", process_sandbox_tier, target_file_path);
                commit_security_audit_entry(0x0003 /* EVENT_AUTH_FAILURE */, "EXT_VAULT", alert_desc);
                printf("[SECURITY FAULT]: %s -> Access denied.\\n", alert_desc);
                return false; // Breach attempt blocked: reject VFS file stream assembly parameters
            }
        }
    }
    return true; // Extension compliant with sandbox policy maps
}
__SECURECURTAIN_EOF__

cat << '__SECURECURTAIN_EOF__' > "${TARGET_DIR}/sys/kernel/src/file_manager.c"
#include "file_manager.h"
#include "ipc.h"
#include "auth.h"
#include "vfs.h"
#include <string.h>

typedef struct {
    char                    current_browsed_directory[256];
    fm_directory_entry_t    cached_entries[FM_MAX_ENTRIES];
    size_t                  active_entry_count;
    ipc_handle_t            auth_server_proxy; // Handle linking securely back to auth_server.bin
    ipc_handle_t            vfs_proxy_handle;   // Handle linking securely back to the VFS engine
} secure_file_browser_t;

static secure_file_browser_t g_file_browser;
extern void print_string(const char* str, int row);

void init_file_manager_server(void) {
    memset(&g_file_browser, 0, sizeof(secure_file_browser_t));
    g_file_browser.auth_server_proxy = 8; // Tied directly to your auth_server.bin handle
    g_file_browser.vfs_proxy_handle   = 4; // Tied directly to your vfs.h kernel proxy handle
    strcpy(g_file_browser.current_browsed_directory, "/");

    print_string("[OK] Sandboxed File Browser: UI Directory Navigation Engine Online.", 29);
}

int handle_file_manager_message(const ipc_message_t* msg, ipc_message_t* out_response) {
    if (!msg || !out_response) return -1;
    if (msg->message_type != FM_CMD_LIST_DIRECTORY) return -1;

    memset(out_response, 0, sizeof(ipc_message_t));
    out_response->message_type = msg->message_type;

    // Pre-allocate the response envelope layout safely
    out_response->payload_length = sizeof(int32_t);
    int32_t* return_status = (int32_t*)out_response->payload;

    if (msg->payload_length < sizeof(fm_ipc_browse_frame_t)) {
        *return_status = -2; // Corrupt packet layout sizing boundary
        return 0;
    }

    const fm_ipc_browse_frame_t* browse = (const fm_ipc_browse_frame_t*)msg->payload;

    // 1. 🛡️ USER SESSION IDENTITY VERIFICATION HANDSHAKE
    // Validate the client's token with your unprivileged auth_server.bin module
    ipc_message_t auth_check_tx, auth_check_rx;
    memset(&auth_check_tx, 0, sizeof(ipc_message_t));
    auth_check_tx.message_type = AUTH_CMD_VALIDATE_TOKEN;
    auth_check_tx.payload_length = 32;
    memcpy(auth_check_tx.payload, &browse->session_token, 1); // Match single-byte user token

    int auth_status = ipc_send_message(g_file_browser.auth_server_proxy, &auth_check_tx);
    if (auth_status != IPC_SUCCESS || ipc_receive_message(g_file_browser.auth_server_proxy, &auth_check_rx) != IPC_SUCCESS) {
        *return_status = -4; // Access Denied: Auth engine connection dropped, block reading
        return 0;
    }

    auth_ipc_response_frame_t* auth_resp = (auth_ipc_response_frame_t*)auth_check_rx.payload;

    // 2. 🛡️ REFACTORED USER AUTHORIZATION FILTER
    // Check if the current user session belongs to the verified master "aaa" account (UID 1000)
    if (auth_resp->status_code != 0 || auth_resp->authorized_uid != 1000) {
        print_string("[SECURITY LOCKOUT] Unauthorized directory listing browse request blocked!", 30);
        *return_status = -4; // Access Denied
        return 0;
    }

    // 3. 🛡️ PATH SIZE BOUNDARY CLEANSE
    char sanitized_path[256];
    memcpy(sanitized_path, browse->target_path, 256);
    sanitized_path[255] = '\\0'; // Enforce absolute null-termination

    // 4. Proxy directory lookup out to the abstract VFS proxy tree layer
    // instead of calling Ring 0 filesystem code blocks directly.
    g_file_browser.active_entry_count = 0;
    
    // Simulating mapping out file results for Nemo/Dolphin GUI folder generation loops
    if (strcmp(sanitized_path, "/SYSTEM/SERVERS") == 0) {
        size_t idx = g_file_browser.active_entry_count++;
        strcpy(g_file_browser.cached_entries[idx].name, "storage_server.bin");
        g_file_browser.cached_entries[idx].type_flags = VFS_FILE;
        g_file_browser.cached_entries[idx].file_size = 65536;

        idx = g_file_browser.active_entry_count++;
        strcpy(g_file_browser.cached_entries[idx].name, "graphics_server.bin");
        g_file_browser.cached_entries[idx].type_flags = VFS_FILE;
        g_file_browser.cached_entries[idx].file_size = 131072;
    } else {
        // Fallback root empty layout view
        size_t idx = g_file_browser.active_entry_count++;
        strcpy(g_file_browser.cached_entries[idx].name, "SYSTEM");
        g_file_browser.cached_entries[idx].type_flags = VFS_DIRECTORY;
        g_file_browser.cached_entries[idx].file_size = 0;
    }

    // Package directory tracking lists cleanly back into the output payload envelope
    uint32_t payload_bytes = g_file_browser.active_entry_count * sizeof(fm_directory_entry_t);
    out_response->payload_length = sizeof(int32_t) + payload_bytes;
    
    uint8_t* payload_dest_ptr = out_response->payload + sizeof(int32_t);
    memcpy(payload_dest_ptr, g_file_browser.cached_entries, payload_bytes);

    print_string("[FILE MGR] Directory listings compiled and proxied to Dolphin/Nemo GUI.", 30);
    *return_status = 0; // Success
    return 0;
}
__SECURECURTAIN_EOF__

cat << '__SECURECURTAIN_EOF__' > "${TARGET_DIR}/sys/kernel/src/file_manager_gui.c"
#include "file_manager.h"
#include "graphics.h"
#include "ipc.h"
#include <string.h>

static ipc_handle_t g_backend_fm_handle = 16; // Linked to file_manager_server.bin
static ipc_handle_t g_graphics_handle   = 3;  // Linked to graphics_server.bin

extern void print_string(const char* str, int row);

/**
 * 🛡️ REFACTORED GUI DRAWER CORNER
 * Loops through the fetched folder array table to render a lightweight list.
 * Clips geometries to protect memory maps from layout corruption.
 */
void fm_gui_render_window(const fm_directory_entry_t* entries, size_t entry_count, uint8_t user_token) {
    // 1. Request the Graphics Compositor to initialize a new window surface canvas context
    ipc_message_t comp_msg;
    memset(&comp_msg, 0, sizeof(ipc_message_t));
    comp_msg.message_type = 0x801; // GRAPHICS_CMD_INIT command flag
    
    // Set layout parameters for our floating Nemo/Dolphin application interface block
    graphics_ipc_rect_frame_t* win_rect = (graphics_ipc_rect_frame_t*)comp_msg.payload;
    win_rect->x = 150;
    win_rect->y = 100;
    win_rect->width = 400;
    win_rect->height = 300;
    comp_msg.payload_length = sizeof(graphics_ipc_rect_frame_t);
    ipc_send_message(g_graphics_handle, &comp_msg);

    // 2. Draw a clean, slate-gray background rectangle wrapper panel
    memset(&comp_msg, 0, sizeof(ipc_message_t));
    comp_msg.message_type = 0x804; // GRAPHICS_CMD_DRAW_RECT
    graphics_ipc_rect_frame_t* bg_rect = (graphics_ipc_rect_frame_t*)comp_msg.payload;
    bg_rect->x = 150; bg_rect->y = 100; bg_rect->width = 400; bg_rect->height = 300;
    bg_rect->color.r = 0x2A; bg_rect->color.g = 0x2E; bg_rect->color.b = 0x32; // Charcoal theme
    comp_msg.payload_length = sizeof(graphics_ipc_rect_frame_t);
    ipc_send_message(g_graphics_handle, &comp_msg);

    // 3. Render a light-blue title bar layout text strip across the top header
    bg_rect->y = 100; bg_rect->height = 24;
    bg_rect->color.r = 0x3D; bg_rect->color.g = 0x8E; bg_rect->color.b = 0xC7; // Deep Blue title
    ipc_send_message(g_graphics_handle, &bg_rect);

    // 4. 🛡️ CRITICAL LOOP CAP CONSTRAINT: Prevent interface rendering overflows
    // We restrict rendering to a maximum of 6 elements to guarantee text clipping bounds.
    size_t display_limit = (entry_count > 6) ? 6 : entry_count;

    for (size_t i = 0; i < display_limit; i++) {
        uint32_t text_y_pos = 140 + (i * 24);

        // Draw a miniature square proxy block representing a folder/file item icon layout
        memset(&comp_msg, 0, sizeof(ipc_message_t));
        comp_msg.message_type = 0x804;
        graphics_ipc_rect_frame_t* icon = (graphics_ipc_rect_frame_t*)comp_msg.payload;
        icon->x = 170; icon->y = text_y_pos; icon->width = 16; icon->height = 16;
        
        // Color-code the graphic nodes: Gold for Directories, White for Binaries/Files
        if (entries[i].type_flags == 2) { // VFS_DIRECTORY
            icon->color.r = 0xFD; icon->color.g = 0xBC; icon->color.b = 0x40; // Folder Gold
        } else {
            icon->color.r = 0xEF; icon->color.g = 0xF0; icon->color.b = 0xF1; // File White
        }
        comp_msg.payload_length = sizeof(graphics_ipc_rect_frame_t);
        ipc_send_message(g_graphics_handle, &comp_msg);

        // Send text string drawing instructions across to the user space font engine
        memset(&comp_msg, 0, sizeof(ipc_message_t));
        comp_msg.message_type = 0x805; // GRAPHICS_CMD_DRAW_STR
        
        // Pack coordinates and data string fragments safely into the proxy envelope
        *(uint32_t*)&comp_msg.payload = 200;        // X offset trailing icon
        *(uint32_t*)&comp_msg.payload = text_y_pos;  // Y line offset
        strcpy((char*)&comp_msg.payload, entries[i].name);
        
        comp_msg.payload_length = 8 + strlen(entries[i].name) + 1;
        ipc_send_message(g_graphics_handle, &comp_msg);
    }

    // 5. Fire a flush command over IPC to trigger the final Z-Order blit loop calculation
    memset(&comp_msg, 0, sizeof(ipc_message_t));
    comp_msg.message_type = 0x803; // GRAPHICS_CMD_FLUSH
    ipc_send_message(g_graphics_handle, &comp_msg);
}

/**
 * 🛡️ INTERACTIVE DIRECTORY REQUEST TRIGGER
 * Contacts the unprivileged file manager server backend over IPC to pull 
 * the folder table matrix using our secure token boundaries.
 */
void fm_gui_request_browse(const char* target_folder_path, uint8_t active_user_token) {
    ipc_message_t tx_msg;
    ipc_message_t rx_msg;
    memset(&tx_msg, 0, sizeof(ipc_message_t));
    tx_msg.message_type = FM_CMD_LIST_DIRECTORY;

    // Pack the secure browse query parameters into the payload envelope
    fm_ipc_browse_frame_t* req = (fm_ipc_browse_frame_t*)tx_msg.payload;
    req->session_token = active_user_token;
    strcpy(req->target_path, target_folder_path);
    tx_msg.payload_length = sizeof(fm_ipc_browse_frame_t);

    // Synchronize communications cleanly across the server containers
    int status = ipc_send_message(g_backend_fm_handle, &tx_msg);
    if (status == IPC_SUCCESS && ipc_receive_message(g_backend_fm_handle, &rx_msg) == IPC_SUCCESS) {
        
        int32_t response_status_code = *(int32_t*)rx_msg.payload;
        if (response_status_code == 0) {
            // Read out the directory array block returned from the validated backend server
            size_t entry_bytes = rx_msg.payload_length - sizeof(int32_t);
            size_t entry_count = entry_bytes / sizeof(fm_directory_entry_t);
            const fm_directory_entry_t* entries_table = (const fm_directory_entry_t*)(rx_msg.payload + sizeof(int32_t));

            // Render the items onto our secure canvas window surface
            fm_gui_render_window(entries_table, entry_count, active_user_token);
        } else {
            print_string("[GUI ERR] Directory browse authorization failed at boundary.", 27);
        }
    }
}
__SECURECURTAIN_EOF__

cat << '__SECURECURTAIN_EOF__' > "${TARGET_DIR}/sys/kernel/src/fs_integrity.c"
#include "fs_integrity.h"
#include "vfs_journal.h"
#include "security_panic.h"
#include "security_audit.h"
#include "kstring.h"
#include <stdio.h>

static IntegrityControlRegistry g_integrity_engine;

extern void read_raw_disk_sector(uint16_t port, uint32_t sector, uint8_t* buffer);
extern void write_raw_disk_sector(uint16_t port, uint32_t sector, const uint8_t* buffer);

// Optimized mathematical step to compute sector payload blocks verification signatures
static uint32_t calculate_sector_crc32(const uint8_t* buffer, uint32_t len) {
    uint32_t crc = 0xFFFFFFFF;
    for (uint32_t i = 0; i < len; i++) {
        crc ^= buffer[i];
        for (uint8_t bit = 0; bit < 8; bit++) {
            if (crc & 1) crc = (crc >> 1) ^ 0xEDB88320;
            else         crc >>= 1;
        }
    }
    return ~crc;
}

void init_fs_integrity_validator_daemon(void) {
    kmemset(&g_integrity_engine, 0, sizeof(IntegrityControlRegistry));
    g_integrity_engine.magic = INTEGRITY_MAGIC_TAG;
    g_integrity_engine.metrics.current_scan_lba = VFS_SECTOR_START_LOG;
    g_integrity_engine.metrics.is_background_scanner_active = true;
    printf("[Kernel Integrity]: Asynchronous sector background checksum validation daemon active.\\n");
}

void sys_fs_execute_asynchronous_background_sweep_tick(void) {
    if (!g_integrity_engine.metrics.is_background_scanner_active) return;

    uint32_t target_lba = g_integrity_engine.metrics.current_scan_lba;
    uint8_t sector_read_buffer[512];

    // Read the raw disk block parameters directly via motherboard IDE/SATA ports
    read_raw_disk_sector(0x1F0, target_lba, sector_read_buffer);

    // Unpack pre-calculated verification token signatures trailing the data blocks
    // (In your complete core, these are cross-referenced from a dedicated metadata table)
    uint32_t stored_expected_checksum = *(uint32_t*)(&sector_read_buffer[508]);
    uint32_t computed_live_checksum = calculate_sector_crc32(sector_read_buffer, 508);

    if (stored_expected_checksum != 0 && computed_live_checksum != stored_expected_checksum) {
        g_integrity_engine.metrics.dynamic_bitrot_failures_found++;
        
        char error_desc[64];
        ksnprintf(error_desc, sizeof(error_desc), "STORAGE INTEGRITY EXCEPTION: Bit-rot or tamper on LBA %u", target_lba);
        commit_security_audit_entry(0x0004, "FS_INTEGRITY", error_desc);
        printf("[Kernel Integrity Fault]: %s -> Initiating isolation locks.\\n", error_desc);

        // Force a system halt if a vital system configuration sector metadata block has been corrupted
        if (target_lba < VFS_SECTOR_START_LOG + 1000) {
            execute_kernel_security_panic("CRITICAL DATA CORRUPTION: Host storage volume structurally compromised!");
        }
    }

    g_integrity_engine.metrics.total_sectors_validated++;
    
    // Increment the scanning index loop to process the next sector block sequentially
    g_integrity_engine.metrics.current_scan_lba++;
    if (g_integrity_engine.metrics.current_scan_lba >= VFS_SECTOR_CEILING) {
        g_integrity_engine.metrics.current_scan_lba = VFS_SECTOR_START_LOG; // Loop back and restart the cycle
        printf("[Kernel Integrity]: Completed whole-drive background validation sweep. Storage pristine.\\n");
    }
}

bool sys_commit_filesystem_metadata_update(uint32_t target_lba, const uint8_t* metadata_buffer) {
    if (!metadata_buffer) return false;

    // 1. Open an atomic transaction block inside Ring 0 to protect the data layout
    uint32_t tx_id = sys_vfs_journal_open_transaction(target_lba, 1);
    if (tx_id == 0) return false;

    // 2. Transition the transaction stage into the COMMIT stage
    sys_vfs_journal_update_stage(tx_id, TRANS_STAGE_COMMIT);

    // Staging area to inject data and append validation tracking keys
    uint8_t hardware_write_block[512];
    kmemcpy(hardware_write_block, metadata_buffer, 508);

    // Append the newly calculated CRC32 checksum token into the last 4 bytes of the data sector
    uint32_t clean_checksum = calculate_sector_crc32(hardware_write_block, 508);
    *(uint32_t*)(&hardware_write_block[508]) = clean_checksum;

    // 3. Write out the actual data block parameters onto the persistent drive hardware ports
    write_raw_disk_sector(0x1F0, target_lba, hardware_write_block);

    // 4. Seal the transaction as safely written
    sys_vfs_journal_update_stage(tx_id, TRANS_STAGE_COMPLETED);
    return true;
}
__SECURECURTAIN_EOF__

cat << '__SECURECURTAIN_EOF__' > "${TARGET_DIR}/sys/kernel/src/fw_injector.c"
#include "signature_parser.h"
#include "fw_injector.h"
#include "security_audit.h"
#include <stdio.h>

static FirewallBlockRule g_blocked_ip_table[MAX_BLOCKED_IPS];
static uint32_t         g_total_blocked_rules = 0;

extern uint64_t get_system_uptime_ms(void);

void init_firewall_injector(void) {
    g_total_blocked_rules = 0;
    for (uint32_t i = 0; i < MAX_BLOCKED_IPS; i++) {
        g_blocked_ip_table[i].is_active = false;
    }
}

void inject_firewall_block_rule(uint32_t offending_ip) {
    // Check if the IP is already blocked to prevent rule duplication
    for (uint32_t i = 0; i < g_total_blocked_rules; i++) {
        if (g_blocked_ip_table[i].is_active && g_blocked_ip_table[i].ipv4_address == offending_ip) {
            return; 
        }
    }

    if (g_total_blocked_rules >= MAX_BLOCKED_IPS) {
        printf("[Firewall Engine]: Table limit reached. Dropping oldest rules first.\\n");
        g_total_blocked_rules = 0; // Simple ring buffer override
    }

    FirewallBlockRule* rule = &g_blocked_ip_table[g_total_blocked_rules];
    rule->ipv4_address = offending_ip;
    rule->insertion_tick = get_system_uptime_ms();
    rule->is_active = true;

    g_total_blocked_rules++;

    unsigned char bytes[4];
    bytes[0] = offending_ip & 0xFF;
    bytes[1] = (offending_ip >> 8) & 0xFF;
    bytes[2] = (offending_ip >> 16) & 0xFF;
    bytes[3] = (offending_ip >> 24) & 0xFF;
    
    printf("[Firewall Engine]: INJECTED HARD BLOCK RULE -> Isolated IP: %d.%d.%d.%d\\n", bytes[0], bytes[1], bytes[2], bytes[3]);
}

bool evaluate_packet_against_blocklist(uint32_t source_ip) {
    for (uint32_t i = 0; i < g_total_blocked_rules; i++) {
        if (g_blocked_ip_table[i].is_active && g_blocked_ip_table[i].ipv4_address == source_ip) {
            return true; // Match found: Packet must be dropped immediately
        }
    }
    return false; // Safe to pass to higher subsystem stacks
}

bool sys_evaluate_inbound_firewall_frame(uint16_t d_port, const uint8_t* data_stream, uint32_t len) {
    if (!sys_evaluate_network_signature((uint32_t)d_port, data_stream, len)) {
        return false;
    }
    return true;
}
__SECURECURTAIN_EOF__

cat << '__SECURECURTAIN_EOF__' > "${TARGET_DIR}/sys/kernel/src/gdt_idt.asm"
bits 64
global flush_gdt
global load_idt
global load_tss
global page_fault_asm_stub

extern core_page_fault_handler_c

; ------------------------------------------------------------------------------
; 🛡️ SECURE GDT FLUSH & Privileged Segment Synchronization
; ------------------------------------------------------------------------------
flush_gdt:
    lgdt [rdi]        ; Load the GDT descriptor layout passed from C

    ; 1. Reset standard supervisor data segment tracking registers
    mov ax, 0x10      ; 0x10 is our Kernel Data Selector (GDT Index 2)
    mov ds, ax
    mov es, ax
    mov ss, ax
    
    ; Clear thread-local block registers to avoid information leaks
    xor ax, ax
    mov fs, ax
    mov gs, ax

    ; 2. HARDWARE ENFORCED: Force execution pipeline reload via a pseudo-Far Return.
    ; This explicitly forces the 'CS' register to update to our 64-bit Kernel Code descriptor.
    mov rax, 0x08     ; 0x08 is our Kernel Code Selector (GDT Index 1)
    push rax          ; Push the target Code Segment selector onto the stack
    lea rax, [rel .reload_cs] ; Load the address of the next sequential instruction
    push rax          ; Push the target instruction pointer onto the stack
    retfq             ; Perform a 64-bit Far Return to update CS and clear execution pipeline

.reload_cs:
    ret

; ------------------------------------------------------------------------------
; 🛡️ SECURE TASK REGISTER BINDING
; ------------------------------------------------------------------------------
load_tss:
    ; RDI contains the TSS GDT byte offset selector (0x28 passed from gdt_idt.c)
    ltr di            ; Load Task Register (Tells CPU where to find the isolation stacks)
    ret

; ------------------------------------------------------------------------------
; 🛡️ SECURE INTERRUPT DESCRIPTOR BINDING
; ------------------------------------------------------------------------------
load_idt:
    lidt [rdi]        ; Load the IDT descriptor layout passed from C
    ; REMOVED 'sti': Let your master main.c daemon decide when it is safe to unmask interrupts.
    ret

; ------------------------------------------------------------------------------
; 🛡️ HARDENED EXCEPTION HANDLING INTERCEPTOR (Exception Vector 14)
; ------------------------------------------------------------------------------
page_fault_asm_stub:
    ; 1. PRESERVE INTEL VOLATILE CONTEXT IMMEDIATELY
    ; When a page fault occurs, the stack layout is currently:
    ; [rsp + 0] = Hardware Error Code (Pushed automatically by CPU)
    ; [rsp + 8] = Faulting RIP
    ; [rsp + 16] = Faulting CS
    ; [rsp + 24] = Faulting RFLAGS
    ; [rsp + 32] = Faulting User RSP (if coming from Ring 3)
    ; [rsp + 40] = Faulting User SS
    
    push rbp
    push rdi
    push rsi
    push rdx
    push rcx
    push rax
    push r8
    push r9
    push r10
    push r11

    ; 2. SECURELY EXTRACT HARDWARE DIAGNOSTIC REGISTER VALUES
    ; Read the exact illegal virtual memory address the process tried to probe
    mov rsi, cr2       ; Argument 2 (RSI) = Faulting Virtual Address
    
    ; Read the error code pushed by the CPU, located just above our saved registers
    mov rdi, [rsp + 80] ; Argument 1 (RDI) = Raw 32-bit hardware error code mask

    ; 3. EXECUTE DEFENSE LOGIC
    ; Call the C memory engine to isolate the rogue Windows/Linux process thread
    call core_page_fault_handler_c

    ; 4. RESTORE AND SANITIZE REGISTERS
    pop r11
    pop r10
    pop r9
    pop r8
    pop rax
    pop rcx
    pop rdx
    pop rsi
    pop rdi
    pop rbp

    ; 5. CLEAN UP HARDWARE ERROR CODE
    add rsp, 8        ; Securely drop the 8-byte error code allocation from stack frame

    iretq             ; Safely restore privilege rings back to execution target
