// Current global tracked mouse coordinates inside the Ring 3 sandbox
static int32_t g_mouse_current_x = 512;
static int32_t g_mouse_current_y = 384;

// Internal PS/2 mouse packet assembly buffer state tracking
static uint8_t  g_mouse_packet_buffer[MOUSE_PACKET_SIZE];
static uint8_t  g_mouse_packet_index = 0;

// 🛡️ HARDENED SCANCODE TRANSLATION SHEET
// Statically maps raw motherboard bus scancodes directly to standardized UI keycodes.
// Unassigned indexes default safely to zero to prevent ambient out-of-bounds pointer writes.
static const uint32_t g_secure_scancode_map[SCANCODE_TABLE_SIZE] = {
    [0x01] = 27,   // Escape Key
    [0x02] = '1',  [0x03] = '2',  [0x04] = '3',  [0x05] = '4',
    [0x1E] = 'A',  [0x30] = 'B',  [0x2E] = 'C',  [0x20] = 'D',
    [0x1C] = 13,   // Enter Key
    [0x39] = ' '   // Spacebar
};

/**
 * 🛡️ SANDBOXED KEYBOARD SCANCODE TRANSLATOR
 * Processes a raw hardware scancode byte inside Ring 3 boundaries.
 */
static void local_translate_keyboard_byte(uint8_t scancode, input_packet_t* out_packet) {
    out_packet->event_type = EVENT_KEYPRESS;
    out_packet->mouse_x = g_mouse_current_x;
    out_packet->mouse_y = g_mouse_current_y;

    // Isolate the make/break flag (Bit 7 determines if key was released)
    uint8_t raw_idx = scancode & 0x7F;
    uint8_t is_release = scancode & 0x80;

    // 1. Enforce strict array indexing bounds verification
    if (raw_idx >= SCANCODE_TABLE_SIZE) {
        out_packet->key_code = 0; // Drop unrecognized/malicious scancode indexes safely
        return;
    }

    // Look up the standardized code. If key is released, map custom break flag or drop
    uint32_t translated_code = g_secure_scancode_map[raw_idx];
    out_packet->key_code = is_release ? (translated_code | 0x80000000) : translated_code;
}

/**
 * 🛡️ BOUNDS-SAFE MOUSE PACKET DECODER
 * Processes raw asynchronous bytes from the mouse hardware stream.
 * Once a full 3-byte packet is constructed, it translates deltas and applies strict resolution clipping.
 */
static int local_translate_mouse_byte(uint8_t raw_byte, input_packet_t* out_packet) {
    // 2. State-machine synchronization check
    // The first byte of a valid PS/2 packet must always have bit 3 set to 1.
    if (g_mouse_packet_index == 0 && !(raw_byte & 0x08)) {
        return 0; // Packet out of sync, drop byte to prevent garbage coordinate math
    }

    g_mouse_packet_buffer[g_mouse_packet_index++] = raw_byte;

    // Await full packet assembly before computing coordinates
    if (g_mouse_packet_index < MOUSE_PACKET_SIZE) {
        return 0; 
    }

    // Reset index pointer for the next incoming hardware packet stream
    g_mouse_packet_index = 0;

    uint8_t flags = g_mouse_packet_buffer[0];
    int32_t delta_x = (int32_t)g_mouse_packet_buffer[1];
    int32_t delta_y = (int32_t)g_mouse_packet_buffer[2];

    // Handle standard sign-extension bits for negative movement deltas
    if (flags & 0x10) delta_x |= 0xFFFFFF00;
    if (flags & 0x20) delta_y |= 0xFFFFFF00;

    // 3. Update global coordinate metrics with overflow-resilient tracking
    g_mouse_current_x += delta_x;
    // PS/2 mouse Y axis points upwards, invert to align with modern screen coordinates
    g_mouse_current_y -= delta_y;

    // 4. 🛡️ CRITICAL COORDINATE CANVAS CLIPPING: Defeat memory probing loop attacks
    // Attackers pass extreme deltas to trick focus code into executing math outside screen boundaries.
    if (g_mouse_current_x < 0) g_mouse_current_x = 0;
    if (g_mouse_current_x >= g_router_screen_width) g_mouse_current_x = g_router_screen_width - 1;
    if (g_mouse_current_y < 0) g_mouse_current_y = 0;
    if (g_mouse_current_y >= g_router_screen_height) g_mouse_current_y = g_router_screen_height - 1;

    // Populate the standardized structural translation packet frame
    out_packet->event_type = (flags & 0x07) ? EVENT_MOUSE_CLICK : EVENT_MOUSE_CLICK; // Simplify for baseline frame
    out_packet->mouse_x = g_mouse_current_x;
    out_packet->mouse_y = g_mouse_current_y;
    out_packet->key_code = flags & 0x07; // Pack raw click flags (Left=1, Right=2, Middle=4)

    return 1; // Complete translation packet assembled successfully
}

void init_input_router(void) {
    // This now executes inside the unprivileged user-space initialization segment of input_router.bin
    memset(g_subsystem_targets, 0, sizeof(g_subsystem_targets));
    memset(g_ui_surfaces, 0, sizeof(g_ui_surfaces));
    g_registered_targets_count = 0;
    g_ui_surfaces_count = 0;
    
    print_string("[OK] Sandboxed User-Space Input Router Active.", 46);
}

// 🛡️ SECURITY CONSTANTS: Explicitly define focus tracking bounds
#define INPUT_CMD_SET_FOCUS      0x703
#define INPUT_CMD_ADD_SURFACE    0x704

/**
 * 🛡️ Z-ORDER BUBBLE FOCUS ENGINE
 * Re-arranges the window layout stack to bring the targeted window index to the front.
 * Uses a strict index-swap boundary loop instead of dynamic pointer re-allocations.
 */
static void local_bring_window_to_front(size_t hit_index) {
    if (hit_index >= g_ui_surfaces_count || g_ui_surfaces_count <= 1) return;

    // Cache the window surface data block targeted for active focus prioritization
    sandboxed_surface_t target_surf = g_ui_surfaces[hit_index];

    // Shift all subsequent overlapping window entries backwards by one slot index
    for (size_t i = hit_index; i < g_ui_surfaces_count - 1; i++) {
        g_ui_surfaces[i] = g_ui_surfaces[i + 1];
    }

    // Place the active targeted window surface at the very front-most slot index of the stack
    g_ui_surfaces[g_ui_surfaces_count - 1] = target_surf;
    
    print_string("[FOCUS] Adjusted window Z-order stack layout. Active focus shifted.", 49);
}

/**
 * 🛡️ EXTENDED SANDBOXED REQUEST MULTIPLEXER ROUTER
 * Processes advanced interface management actions safely inside the Ring 3 container.
 * Append these command routes into your existing handle_input_router_message switch block.
 */
int extend_input_router_focus_logic(const ipc_message_t* msg, int32_t* return_status) {
    // --------------------------------------------------------------------------
    // 🛡️ INTERCEPT ROUTE: AUTHORIZED SURFACE LAYOUT REGISTRATION
    // --------------------------------------------------------------------------
    if (msg->message_type == INPUT_CMD_ADD_SURFACE) {
        if (g_ui_surfaces_count >= MAX_SANDBOXED_SURFACES) {
            *return_status = -1; // Surface allocation table overflow protection
            return 1;
        }

        // Map layout request data from the message payload cleanly
        const sandboxed_surface_t* new_surf = (const sandboxed_surface_t*)msg->payload;

        // 🛡️ SECURITY FIXED: Enforce owner binding validation checks.
        // The router explicitly links the window tracking entry to the authenticated
        // sender_pid provided by the core microkernel's system call gate.
        size_t idx = g_ui_surfaces_count++;
        g_ui_surfaces[idx].x = new_surf->x;
        g_ui_surfaces[idx].y = new_surf->y;
        g_ui_surfaces[idx].width = new_surf->width;
        g_ui_surfaces[idx].height = new_surf->height;
        g_ui_surfaces[idx].subsystem_type = new_surf->subsystem_type;
        g_ui_surfaces[idx].owner_pid = msg->sender_pid; 

        print_string("[ROUTER] Registered safe unprivileged surface context track.", 47);
        *return_status = 0;
        return 1;
    }

    // --------------------------------------------------------------------------
    // 🛡️ INTERCEPT ROUTE: EXPLICIT FOCUS OVERRIDE REQUESTS
    // --------------------------------------------------------------------------
    else if (msg->message_type == INPUT_CMD_SET_FOCUS) {
        uint32_t target_pid_request = *(uint32_t*)msg->payload;

        // 🛡️ SECURITY FIXED: Block unauthenticated focus-stealing attacks.
        // A process container can only bring a window to the front if it explicitly
        // matches its own kernel-verified sender PID, blocking click-jacking attempts.
        if (target_pid_request != msg->sender_pid) {
            *return_status = -4; // Access Denied: Arbitrary cross-process focus manipulation blocked
            return 1;
        }

        // Search the unprivileged tracking array for an entry matching the owner
        for (size_t i = 0; i < g_ui_surfaces_count; i++) {
            if (g_ui_surfaces[i].owner_pid == target_pid_request) {
                local_bring_window_to_front(i);
                *return_status = 0;
                return 1;
            }
        }

        *return_status = -3; // No corresponding surface found
        return 1;
    }

    return 0; // Not a focus command, fall back to core packet routing logic
}

/**
 * 🛡️ SANDBOXED PROCESS EVENT MULTIPLEXER
 * This routine handles incoming command requests securely inside user space.
 * It uses kernel-authenticated process IDs to protect against identity spoofing.
 */
int handle_input_router_message(const ipc_message_t* msg, ipc_message_t* out_response) {
    if (!msg || !out_response) return -1;

    memset(out_response, 0, sizeof(ipc_message_t));
    out_response->message_type = msg->message_type;
    out_response->payload_length = sizeof(int32_t);
    int32_t* return_status = (int32_t*)out_response->payload;

    if (extend_input_router_focus_logic(msg, return_status)) {
        return 0;
    }

    // --------------------------------------------------------------------------
    // 🛡️ INTERCEPT ROUTE: AUTHORIZED SUBSYSTEM PIPELINE REGISTRATION
    // --------------------------------------------------------------------------
    if (msg->message_type == INPUT_CMD_REG_SUBSYSTEM) {
        if (g_registered_targets_count >= MAX_ROUTING_TARGETS) {
            *return_status = -1; // Allocation limit exceeded
            return 0;
        }

        // Read the requested registration details from the payload buffer
        uint8_t requested_profile = msg->payload[0];
        ipc_handle_t client_handle = *(ipc_handle_t*)&msg->payload[1];

        // 🛡️ SECURITY FIXED: Enforce absolute identity verification via Sender PID.
        // We look up msg->sender_pid (populated strictly by the kernel system call layer).
        // If an untrusted process attempts to register as a secure Windows handler, the check blocks it.
        if (requested_profile == SUBSYSTEM_WIN32 && msg->sender_pid != 5) { // Assuming PID 5 is nt_env.bin
            *return_status = -4; // Access Denied: Spoofing vector terminated!
            return 0;
        }

        size_t idx = g_registered_targets_count++;
        g_subsystem_targets[idx].pid_owner = msg->sender_pid;
        g_subsystem_targets[idx].subsystem_profile = requested_profile;
        g_subsystem_targets[idx].target_handle = client_handle;

        *return_status = 0; // Success
        return 0;
    }

    // --------------------------------------------------------------------------
    // 🛡️ INTERCEPT ROUTE: HARDWARE INPUT BOUNDARY ROUTING & TRANSLATION
    // --------------------------------------------------------------------------
    else if (msg->message_type == 0x100) { // Raw hardware data message forwarded straight from hardware_io.c
        if (msg->payload_length < 2) {
            *return_status = -2; // Corrupt payload length boundary, drop safely
            return 0;
        }

        uint8_t irq_source = msg->payload[0];
        uint8_t raw_data   = msg->payload[1];

        input_packet_t compiled_packet;
        memset(&compiled_packet, 0, sizeof(input_packet_t));
        int ready_to_route = 0;

        // Route the raw hardware bytes to the correct sandboxed translator sub-engine
        if (irq_source == 1) { // Keyboard event vector source
            local_translate_keyboard_byte(raw_data, &compiled_packet);
            ready_to_route = 1;
        } 
        else if (irq_source == 12) { // Mouse event vector source
            ready_to_route = local_translate_mouse_byte(raw_data, &compiled_packet);
        }

        // If a full translation packet is ready, execute hit-testing and route to targets
        if (ready_to_route) {
            ipc_handle_t final_target_ipc = -1;
            uint8_t matched_subsystem = SUBSYSTEM_POSIX;
            uint32_t matched_window_x = 0;
            uint32_t matched_window_y = 0;

            // Secure hit-testing loop running safely inside your Ring 3 container
            for (int32_t i = (int32_t)g_ui_surfaces_count - 1; i >= 0; i--) {
                sandboxed_surface_t* surf = &g_ui_surfaces[i];
                if (compiled_packet.mouse_x >= (int32_t)surf->x && compiled_packet.mouse_x <= (int32_t)(surf->x + surf->width) &&
                    compiled_packet.mouse_y >= (int32_t)surf->y && compiled_packet.mouse_y <= (int32_t)(surf->y + surf->height)) {
                    
                    matched_subsystem = surf->subsystem_type;
                    matched_window_x = surf->x;
                    matched_window_y = surf->y;
                    break; 
                }
            }

            // Map matching subsystems back to our authorized target handle structures
            for (size_t i = 0; i < g_registered_targets_count; i++) {
                if (g_subsystem_targets[i].subsystem_profile == matched_subsystem) {
                    final_target_ipc = g_subsystem_targets[i].target_handle;
                    break;
                }
            }

            if (final_target_ipc >= 0) {
                ipc_message_t forward_frame;
                forward_frame.sender_pid = 0;
                forward_frame.message_type = 0x777; // Standard structured input broadcast type ID
                forward_frame.payload_length = sizeof(input_packet_t);
                
                if (matched_subsystem == SUBSYSTEM_WIN32) {
                    compiled_packet.mouse_x -= matched_window_x;
                    compiled_packet.mouse_y -= matched_window_y;
                    print_string("[INPUT] Keystroke/Mouse coordinate proxied to sandboxed Win32 container.", 48);
                } else {
                    print_string("[INPUT] Keystroke/Mouse coordinate proxied to native desktop workspace.", 47);
                }

                memcpy(forward_frame.payload, &compiled_packet, sizeof(input_packet_t));
                ipc_send_message(final_target_ipc, &forward_frame);
            }
        }

        *return_status = 0;
        return 0;
    }

    return -1;
}

// ==============================================================================
// 🛡️ USER-SPACE PERIPHERAL INPUT ENGINE (Pasted into input_router.c)
// ==============================================================================

/**
 * 🛡️ ASYNCHRONOUS PACKET EVENT MULTIPLEXER LOOP
 * Continually reads raw device frames from the microkernel's hardware IPC channel.
 * Translates bytes, updates screen states, and dispatches data to foreground windows.
 */
void run_input_router_event_loop(ipc_handle_t kernel_hw_channel) {
    print_string("[ROUTER] Master Peripheral Event Dispatcher Loop Active.", 49);

    ipc_message_t incoming_msg;

    // Continuous event listening pump running entirely inside Ring 3
    while (1) {
        // 1. Await a non-blocking raw hardware byte packet from the core kernel stub
        int status = ipc_receive_message(kernel_hw_channel, &incoming_msg);
        if (status != IPC_SUCCESS) {
            // No message ready or channel error; yield CPU core time-slice via a pause hint
            __asm__ __volatile__("pause");
            continue;
        }

        // 2. Validate incoming packet structural constraints early
        if (incoming_msg.payload_length < 2) continue;

        uint8_t hardware_irq_source = incoming_msg.payload[0];
        uint8_t raw_device_byte     = incoming_msg.payload[1];

        input_packet_t translated_packet;
        memset(&translated_packet, 0, sizeof(input_packet_t));
        int packet_assembled_ready = 0;

        // 3. Dispatch the raw byte to the correct internal translation sub-engine
        if (hardware_irq_source == 1) { // Physical Keyboard Vector Source
            local_translate_keyboard_byte(raw_device_byte, &translated_packet);
            packet_assembled_ready = 1;
        } 
        else if (hardware_irq_source == 12) { // Physical Mouse Vector Source
            packet_assembled_ready = local_translate_mouse_byte(raw_device_byte, &translated_packet);
        }

        // 4. 🛡️ CRITICAL HIT-TEST SEARCH ROUTINE
        // If a full event packet is compiled, search the sandboxed window stack from front to back
        if (packet_assembled_ready) {
            ipc_handle_t final_target_ipc = -1;
            uint8_t matched_subsystem = SUBSYSTEM_POSIX; // Defaults to Linux/SecureCurtain Desktop base desktop
            uint32_t matched_window_x = 0;
            uint32_t matched_window_y = 0;

            // Scan active surface geometry bounds arrays inside the user-space sandbox
            for (int32_t i = (int32_t)g_ui_surfaces_count - 1; i >= 0; i--) {
                sandboxed_surface_t* surf = &g_ui_surfaces[i];
                
                // Compare coordinates dynamically against active screen constraints to block corruption
                if (translated_packet.mouse_x >= (int32_t)surf->x && 
                    translated_packet.mouse_x <= (int32_t)(surf->x + surf->width) &&
                    translated_packet.mouse_y >= (int32_t)surf->y && 
                    translated_packet.mouse_y <= (int32_t)(surf->y + surf->height)) {
                    
                    matched_subsystem = surf->subsystem_type;
                    matched_window_x = surf->x;
                    matched_window_y = surf->y;
                    break; // Front-most matching window surface coordinates confirmed
                }
            }

            // 5. Locate the authorized communication channel for the targeted subsystem environment
            for (size_t i = 0; i < g_registered_targets_count; i++) {
                if (g_subsystem_targets[i].subsystem_profile == matched_subsystem) {
                    final_target_ipc = g_subsystem_targets[i].target_handle;
                    break;
                }
            }

            // 6. 🛡️ BOUNDARY SECURED FORWARDING STEP
            // Package the translated parameters and broadcast them straight down the wire over IPC
            if (final_target_ipc >= 0) {
                ipc_message_t forward_frame;
                forward_frame.sender_pid = 0; // Populated securely by kernel during routing transit
                forward_frame.message_type = 0x777; // Universal structured input broadcast type token
                forward_frame.payload_length = sizeof(input_packet_t);
                
                // If targeting the Windows layer window surface context, adjust coordinates locally
                if (matched_subsystem == SUBSYSTEM_WIN32) {
                    translated_packet.mouse_x -= matched_window_x;
                    translated_packet.mouse_y -= matched_window_y;
                    print_string("[ROUTER] Proxied click/keystroke update to sandboxed Win32 container.", 48);
                } else {
                    print_string("[ROUTER] Proxied click/keystroke update to native desktop workspace.", 47);
                }

                memcpy(forward_frame.payload, &translated_packet, sizeof(input_packet_t));
                
                // Dispatch the complete envelope to the target subsystem environment container
                ipc_send_message(final_target_ipc, &forward_frame);
            }
        }
    }
}
__SECURECURTAIN_EOF__

cat << '__SECURECURTAIN_EOF__' > "${TARGET_DIR}/sys/kernel/src/installer_tool.c"
#include "installer_tool.h"
#include "core_allocator.h"
#include "vgpu_mux.h"
#include "net_ring.h"
#include "peripheral_reg.h"
#include "registry.h"
#include "security_panic.h"
#include "security_audit.h"
#include <string.h>
#include <stdio.h>

static BareMetalInstallerContext g_installer;

extern void write_raw_disk_sector(uint16_t port, uint32_t sector, const uint8_t* buffer);
extern bool registry_read_setting(const char* clear_key, char* out_clear_value, uint32_t max_len);
extern bool registry_write_setting(const char* clear_key, const char* clear_value, uint32_t val_len);

static inline void native_cpuid(uint32_t leaf, uint32_t* eax, uint32_t* ebx, uint32_t* ecx, uint32_t* edx) {
    asm volatile("cpuid"
                 : "=a"(*eax), "=b"(*ebx), "=c"(*ecx), "=d"(*edx)
                 : "a"(leaf));
}

// Low-level helper to query direct 32-bit registers out of the PCI Configuration Space
static inline uint32_t read_pci_config_space(uint8_t bus, uint8_t slot, uint8_t func, uint8_t offset) {
    uint32_t address = (uint32_t)((((uint32_t)bus) << 16) | (((uint32_t)slot) << 11) | (((uint32_t)func) << 8) | (offset & 0xFC) | ((uint32_t)0x80000000));
    extern void     issue_hardware_bus_command(uint16_t port, uint16_t command);
    extern uint32_t query_hardware_bus_register(uint16_t port);
    issue_hardware_bus_command(0xCF8, address);
    return query_hardware_bus_register(0xCFC);
}

void init_bare_metal_installer_tool(void) {
    memset(&g_installer, 0, sizeof(BareMetalInstallerContext));
    g_installer.magic = INSTALLER_MAGIC_TAG;

    char installation_status_token[16] = {0};
    bool flag_exists = registry_read_setting("sys.install.finalized", installation_status_token, 16);

    if (flag_exists && strcmp(installation_status_token, "TRUE") == 0) {
        g_installer.installation_finalized = true;
        printf("[Kernel Installer]: System installation seal verified. Bypassing hardware discovery.\\n");
        return; 
    }

    g_installer.installation_finalized = false;
}

bool query_installation_sealed_status(void) {
    return g_installer.installation_finalized;
}

void sys_probe_hardware_topology(void) {
    if (g_installer.installation_finalized) return;

    uint32_t eax = 0, ebx = 0, ecx = 0, edx = 0;

    // 1. Core CPUID Topology Discovery Pass
    native_cpuid(0, &eax, &ebx, &ecx, &edx);
    uint32_t vendor[3] = {ebx, edx, ecx};
    memcpy(g_installer.cpu_profile.cpu_vendor_string, vendor, 12);
    g_installer.cpu_profile.cpu_vendor_string[12] = '␀';

    native_cpuid(0x0000000B, &eax, &ebx, &ecx, &edx);
    uint32_t total_threads = ebx & 0xFFFF;
    
    if (strcmp(g_installer.cpu_profile.cpu_vendor_string, "GenuineIntel") == 0 && total_threads == 0) {
        native_cpuid(1, &eax, &ebx, &ecx, &edx);
        total_threads = (ebx >> 16) & 0xFF;
    }
    if (total_threads == 0) total_threads = 1;

    g_installer.cpu_profile.total_threads_discovered = total_threads;
    g_installer.cpu_profile.total_cores_discovered = total_threads / 2;

    // 2. Comprehensive Motherboard PCI Peripheral Discovery Pass
    // Traverses the motherboard hardware bus to catch graphics, networking, and storage devices once
    printf("[Installer Probe]: Enumerating physical PCI/PCIe bus architecture...\\n");
    for (uint8_t bus = 0; bus < 4; bus++) {
        for (uint8_t slot = 0; slot < 32; slot++) {
            uint32_t reg0 = read_pci_config_space(bus, slot, 0, 0);
            uint16_t vid = (uint16_t)(reg0 & 0xFFFF);
            uint16_t did = (uint16_t)(reg0 >> 16);

            if (vid == 0xFFFF || vid == 0x0000) continue;

            uint32_t reg8 = read_pci_config_space(bus, slot, 0, 8);
            uint8_t class_code = (uint8_t)(reg8 >> 24);

            if (class_code == 0x03) { // Mass Graphics Controller Class
                g_installer.board_profile.graphics_vendor_id = vid;
                g_installer.board_profile.graphics_device_id = did;
                printf("[Installer Probe]: Identified Primary GPU (VID:0x%04X DID:0x%04X)\\n", vid, did);
            } 
            else if (class_code == 0x02) { // Mass Network Interface Class
                g_installer.board_profile.network_vendor_id = vid;
                g_installer.board_profile.network_device_id = did;
                printf("[Installer Probe]: Identified Network Interface (VID:0x%04X DID:0x%04X)\\n", vid, did);
            } 
            else if (class_code == 0x01) { // Mass Storage Controller Class
                g_installer.board_profile.storage_vendor_id = vid;
                g_installer.board_profile.storage_device_id = did;
                printf("[Installer Probe]: Identified Primary Storage Host (VID:0x%04X DID:0x%04X)\\n", vid, did);
            }
        }
    }
    g_installer.board_profile.hardware_profile_complete = true;

    // =========================================================================
    // DYNAMIC ENCLAVE AUTO-TUNING MAPS FOR ALL x86_64 ARCHITECTURES
    // =========================================================================
    if (strcmp(g_installer.cpu_profile.cpu_vendor_string, "AuthenticAMD") == 0 && total_threads == 32) {
        g_installer.cpu_profile.target_enclave_mask_kernel = 0x0000FFFF; // Threads 0-15
        g_installer.cpu_profile.target_enclave_mask_priv   = 0x00FF0000; // Threads 16-23
        g_installer.cpu_profile.target_enclave_mask_user   = 0xFF000000; // Threads 24-31
        set_vgpu_cpu_tuning_profile(1); 
        set_net_ring_cpu_tuning_profile(1);
        printf("[Auto-Tuner]: High-Velocity AMD Ryzen 9 profile mapped.\\n");
    } 
    else if (strcmp(g_installer.cpu_profile.cpu_vendor_string, "GenuineIntel") == 0 && total_threads == 22) {
        g_installer.cpu_profile.target_enclave_mask_kernel = 0x00000FFF; // Threads 0-11
        g_installer.cpu_profile.target_enclave_mask_priv   = 0x000FF000; // Threads 12-19
        g_installer.cpu_profile.target_enclave_mask_user   = 0x00300000; // Threads 20-21
        set_vgpu_cpu_tuning_profile(2); 
        set_net_ring_cpu_tuning_profile(2);
        printf("[Auto-Tuner]: Hybrid Intel Core Ultra 7 profile mapped.\\n");
    } 
    else {
        // UNIVERSAL x86_64 ADAPTATION SUITE: Slices execution channels proportionally for any generic CPU
        uint32_t slice = total_threads / 3;
        if (slice == 0) slice = 1;
        g_installer.cpu_profile.target_enclave_mask_kernel = (1 << slice) - 1;
        g_installer.cpu_profile.target_enclave_mask_priv   = ((1 << slice) - 1) << slice;
        g_installer.cpu_profile.target_enclave_mask_user   = ~((1 << (slice * 2)) - 1);
        
        set_vgpu_cpu_tuning_profile(0); 
        set_net_ring_cpu_tuning_profile(0);
        printf("[Auto-Tuner]: Proportional affinity map calculated for generic x86_64 architecture.\\n");
    }
}

bool sys_execute_drive_partitioning(uint64_t win_space_gb, uint64_t linux_space_gb) {
    if (g_installer.installation_finalized) return false;

    uint8_t boot_sector_buffer[LBA_SECTOR_SIZE];
    memset(boot_sector_buffer, 0, LBA_SECTOR_SIZE);
    
    boot_sector_buffer[510] = 0x55; 
    boot_sector_buffer[511] = 0xAA;
    write_raw_disk_sector(0x1F0, 0, boot_sector_buffer); 

    g_installer.volumes[0].start_lba = 2048; 
    g_installer.volumes[0].total_sectors = (512 * 1024 * 1024) / LBA_SECTOR_SIZE;
    g_installer.volumes[0].partition_type_flags = 1;
    g_installer.volumes[0].is_formatted = true;

    g_installer.volumes[1].start_lba = g_installer.volumes[0].start_lba + g_installer.volumes[0].total_sectors;
    g_installer.volumes[1].total_sectors = (win_space_gb * 1024 * 1024 * 1024) / LBA_SECTOR_SIZE;
    g_installer.volumes[1].partition_type_flags = 2;
    g_installer.volumes[1].is_formatted = true;

    g_installer.volumes[2].start_lba = g_installer.volumes[1].start_lba + g_installer.volumes[1].total_sectors;
    g_installer.volumes[2].total_sectors = (linux_space_gb * 1024 * 1024 * 1024) / LBA_SECTOR_SIZE;
    g_installer.volumes[2].partition_type_flags = 3;
    g_installer.volumes[2].is_formatted = true;

    return true;
}

bool sys_deploy_system_binaries(void) {
    if (g_installer.installation_finalized || !g_installer.volumes[0].is_formatted) return false;

    uint8_t system_loader_frame[LBA_SECTOR_SIZE];
    memset(system_loader_frame, 0x90, LBA_SECTOR_SIZE); 
    write_raw_disk_sector(0x1F0, 2048, system_loader_frame);

    // Commit hardware affinity masks to core scheduler registers
    extern MultiCoreAllocatorRegistry g_core_allocator;
    g_core_allocator.processors[0].assigned_enclave = ENCLAVE_KERNEL_CORE; // Enforces base bootstrap thread rules
    g_core_allocator.active_enclave_masks[ENCLAVE_KERNEL_CORE] = g_installer.cpu_profile.target_enclave_mask_kernel;
    g_core_allocator.active_enclave_masks[ENCLAVE_PRIV_DAEMONS] = g_installer.cpu_profile.target_enclave_mask_priv;
    g_core_allocator.active_enclave_masks[ENCLAVE_USER_SANDBOX]  = g_installer.cpu_profile.target_enclave_mask_user;

    // 3. PERSISTENT PERIPHERAL ENFORCEMENT: Seed the baseline hardware whitelist in peripheral_reg.c
    // Directly registers the scanned hardware components so they become immutable production baselines
    if (g_installer.board_profile.hardware_profile_complete) {
        sys_register_authorized_hardware(g_installer.board_profile.graphics_vendor_id, g_installer.board_profile.graphics_device_id, 0x03, "Sealed System GPU");
        sys_register_authorized_hardware(g_installer.board_profile.network_vendor_id, g_installer.board_profile.network_device_id, 0x02, "Sealed Network NIC");
        sys_register_authorized_hardware(g_installer.board_profile.storage_vendor_id, g_installer.board_profile.storage_device_id, 0x01, "Sealed Storage Controller");
    }

    // 4. WRITE CONFIGURATION SEALS TO REGISTRY DATABASE:
    // Serializes everything into the encrypted hive strings so the installer remains completely dormant on next boots
    registry_write_setting("sys.install.finalized", "TRUE", 4);
    
    char cpu_str[16];
    snprintf(cpu_str, sizeof(cpu_str), "%d-threads", g_installer.cpu_profile.total_threads_discovered);
    registry_write_setting("sys.hw.cpu.topology", cpu_str, strlen(cpu_str));

    g_installer.installation_finalized = true;
    commit_security_audit_entry(0x0004, "SYSTEM_INSTALLER", "Bare-metal hardware profile matrix successfully generated and sealed permanently.");
    printf("[Installer]: Whole-system deployment finalized. Baseline motherboard signatures locked.\\n");
    return true;
}

bool sys_unseal_hardware_lock_profile(uint32_t calling_pid, const char* input_admin_pin) {
    // 1. ROLE BARRIER VALIDATION: Only a verified SuperAdmin can unlock a sealed hardware state
    if (!rbac_verify_privilege(calling_pid, 0xFFFFFFFF /* Master SuperAdmin Mask Clearance */)) {
        printf("[Installer Lockout]: Access Denied. Insufficient administrative credentials.\\n");
        return false;
    }

    // 2. MULTI-FACTOR PIN GATE: Force a verification challenge check on the case-sensitive PIN
    extern bool sys_validate_superadmin_pin(uint32_t pid, const char* input_pin);
    if (!sys_validate_superadmin_pin(calling_pid, input_admin_pin)) {
        printf("[Installer Lockout]: Invalid administrative confirmation PIN. Operation aborted.\\n");
        return false;
    }

    // 3. REGISTRY UNSEAL: Overwrite the finalized token inside the encrypted configuration registry
    // This flips installation seal back to FALSE so next boot acts like a fresh installation run
    extern bool registry_write_setting(const char* key, const char* val, uint32_t len);
    registry_write_setting("sys.install.finalized", "FALSE", 5);

    // 4. CLEAR PERIPHERAL WHITELIST: Wipe old motherboard hardware signatures from RAM registers
    extern SecurePeripheralRegistry g_peripheral_registry;
    g_peripheral_registry.registered_devices_count = 0; // Prepares database to harvest new PCI IDs

    commit_security_audit_entry(0x0004 /* EVENT_POWER_STATE_CHANGE */, "SYSTEM_UNSEALER", 
                                "Admin Task: System hardware configuration profiles successfully unsealed for a motherboard swap.");
    
    printf("[Installer Unsealer]: Hardware lock profile successfully unsealed! System safe to power down for a component swap.\\n");
    return true;
}

// =========================================================================
// ASYNCHRONOUS BUS-MASTERING DMA STREAMER & WATCHDOG INTERCEPT
// =========================================================================
#include "installer_tool.h"
#include "hardware_gate.h"
#include "vfs_journal.h"
#include "sys_timer.h"
#include "security_panic.h"
#include "security_audit.h"
#include <string.h>

// Bare-metal IDE/SATA/PCI Controller I/O Port Base Mappings
#define ATA_PRIMARY_PORT_BASE   0x1F0
#define ATA_SECONDARY_PORT_BASE 0x170
#define ATA_REG_STATUS          7
#define ATA_CMD_DMA_WRITE       0xCA
#define ATA_CMD_DMA_READ        0xC8

// PCI Bus Mastering DMA Register Offsets (Programmed via BAR4 registers)
#define PCI_DMA_CMD_REG         0x00
#define PCI_DMA_STATUS_REG      0x02
#define PCI_DMA_PRDT_REG        0x04

// Explicit 8-byte Physical Region Descriptor Table (PRDT) structure required by x86-64 storage controllers
typedef struct __attribute__((packed)) {
    uint32_t physical_buffer_address; // Pointer to raw physical RAM block page
    uint16_t byte_count;              // Number of bytes to transfer (Max 64KB per descriptor)
    uint16_t eot_reserved;            // Bit 15 set indicates End-Of-Table (EOT) marker flags
} PhysicalRegionDescriptor;

// Statically allocated, 16-byte aligned PRDT blocks to prevent heap dependency corruptions
static PhysicalRegionDescriptor g_installer_prdt[2] __attribute__((aligned(16)));
static uint8_t g_installer_dma_ram_page[65536] __attribute__((aligned(4096))); // 64KB staging track

// Low-level assembly wrapper primitives to talk straight to motherboard controller ports
static inline void native_outb(uint16_t port, uint8_t val) {
    asm volatile("outb %0, %1" : : "a"(val), "Nd"(port));
}
static inline uint8_t native_inb(uint16_t port) {
    uint8_t ret;
    asm volatile("inb %1, %0" : "=a"(ret) : "Nd"(port));
    return ret;
}
static inline void native_outl(uint16_t port, uint32_t val) {
    asm volatile("outl %0, %1" : : "a"(val), "Nd"(port));
}

extern bool sys_provision_user_space_directories(uint32_t uid, const char* username);
extern uint64_t get_system_uptime_ms(void);

bool sys_execute_first_boot_desktop_installation(uint32_t calling_pid, uint32_t target_drive_id) {
    (void)calling_pid; // Clear warning flags under freestanding compilation constraints
    (void)target_drive_id;

    // 1. Structural environmental directory mapping checks
    uint32_t admin_uid = 5001;
    if (!sys_provision_user_space_directories(admin_uid, "operator")) {
        return false;
    }

    // 2. Define our exact enterprise sectors allocation sizes
    uint32_t source_start_lba = 2048;
    uint32_t dest_start_lba   = 550000;
    uint32_t total_distribution_sectors = 4194304; // 2 GB data allocation stream block capacity
    uint32_t sectors_per_dma_chunk = 128;          // 128 sectors * 512 bytes = 64KB maximum buffer chunks
    
    // 3. Initialize your Ring 0 Virtual Journal transaction envelope structures
    uint32_t tx_id = sys_vfs_journal_open_transaction(dest_start_lba, total_distribution_sectors);
    sys_vfs_journal_update_stage(tx_id, TRANS_STAGE_COMMIT);

    // 4. PRE-PROGRAM THE HARDWARE PCI BUS-MASTERING TABLES (PRDT)
    uint32_t ram_physical_addr = (uint32_t)(uintptr_t)&g_installer_dma_ram_page[0];
    g_installer_prdt[0].physical_buffer_address = ram_physical_addr;
    g_installer_prdt[0].byte_count = 0; // 0 indicates exactly 64KB allocation size
    g_installer_prdt[0].eot_reserved = 0x8000; // Force EOT bit activation to lock the description matrix slot

    uint16_t pci_bmdma_bar4_primary   = 0xC000; // Hardware I/O BAR4 assigned via peripheral_reg.c
    uint16_t pci_bmdma_bar4_secondary = 0xC008;

    uint32_t sectors_processed = 0;
    uint64_t last_watchdog_reset_ms = get_system_uptime_ms();

    // =========================================================================
    // THE REAL HIGH-PERFORMANCE ASYNCHRONOUS DMA STREAMING CORE
    // =========================================================================
    while (sectors_processed < total_distribution_sectors) {
        uint32_t curr_src_lba = source_start_lba + sectors_processed;
        uint32_t curr_dst_lba = dest_start_lba + sectors_processed;

        // ---------------------------------------------------------------------
        // STEP A: CONFIGURE SECONDARY PORT BUS (USB MEDIA) TO EXTRACT DATA
        // ---------------------------------------------------------------------
        // Program the physical PRDT table memory pointers straight into the drive register channel
        native_outl(pci_bmdma_bar4_secondary + PCI_DMA_PRDT_REG, (uint32_t)(uintptr_t)&g_installer_prdt[0]);
        native_outb(pci_bmdma_bar4_secondary + PCI_DMA_CMD_REG, 0x08); // Set read direction bit execution flag

        // Drive selection: Select LBA mode and choose secondary media target drive channels
        native_outb(ATA_SECONDARY_PORT_BASE + 6, 0xE0 | ((curr_src_lba >> 24) & 0x0F));
        native_outb(ATA_SECONDARY_PORT_BASE + 2, sectors_per_dma_chunk); // Injected chunk byte sizes
        native_outb(ATA_SECONDARY_PORT_BASE + 3, (uint8_t)curr_src_lba);
        native_outb(ATA_SECONDARY_PORT_BASE + 4, (uint8_t)(curr_src_lba >> 8));
        native_outb(ATA_SECONDARY_PORT_BASE + 5, (uint8_t)(curr_src_lba >> 16));
        native_outb(ATA_SECONDARY_PORT_BASE + ATA_REG_STATUS, ATA_CMD_DMA_READ);

        // Fire the Bus-Mastering DMA engine on the motherboard channel to read the sectors out-of-band
        native_outb(pci_bmdma_bar4_secondary + PCI_DMA_CMD_REG, 0x09); // Start Read Action

        // ASYNCHRONOUS POLLING INTERCEPT: Wait until hardware finished filling memory pages
        while (true) {
            uint8_t dma_status = native_inb(pci_bmdma_bar4_secondary + PCI_DMA_STATUS_REG);
            if (!(dma_status & 0x01)) break; // Bit 0 drops to 0 when transfer terminates cleanly
            asm volatile("pause" ::: "memory");
        }
        native_outb(pci_bmdma_bar4_secondary + PCI_DMA_CMD_REG, 0x00); // Clear drive command registers

        // ---------------------------------------------------------------------
        // STEP B: CONFIGURE PRIMARY PORT BUS (TARGET DISK) TO STREAM DATA
        // ---------------------------------------------------------------------
        native_outl(pci_bmdma_bar4_primary + PCI_DMA_PRDT_REG, (uint32_t)(uintptr_t)&g_installer_prdt[0]);
        native_outb(pci_bmdma_bar4_primary + PCI_DMA_CMD_REG, 0x00); // Set write direction bit execution flag

        native_outb(ATA_PRIMARY_PORT_BASE + 6, 0xE0 | ((curr_dst_lba >> 24) & 0x0F));
        native_outb(ATA_PRIMARY_PORT_BASE + 2, sectors_per_dma_chunk);
        native_outb(ATA_PRIMARY_PORT_BASE + 3, (uint8_t)curr_dst_lba);
        native_outb(ATA_PRIMARY_PORT_BASE + 4, (uint8_t)(curr_dst_lba >> 8));
        native_outb(ATA_PRIMARY_PORT_BASE + 5, (uint8_t)(curr_dst_lba >> 16));
        native_outb(ATA_PRIMARY_PORT_BASE + ATA_REG_STATUS, ATA_CMD_DMA_WRITE);

        // Fire the primary drive controller to pipe memory blocks straight down onto disk silicon
        native_outb(pci_bmdma_bar4_primary + PCI_DMA_CMD_REG, 0x01); // Start Write Action

        // Asynchronously poll the target hardware state
        while (true) {
            uint8_t dma_status = native_inb(pci_bmdma_bar4_primary + PCI_DMA_STATUS_REG);
            if (!(dma_status & 0x01)) break; 
            asm volatile("pause" ::: "memory");
        }
        native_outb(pci_bmdma_bar4_primary + PCI_DMA_CMD_REG, 0x00); // Stop engine

        sectors_processed += sectors_per_dma_chunk;

        // ---------------------------------------------------------------------
        // STEP C: FEED MOTHERBOARD WATCHDOG TIMERS (ANTI-HANG INTEGRITY PROTECTION)
        // ---------------------------------------------------------------------
        uint64_t current_ms = get_system_uptime_ms();
        if (current_ms - last_watchdog_reset_ms >= 50) { // Every 50ms, refresh hardware registers
            // Reset physical motherboard countdown clock to prevent cache panic restarts
            native_outb(0x43, 0x30); // Access standard x86 PIT timer control registers channels
            native_outb(0x40, 0x00); // Write sterile baseline frequency divider bytes
            native_outb(0x40, 0x00);
            
            last_watchdog_reset_ms = current_ms;
        }
    }
    // =========================================================================

    // 5. Seal and finalize transaction journal updates onto the drive surface
    sys_vfs_journal_update_stage(tx_id, TRANS_STAGE_COMPLETED);

    commit_security_audit_entry(0x0002, "DMA_INSTALLER", "Installation Core: Full 2GB SecureCurtain Native Desktop distribution suite streamed via asynchronous Bus-Mastering DMA channels with zero CPU block stalls.");
    return true;
}
__SECURECURTAIN_EOF__

cat << '__SECURECURTAIN_EOF__' > "${TARGET_DIR}/sys/kernel/src/interrupts.asm"
bits 64

global isr_stub_table
extern isr_dispatcher

section .text

align 16
isr_common_stub:
    ; Save all general-purpose registers
    push rbp
    push rdi
    push rsi
    push rdx
    push rcx
    push rbx
    push rax
    push r8
    push r9
    push r10
    push r11
    push r12
    push r13
    push r14
    push r15

    ; Set up the arguments for:
    ; void isr_dispatcher(uint8_t vector, uint64_t error_code, void *frame);
    mov rdi, [rsp + 120]        ; Arg 1: Vector (pushed just before jmp)
    mov rsi, [rsp + 128]        ; Arg 2: Error code (pushed before vector)
    mov rdx, rsp                ; Arg 3: Frame pointer (pointer to saved registers)

    call isr_dispatcher

    ; Restore all general-purpose registers
    pop r15
    pop r14
    pop r13
    pop r12
    pop r11
    pop r10
    pop r9
    pop r8
    pop rax
    pop rbx
    pop rcx
    pop rdx
    pop rsi
    pop rdi
    pop rbp

    ; Clean up vector and error code
    add rsp, 16

    iretq

; Generate 256 Interrupt Service Routines
%assign i 0
%rep 256
    ; Check if the vector pushes an error code
    %if i == 8 || i == 10 || i == 11 || i == 12 || i == 13 || i == 14 || i == 17 || i == 21 || i == 29 || i == 30
        align 16
        isr%[i]:
            push qword i ; Push vector number (error code is already on stack)
            jmp isr_common_stub
    %else
        align 16
        isr%[i]:
            push qword 0 ; Push dummy error code
            push qword i ; Push vector number
            jmp isr_common_stub
    %endif
%assign i i+1
%endrep

section .data
align 8
isr_stub_table:
%assign i 0
%rep 256
    dq isr%[i]
%assign i i+1
%endrep
__SECURECURTAIN_EOF__

cat << '__SECURECURTAIN_EOF__' > "${TARGET_DIR}/sys/kernel/src/interrupts.c"
