cat << '__SECURECURTAIN_EOF__' > "${TARGET_DIR}/sys/kernel/src/ipc.c"
#include "ipc.h"
#include "syscall.h" // Needed to import the is_user_buffer_safe helper

// A secure, internal kernel handle table mapping IDs to safe structures
#define MAX_IPC_CHANNELS 256

typedef struct {
    uint8_t       buffer[4096]; // Expanded for structured message frames
    size_t        head;
    size_t        tail;
    size_t        count;
    uint32_t      owner_pid;    // Tracks which process is authorized to use this channel
    volatile uint32_t lock;     // Kernel-controlled lock variable
} kernel_ipc_channel_t;

// The actual channel memory is stored safely INSIDE kernel space, hidden from user access
static kernel_ipc_channel_t g_kernel_channels[MAX_IPC_CHANNELS];

// Internal Atomic Spinlock with an escape mechanism to prevent CPU lockups
static int secure_spinlock_lock(volatile uint32_t* lock) {
    uint64_t timeout = 1000000; // Define a strict safety loop iteration limit
    while (__sync_lock_test_and_set(lock, 1)) {
        __asm__ __volatile__("pause");
        if (--timeout == 0) {
            return 0; // Failed to acquire lock safely, prevent system-wide lockup
        }
    }
    return 1; 
}

static void secure_spinlock_unlock(volatile uint32_t* lock) {
    __sync_lock_release(lock);
}

// 🛡️ SECURITY: Validates whether a handle is valid and belongs to the caller
static kernel_ipc_channel_t* validate_and_get_channel(ipc_handle_t handle, uint32_t calling_pid) {
    if (handle < 0 || handle >= MAX_IPC_CHANNELS) {
        return NULL;
    }
    
    kernel_ipc_channel_t* chan = &g_kernel_channels[handle];
    
    // Ensure the channel has been initialized and belongs to this process
    if (chan->owner_pid == 0 || chan->owner_pid != calling_pid) {
        return NULL; 
    }
    
    return chan;
}

int ipc_send_message(ipc_handle_t handle, const ipc_message_t* msg) {
    // 1. Fetch calling PID securely from active process structures (Mocked here as PID 2)
    uint32_t active_pid = 2; 

    // 2. Verify the handle and validate the user-space payload pointer
    kernel_ipc_channel_t* chan = validate_and_get_channel(handle, active_pid);
    if (!chan) return IPC_ERR_INVALID_HDL;

    // Use our global memory bound check to ensure msg lives entirely in user-space
    if (!is_user_buffer_safe((void*)msg, sizeof(ipc_message_t))) return IPC_ERR_ACCESS_DENIED;

    if (!secure_spinlock_lock(&chan->lock)) return IPC_ERR_ACCESS_DENIED;

    // 3. Ensure the message frame will fit into the message buffer
    if (chan->count + sizeof(ipc_message_t) > sizeof(chan->buffer)) {
        secure_spinlock_unlock(&chan->lock);
        return IPC_ERR_BUFFER_FULL;
    }

    // 4. Safely copy the packet data into the kernel ring buffer
    uint8_t* byte_ptr = (uint8_t*)msg;
    for (size_t i = 0; i < sizeof(ipc_message_t); i++) {
        chan->buffer[chan->head] = byte_ptr[i];
        chan->head = (chan->head + 1) % sizeof(chan->buffer);
    }
    chan->count += sizeof(ipc_message_t);

    secure_spinlock_unlock(&chan->lock);
    return IPC_SUCCESS;
}

int ipc_receive_message(ipc_handle_t handle, ipc_message_t* out_msg) {
    uint32_t active_pid = 2; 

    kernel_ipc_channel_t* chan = validate_and_get_channel(handle, active_pid);
    if (!chan) return IPC_ERR_INVALID_HDL;

    // Verify destination pointer is safe to write to and belongs to user space
    if (!is_user_buffer_safe((void*)out_msg, sizeof(ipc_message_t))) return IPC_ERR_ACCESS_DENIED;

    if (!secure_spinlock_lock(&chan->lock)) return IPC_ERR_ACCESS_DENIED;

    if (chan->count < sizeof(ipc_message_t)) {
        secure_spinlock_unlock(&chan->lock);
        return IPC_ERR_BUFFER_EMPTY;
    }

    // 5. Securely reconstruct the message back into user memory
    uint8_t* dest_ptr = (uint8_t*)out_msg;
    for (size_t i = 0; i < sizeof(ipc_message_t); i++) {
        dest_ptr[i] = chan->buffer[chan->tail];
        chan->tail = (chan->tail + 1) % sizeof(chan->buffer);
    }
    chan->count -= sizeof(ipc_message_t);

    // 6. Overwrite the sender PID field with the AUTHENTIC PID validated by the kernel
    out_msg->sender_pid = active_pid;

    secure_spinlock_unlock(&chan->lock);
    return IPC_SUCCESS;
}

int ipc_map_shared_memory(ipc_handle_t handle, void* target_virtual_addr, size_t page_count, uint32_t flags) {
    uint32_t active_pid = 2;
    kernel_ipc_channel_t* chan = validate_and_get_channel(handle, active_pid);
    if (!chan) return IPC_ERR_INVALID_HDL;

    // Verify destination pointer sits safely inside user space
    if (!is_user_buffer_safe(target_virtual_addr, page_count * 4096)) {
        return IPC_ERR_ACCESS_DENIED;
    }

    // Map shared memory frames between isolated modules securely
    return IPC_SUCCESS;
}
__SECURECURTAIN_EOF__

cat << '__SECURECURTAIN_EOF__' > "${TARGET_DIR}/sys/kernel/src/ipc_gate.c"
#include "ipc_gate.h"
#include "sandbox_watchdog.h"
#include "sandbox.h"
#include "pm_core.h"
#include <string.h>
#include <stdio.h>

static IpcGateControlRegistry g_ipc_gate;

extern SwapCryptoContext g_hibernation_crypto;

// Generate process-specific cryptographic streams to isolate message footprints inline
static void ipc_crypto_transform(uint32_t pid_seed, const uint8_t* input, uint8_t* output, uint32_t length) {
    for (uint32_t i = 0; i < length; i++) {
        // Compound the core transient kernel key with localized application PIDs
        uint8_t seed_byte = (uint8_t)((pid_seed >> (i % 4 * 8)) & 0xFF);
        uint8_t master_key_byte = g_hibernation_crypto.key_buffer[i % SWAP_ENCRYPTION_KEY_SIZE];
        
        output[i] = input[i] ^ master_key_byte ^ seed_byte;
    }
}

void init_ipc_gate_subsystem(void) {
    memset(&g_ipc_gate, 0, sizeof(IpcGateControlRegistry));
    g_ipc_gate.total_allocated_channels = 0;
    printf("[Kernel IPC Gate]: Cross-sandbox transactional routing matrix operational.\\n");
}

int32_t open_secure_ipc_channel(uint32_t source_pid, uint32_t dest_pid) {
    if (g_ipc_gate.total_allocated_channels >= IPC_MAX_CHANNELS) return -1;

    uint32_t channel_idx = g_ipc_gate.total_allocated_channels;
    IpcChannelNode* chan = &g_ipc_gate.channels[channel_idx];

    chan->channel_id = channel_idx + 500; // Unique secure channel tracking ID descriptor
    chan->source_pid = source_pid;
    chan->dest_pid = dest_pid;
    chan->has_message = false;
    chan->is_locked = false;

    g_ipc_gate.total_allocated_channels++;
    printf("[Kernel IPC]: Opened secure communication gate channel %d (%d -> %d)\\n", chan->channel_id, source_pid, dest_pid);
    return (int32_t)chan->channel_id;
}

bool sys_ipc_send_secure_message(uint32_t channel_id, uint32_t sender_pid, const uint8_t* clear_data, uint32_t length) {
    if (length > IPC_PAYLOAD_SIZE) return false;

    if (!sys_watchdog_log_ipc_transaction(sender_pid)) {
        return false;
    }

    for (uint32_t i = 0; i < g_ipc_gate.total_allocated_channels; i++) {
        IpcChannelNode* chan = &g_ipc_gate.channels[i];

        if (chan->channel_id == channel_id && chan->source_pid == sender_pid) {
            if (chan->has_message || chan->is_locked) return false; // Channel pipeline is busy

            chan->is_locked = true;

            IpcMessagePacket* packet = &chan->pending_queue;
            packet->magic = IPC_MAGIC_HEADER;
            packet->sender_pid = sender_pid;
            packet->recipient_pid = chan->dest_pid;
            packet->data_length = length;

            // Enforce sandbox verification checks on the sender memory footprint segment
            if (!validate_memory_access_bounds(sender_pid, (uint64_t)clear_data, length, false)) {
                chan->is_locked = false;
                return false; // Access violation abort
            }

            // Encrypt and stage the plaintext payload directly inside our Ring 0 cache boundary
            ipc_crypto_transform(sender_pid ^ chan->dest_pid, clear_data, packet->encrypted_payload, length);

            chan->has_message = true;
            chan->is_locked = false;
            return true;
        }
    }
    return false; // Unauthorized sender or dead link channel allocation mapping
}

bool sys_ipc_receive_secure_message(uint32_t channel_id, uint32_t recipient_pid, uint8_t* out_clear_buffer, uint32_t max_len) {
    for (uint32_t i = 0; i < g_ipc_gate.total_allocated_channels; i++) {
        IpcChannelNode* chan = &g_ipc_gate.channels[i];

        if (chan->channel_id == channel_id && chan->dest_pid == recipient_pid) {
            if (!chan->has_message || chan->is_locked) return false; // Queue empty or blocked

            chan->is_locked = true;

            IpcMessagePacket* packet = &chan->pending_queue;
            if (packet->magic != IPC_MAGIC_HEADER) {
                chan->is_locked = false;
                return false; // Corrupted packet validation structure
            }

            // Enforce sandbox write clearance checks on the recipient target space layout
            if (!validate_memory_access_bounds(recipient_pid, (uint64_t)out_clear_buffer, packet->data_length, true)) {
                chan->is_locked = false;
                return false;
            }

            uint32_t bytes_to_copy = (packet->data_length > max_len) ? max_len : packet->data_length;

            // Decrypt the raw stored database payload straight out of kernel cache into app space
            ipc_crypto_transform(packet->sender_pid ^ recipient_pid, packet->encrypted_payload, out_clear_buffer, bytes_to_copy);

            // Flush queue states cleanly
            memset(packet, 0, sizeof(IpcMessagePacket));
            chan->has_message = false;
            chan->is_locked = false;
            return true;
        }
    }
    return false; // Unauthorized receiver access query
}
