                tv->tv_usec = 123456;
            }
            return 0;
        }
        case LINUX_SYS_NANOSLEEP:
            return 0;

        // --- 6. Network Socket Rings ---
        case LINUX_SYS_SOCKET:
            return (uint64_t)sys_net_socket((uint32_t)frame->rdi, (uint32_t)frame->rsi, (uint32_t)frame->rdx);
        case LINUX_SYS_BIND:
