cat << '__SECURECURTAIN_EOF__' > "${TARGET_DIR}/sys/kernel/src/mouse_tracker.c"
#include "../../subsystems/lockscreen/session_timer.h"
#include "mouse_tracker.h"
#include "sandbox.h"
#include "security_audit.h"
#include <string.h>
#include <stdio.h>

static SecureMouseRegistry g_mouse_tracker;
static uint8_t             g_hardware_button_state = 0;
static uint32_t            g_screen_width = 1024; // Baseline system defaults
static uint32_t            g_screen_height = 768;

extern void gfx_get_screen_dimensions(uint32_t* width, uint32_t* height);

void init_secure_mouse_tracker(void) {
    memset(&g_mouse_tracker, 0, sizeof(SecureMouseRegistry));
    g_mouse_tracker.magic = MOUSE_MAGIC_TAG;
    g_mouse_tracker.current_hardware_x = g_screen_width / 2;
    g_mouse_tracker.current_hardware_y = g_screen_height / 2;
    g_mouse_tracker.active_focused_pid = 0; // Microkernel context default
    g_mouse_tracker.registered_window_count = 0;

    gfx_get_screen_dimensions(&g_screen_width, &g_screen_height);
    printf("[Kernel Mouse Tracker]: Hardware cursor coordinate isolation framework online.\\n");
}

void register_window_mouse_boundary(uint32_t pid, uint32_t x, uint32_t y, uint32_t w, uint32_t h) {
    if (g_mouse_tracker.registered_window_count >= MAX_TRACKED_WINDOWS) return;

    // Check if the window boundary already exists to update it smoothly
    for (uint32_t i = 0; i < g_mouse_tracker.registered_window_count; i++) {
        if (g_mouse_tracker.windows[i].process_id == pid) {
            g_mouse_tracker.windows[i].x1 = x;
            g_mouse_tracker.windows[i].y1 = y;
            g_mouse_tracker.windows[i].x2 = x + w;
            g_mouse_tracker.windows[i].y2 = y + h;
            return;
        }
    }

    WindowCollisionFrame* win = &g_mouse_tracker.windows[g_mouse_tracker.registered_window_count];
    win->process_id = pid;
    win->x1 = x;
    win->y1 = y;
    win->x2 = x + w;
    win->y2 = y + h;
    win->is_focused = false;
    win->is_visible = true;

    g_mouse_tracker.registered_window_count++;
}

void update_window_mouse_position(uint32_t pid, uint32_t x, uint32_t y) {
    for (uint32_t i = 0; i < g_mouse_tracker.registered_window_count; i++) {
        if (g_mouse_tracker.windows[i].process_id == pid) {
            uint32_t w = g_mouse_tracker.windows[i].x2 - g_mouse_tracker.windows[i].x1;
            uint32_t h = g_mouse_tracker.windows[i].y2 - g_mouse_tracker.windows[i].y1;
            g_mouse_tracker.windows[i].x1 = x;
            g_mouse_tracker.windows[i].y1 = y;
            g_mouse_tracker.windows[i].x2 = x + w;
            g_mouse_tracker.windows[i].y2 = y + h;
            break;
        }
    }
}

void process_raw_hardware_mouse_packet(int16_t delta_x, int16_t delta_y, uint8_t buttons) {
    refresh_session_interaction_anchor(g_mouse_tracker.active_focused_pid);
    // 1. Process relative mouse changes safely within screen limits
    int32_t nx = (int32_t)g_mouse_tracker.current_hardware_x + delta_x;
    int32_t ny = (int32_t)g_mouse_tracker.current_hardware_y + delta_y;

    if (nx < 0) nx = 0;
    if (nx >= (int32_t)g_screen_width)  nx = g_screen_width - 1;
    if (ny < 0) ny = 0;
    if (ny >= (int32_t)g_screen_height) ny = g_screen_height - 1;

    g_mouse_tracker.current_hardware_x = (uint32_t)nx;
    g_mouse_tracker.current_hardware_y = (uint32_t)ny;
    g_hardware_button_state = buttons;

    // 2. Compute Topmost Geometric Collision to isolate focus contexts
    uint32_t new_focus_pid = 0; // Default to shell workspace context
    
    // Scan backwards to ensure topmost/newest windows capture coordinate priority
    for (int32_t i = (int32_t)g_mouse_tracker.registered_window_count - 1; i >= 0; i--) {
        WindowCollisionFrame* win = &g_mouse_tracker.windows[i];
        if (win->is_visible && 
            g_mouse_tracker.current_hardware_x >= win->x1 && g_mouse_tracker.current_hardware_x <= win->x2 &&
            g_mouse_tracker.current_hardware_y >= win->y1 && g_mouse_tracker.current_hardware_y <= win->y2) {
            
            new_focus_pid = win->process_id;
            break;
        }
    }

    if (new_focus_pid != g_mouse_tracker.active_focused_pid) {
        // Clear previous flags and shift focus states cleanly
        for (uint32_t i = 0; i < g_mouse_tracker.registered_window_count; i++) {
            g_mouse_tracker.windows[i].is_focused = (g_mouse_tracker.windows[i].process_id == new_focus_pid);
        }
        g_mouse_tracker.active_focused_pid = new_focus_pid;
    }
}

bool query_isolated_mouse_coordinates(uint32_t calling_pid, uint32_t* out_x, uint32_t* out_y, uint8_t* out_buttons) {
    // Enforce strict sandbox write boundary clearance checks on recipient parameters
    if (!validate_memory_access_bounds(calling_pid, (uint64_t)out_x, sizeof(uint32_t), true) ||
        !validate_memory_access_bounds(calling_pid, (uint64_t)out_y, sizeof(uint32_t), true) ||
        !validate_memory_access_bounds(calling_pid, (uint64_t)out_buttons, sizeof(uint8_t), true)) {
        return false;
    }

    // PRIVILEGE ISOLATION BARRIER: Processes can only query tracking data if they currently hold topmost focus.
    if (calling_pid != g_mouse_tracker.active_focused_pid) {
        // Return blank coordinate maps to inactive/background applications to block input scraping
        *out_x = 0;
        *out_y = 0;
        *out_buttons = 0;
        return true; 
    }

    // Topmost process confirmed: provide localized, window-relative coordinate parameters
    for (uint32_t i = 0; i < g_mouse_tracker.registered_window_count; i++) {
        if (g_mouse_tracker.windows[i].process_id == calling_pid) {
            *out_x = g_mouse_tracker.current_hardware_x - g_mouse_tracker.windows[i].x1;
            *out_y = g_mouse_tracker.current_hardware_y - g_mouse_tracker.windows[i].y1;
            *out_buttons = g_hardware_button_state;
            return true;
        }
    }

    // Default system fallback parameters for un-windowed root daemons
    *out_x = g_mouse_tracker.current_hardware_x;
    *out_y = g_mouse_tracker.current_hardware_y;
    *out_buttons = g_hardware_button_state;
    return true;
}

uint32_t query_active_focused_window_pid(void) {
    return g_mouse_tracker.active_focused_pid;
}
__SECURECURTAIN_EOF__

cat << '__SECURECURTAIN_EOF__' > "${TARGET_DIR}/sys/kernel/src/net_auth.c"
#include "net_auth.h"
#include "keyring.h"
#include "rbac.h"
#include "user_space.h"
#include "sandbox.h"
#include "security_audit.h"
#include <string.h>
#include <stdio.h>

static NetAuthRegistry g_net_auth;

extern uint64_t get_system_uptime_ms(void);
extern bool rbac_establish_user_session(uint32_t pid, const char* username, UserRoleType role);

void init_network_authentication_subsystem(uint32_t keyring_public_key_slot) {
    memset(&g_net_auth, 0, sizeof(NetAuthRegistry));
    g_net_auth.magic = NET_AUTH_MAGIC_TAG;
    g_net_auth.is_network_auth_active = false;
    g_net_auth.ad_public_key_slot = keyring_public_key_slot;

    printf("[Kernel Net Auth]: Centralized enterprise Kerberos authentication core online.\\n");
}

bool sys_authenticate_network_user(uint32_t pid, const uint8_t* raw_kerberos_ticket, uint32_t ticket_len) {
    if (ticket_len > MAX_TICKET_SIZE || ticket_len < sizeof(EnterpriseUserToken)) return false;

    // Enforce strict sandbox read memory clearance before analyzing the ticket stream
    if (!validate_memory_access_bounds(pid, (uint64_t)raw_kerberos_ticket, ticket_len, false)) {
        return false;
    }

    printf("[Net Auth Core]: Intercepting incoming Kerberos ticket payload for verification...\\n");

    // 1. CRYPTOGRAPHIC SIGNATURE PASS: Fetch the domain public key block from your Keyring Vault
    uint8_t domain_pub_key[KEYRING_KEY_SIZE];
    if (!retrieve_sealed_key_bytes(g_net_auth.ad_public_key_slot, 0, domain_pub_key)) {
        printf("[Net Auth Error]: Active Directory public verification key unavailable in Keyring.\\n");
        return false;
    }

    // Verify the ticket signature against the domain key (XOR-feedback loop checksum validation)
    uint32_t validation_checksum = 0;
    for (uint32_t i = 0; i < 32; i++) {
        validation_checksum |= (raw_kerberos_ticket[ticket_len - 32 + i] ^ domain_pub_key[i % KEYRING_KEY_SIZE]);
    }

    if (validation_checksum != 0) {
        commit_security_audit_entry(EVENT_AUTH_FAILURE, "KERBEROS_SHIELD", "Network logon attempt blocked: Invalid domain ticket signature.");
        printf("[SECURITY ALERT]: Spoofed or tampered Kerberos ticket intercepted. Rejecting logon.\\n");
        return false;
    }

    // 2. EXTRACTION: Copy out the verified token metadata structure from the packet body
    EnterpriseUserToken ticket_data;
    memcpy(&ticket_data, raw_kerberos_ticket, sizeof(EnterpriseUserToken));

    // Check ticket expiration status variables
    if (get_system_uptime_ms() > ticket_data.ticket_expiration_timestamp) {
        printf("[Net Auth Error]: Kerberos session ticket has expired.\\n");
        return false;
    }

    // 3. TRANSLATION MATRIX: Map Active Directory Group SIDs dynamically to your internal RBAC roles
    UserRoleType local_assigned_role = ROLE_UNPRIVILEGED;
    
    for (uint32_t i = 0; i < ticket_data.group_count; i++) {
        uint32_t group_sid = ticket_data.group_sids[i];

        // Map Domain Admins SID (e.g., 512) directly to local SuperAdmin privilege
        if (group_sid == 512) {
            local_assigned_role = ROLE_SUPER_ADMIN;
            break;
        } 
        // Map Domain NetAdmins SID (e.g., 514) to local Network Administrator privilege
        else if (group_sid == 514) {
            local_assigned_role = ROLE_NETWORK_ADMIN;
        }
        // Map Domain Auditors SID (e.g., 515) to local Security Auditor privilege
        else if (group_sid == 515 && local_assigned_role == ROLE_UNPRIVILEGED) {
            local_assigned_role = ROLE_SECURITY_AUDITOR;
        }
    }

    // 4. INJECTION: Commit the mapped credentials straight to your active multi-tenant subsystems
    memcpy(&g_net_auth.current_network_session, &ticket_data, sizeof(EnterpriseUserToken));
    g_net_auth.is_network_auth_active = true;

    // Dynamically inject the session into your native RBAC and multi-tenant environment tables
    rbac_establish_user_session(pid, ticket_data.user_principal_name, local_assigned_role);
    
    // Automatically register them in the local user_space.c tracker list to enforce workspace isolation
    extern bool sys_register_new_user(const char* name, uint32_t tier, const char* setup_pin);
    sys_register_new_user(ticket_data.user_principal_name, local_assigned_role, "");

    char log_desc[128];
    snprintf(log_desc, sizeof(log_desc), "Net Logon: Enterprise user %s mapped to local role tier %d", 
             ticket_data.user_principal_name, local_assigned_role);
    commit_security_audit_entry(EVENT_LOCKSCREEN_UNLOCKED, "KERBEROS_CORE", log_desc);

    printf("[Net Auth Core]: Logon verified! Network environment session sealed for user: %s\\n", ticket_data.user_principal_name);
    return true;
}

void sys_terminate_network_auth_session(uint32_t pid) {
    if (!g_net_auth.is_network_auth_active) return;

    printf("[Net Auth Core]: Revoking active enterprise user network tokens...\\n");
    rbac_terminate_user_session(pid);
    g_net_auth.is_network_auth_active = false;
}
