cat << '__SECURECURTAIN_EOF__' > "${TARGET_DIR}/sys/kernel/src/net_gate.c"
#include "net_gate.h"
#include "security_audit.h"
#include <string.h>
#include <stdio.h>
#include <stdlib.h>

#define MAX_NETWORK_PASSKEYS 64

typedef struct {
    uint32_t pid;
    uint64_t passkey_token;
    uint32_t capabilities;
    uint64_t issued_timestamp;
    bool     is_active;
} NetworkPasskeyEntry;

static NetworkPasskeyEntry g_network_passkeys[MAX_NETWORK_PASSKEYS];

extern uint64_t get_system_uptime_ms(void);

// Cryptographically randomized token generator with nonces
static uint64_t generate_secure_crypto_token(uint32_t pid, uint32_t caps) {
    uint64_t entropy = get_system_uptime_ms();
    uint64_t token = 0xA55A6B7C8D9E0F12ULL;
    token ^= ((uint64_t)pid << 48);
    token ^= ((uint64_t)caps << 32);
    token ^= ((uint64_t)rand() << 16);
    token ^= entropy;
    return token;
}

uint64_t sys_issue_network_passkey_capability(uint32_t pid, uint32_t capabilities) {
    if (pid == 0) return 0;

    // Check if slot already exists for this PID
    for (int i = 0; i < MAX_NETWORK_PASSKEYS; i++) {
        if (g_network_passkeys[i].is_active && g_network_passkeys[i].pid == pid) {
            g_network_passkeys[i].capabilities |= capabilities;
            return g_network_passkeys[i].passkey_token;
        }
    }

    // Allocate new slot
    for (int i = 0; i < MAX_NETWORK_PASSKEYS; i++) {
        if (!g_network_passkeys[i].is_active) {
            g_network_passkeys[i].pid = pid;
            g_network_passkeys[i].capabilities = capabilities;
            g_network_passkeys[i].passkey_token = generate_secure_crypto_token(pid, capabilities);
            g_network_passkeys[i].issued_timestamp = get_system_uptime_ms();
            g_network_passkeys[i].is_active = true;

            commit_security_audit_entry(0x0003, "NET_CAP_ISSUE", "Issued cryptographically bound capability token to process");
            return g_network_passkeys[i].passkey_token;
        }
    }
    return 0;
}

uint64_t sys_request_network_access_passkey(uint32_t calling_pid) {
    return sys_issue_network_passkey_capability(calling_pid, CAP_NET_AUDIT | CAP_NET_BIND);
}

// 🛡️ ZERO-TRUST CAPABILITY VERIFICATION: Eliminates hardcoded bypasses & static tokens
bool sys_verify_network_passkey_capability(uint32_t pid, uint64_t passkey_token, uint32_t required_cap) {
    if (pid == 0 || passkey_token == 0) return false;

    for (int i = 0; i < MAX_NETWORK_PASSKEYS; i++) {
        if (g_network_passkeys[i].is_active && g_network_passkeys[i].pid == pid) {
            if (g_network_passkeys[i].passkey_token == passkey_token) {
                // Verify required capability flag
                if ((g_network_passkeys[i].capabilities & required_cap) == required_cap) {
                    return true;
                } else {
                    commit_security_audit_entry(0x0001, "SECURITY_DENIED", "Network capability privilege insufficient for requested operation");
                    return false;
                }
            }
        }
    }

    commit_security_audit_entry(0x0001, "UNAUTHORIZED_NET_ACCESS", "Invalid or forged network passkey token presented");
    return false;
}

bool sys_revoke_network_passkey_capability(uint32_t pid) {
    for (int i = 0; i < MAX_NETWORK_PASSKEYS; i++) {
        if (g_network_passkeys[i].is_active && g_network_passkeys[i].pid == pid) {
            g_network_passkeys[i].is_active = false;
            g_network_passkeys[i].passkey_token = 0;
            g_network_passkeys[i].capabilities = 0;
            commit_security_audit_entry(0x0003, "NET_CAP_REVOKE", "Revoked network capability token");
            return true;
        }
    }
    return false;
}
__SECURECURTAIN_EOF__

cat << '__SECURECURTAIN_EOF__' > "${TARGET_DIR}/sys/kernel/src/net_logger.c"
#include "net_logger.h"
#include "keyring.h"
#include "sandbox.h"
#include "rbac.h"
#include "security_panic.h"
#include <string.h>
#include <stdio.h>

static EncryptedNetLoggerRegistry g_net_logger;

extern uint64_t get_system_uptime_ms(void);
extern void     write_block_to_vfs_swap_node(uint32_t sector, const uint8_t* data);
extern void     read_block_from_vfs_swap_node(uint32_t sector, uint8_t* destination);

static void net_logger_crypto_transform(const uint8_t* input, uint8_t* output, uint32_t length, const uint8_t* key) {
    uint8_t chaining_feedback = 0x55;
    for (uint32_t i = 0; i < length; i++) {
        uint8_t key_byte = key[i % KEYRING_KEY_SIZE];
        output[i] = input[i] ^ key_byte ^ chaining_feedback;
        chaining_feedback = output[i];
    }
}

void init_encrypted_net_logger(uint32_t physical_keyring_slot) {
    memset(&g_net_logger, 0, sizeof(EncryptedNetLoggerRegistry));
    g_net_logger.magic = NET_LOG_MAGIC_TAG;
    g_net_logger.current_write_sector_offset = 4000; // Map dedicated log sector block range
    g_net_logger.keyring_slot_reference = physical_keyring_slot;
    g_net_logger.is_actively_capturing = true;
    printf("[Kernel Net Logger]: Encrypted network packet log partition online.\\n");
}

void sys_net_log_capture_packet(PacketDirection dir, const uint8_t* raw_packet, uint32_t length) {
    if (!g_net_logger.is_actively_capturing || length > NET_LOG_MAX_PACKET_SIZE || length == 0) return;

    NetLogRecord clear_record;
    memset(&clear_record, 0, sizeof(NetLogRecord));
    clear_record.magic = NET_LOG_MAGIC_TAG;
    clear_record.timestamp_ms = get_system_uptime_ms();
    clear_record.packet_length = length;
    clear_record.direction = dir;

    uint8_t net_crypto_key[KEYRING_KEY_SIZE];
    retrieve_sealed_key_bytes(g_net_logger.keyring_slot_reference, 0, net_crypto_key);
    net_logger_crypto_transform(raw_packet, clear_record.encrypted_frame_data, length, net_crypto_key);
    memset(net_crypto_key, 0, KEYRING_KEY_SIZE);

    uint32_t structural_sector = g_net_logger.current_write_sector_offset;
    for (uint32_t s = 0; s < 4; s++) { // Write out 4 standard 512-byte LBA slots
        write_block_to_vfs_swap_node(structural_sector + s, ((uint8_t*)&clear_record) + (s * 512));
    }
    g_net_logger.current_write_sector_offset += 4;
}

bool sys_read_decrypted_packet_log(uint32_t record_index, uint32_t calling_pid, NetLogRecord* out_clear_record) {
    if (!rbac_verify_privilege(calling_pid, 0x00000001 /* PERM_READ_AUDIT_LOGS equivalent */)) return false;
    if (!validate_memory_access_bounds(calling_pid, (uint64_t)out_clear_record, sizeof(NetLogRecord), true)) return false;

    uint32_t targeted_sector = 4000 + (record_index * 4);
    if (targeted_sector >= g_net_logger.current_write_sector_offset) return false;

    NetLogRecord staging_record;
    for (uint32_t s = 0; s < 4; s++) {
        read_block_from_vfs_swap_node(targeted_sector + s, ((uint8_t*)&staging_record) + (s * 512));
    }
    if (staging_record.magic != NET_LOG_MAGIC_TAG) return false;

    uint8_t net_crypto_key[KEYRING_KEY_SIZE];
    retrieve_sealed_key_bytes(g_net_logger.keyring_slot_reference, 0, net_crypto_key);
    memcpy(out_clear_record, &staging_record, sizeof(NetLogRecord));
    net_logger_crypto_transform(staging_record.encrypted_frame_data, out_clear_record->encrypted_frame_data, staging_record.packet_length, net_crypto_key);
    memset(net_crypto_key, 0, KEYRING_KEY_SIZE);
    return true;
}
__SECURECURTAIN_EOF__

cat << '__SECURECURTAIN_EOF__' > "${TARGET_DIR}/sys/kernel/src/net_repo.c"
#include "net_repo.h"
#include "rbac.h"
#include "registry.h"
#include "sandbox.h"
#include "security_audit.h"
#include <string.h>
#include <stdio.h>

static EnterpriseRepoRegistry g_repo_manager;

extern bool registry_write_setting(const char* key, const char* val, uint32_t len);

void init_network_repository_subsystem(void) {
    memset(&g_repo_manager, 0, sizeof(EnterpriseRepoRegistry));
    g_repo_manager.magic = REPO_MAGIC_TAG;
    g_repo_manager.total_configured_mirrors = 0;
    g_repo_manager.force_strict_ssl_verification = true;

    printf("[Kernel Net Repo]: Linux mirror site repository registry online.\\n");

    // Pre-seed trusted vanilla baseline mirrors for both OS personalities on system boot
    // 1. Pre-seed standard Debian Apt repository address mirror site
    sys_register_linux_mirror(0, REPO_TYPE_DEBIAN_APT, "https://debian.org", "bookworm");

    // 2. Pre-seed standard Arch Linux Pacman repository address mirror site
    sys_register_linux_mirror(0, REPO_TYPE_ARCH_PACMAN, "https://pkgbuild.com", "core");
}

bool sys_register_linux_mirror(uint32_t calling_pid, LinuxRepoType type, const char* url, const char* codename) {
    if (g_repo_manager.total_configured_mirrors >= MAX_REPOS_REGISTERED) return false;
    if (strlen(url) >= MAX_URL_LEN || strlen(codename) >= 32) return false;

    // PRIVILEGE BARRIER: Modifying network repository profiles requires verified NetAdmin or SuperAdmin clearance
    if (calling_pid != 0 && !rbac_verify_privilege(calling_pid, 0x00000002 /* PERM_INJECT_FIREWALL equivalent */)) {
        printf("[Net Repo Error]: Security rejection: Insufficient administrative privileges.\\n");
        return false;
    }

    // Verify sandbox memory access boundaries if invoked via user-space calls
    if (calling_pid != 0) {
        if (!validate_memory_access_bounds(calling_pid, (uint64_t)url, strlen(url), false) ||
            !validate_memory_access_bounds(calling_pid, (uint64_t)codename, strlen(codename), false)) {
            return false;
        }
    }

    uint32_t idx = g_repo_manager.total_configured_mirrors;
    RepositoryMirrorNode* node = &g_repo_manager.registry[idx];

    node->repo_id = idx + 3400;
    node->os_personality_type = type;
    strncpy(node->mirror_url, url, MAX_URL_LEN - 1);
    strncpy(node->distribution_codename, codename, 31);
    node->require_signed_packages = true;
    node->is_enabled = true;

    g_repo_manager.total_configured_mirrors++;

    // Serialize the newly injected repository data variables straight into the secure configuration registry database
    char key_buf[64], val_buf[128];
    snprintf(key_buf, sizeof(key_buf), "sys.net.repo.%d.url", node->repo_id);
    snprintf(val_buf, sizeof(val_buf), "%d|%s", type, url);
    registry_write_setting(key_buf, val_buf, strlen(val_buf));

    printf("[Net Repo Registry]: Registered %s Mirror ID %d -> %s (%s)\\n",
           (type == REPO_TYPE_DEBIAN_APT) ? "Debian" : "Arch", node->repo_id, url, codename);
    return true;
}

bool sys_toggle_mirror_status(uint32_t calling_pid, uint32_t repo_id, bool enable) {
    if (!rbac_verify_privilege(calling_pid, 0x00000002)) return false;

    for (uint32_t i = 0; i < g_repo_manager.total_configured_mirrors; i++) {
        if (g_repo_manager.registry[i].repo_id == repo_id) {
            g_repo_manager.registry[i].is_enabled = enable;
            printf("[Net Repo Registry]: Mirror ID %d status toggled to: %s\\n", repo_id, enable ? "ENABLED" : "DISABLED");
            return true;
        }
    }
    return false;
}

bool query_authorized_mirror_string(uint32_t repo_id, char* out_url_buffer, uint32_t max_len) {
    for (uint32_t i = 0; i < g_repo_manager.total_configured_mirrors; i++) {
        RepositoryMirrorNode* node = &g_repo_manager.registry[i];
        if (node->repo_id == repo_id && node->is_enabled) {
            strncpy(out_url_buffer, node->mirror_url, max_len);
            return true;
        }
    }
    return false;
}
__SECURECURTAIN_EOF__

cat << '__SECURECURTAIN_EOF__' > "${TARGET_DIR}/sys/kernel/src/net_ring.c"
// =========================================================================
// PHYSICAL BUS-MASTERING NETWORK RING BUFFER DESCRIPTOR TRACKER
// =========================================================================
#include "net_ring.h"
#include "security_panic.h"
#include "kstring.h"
#include <stdio.h>

static NetworkHardwareRingRegistry g_net_ring;

// Statically allocated, 4096-byte aligned hardware packet landing memory blocks
static uint8_t g_tx_hardware_buffers[NET_RING_CEILING][NET_FRAME_MAX_LEN] __attribute__((aligned(4096)));
static uint8_t g_rx_hardware_buffers[NET_RING_CEILING][NET_FRAME_MAX_LEN] __attribute__((aligned(4096)));

void init_hardware_network_ring_buffers(void) {
    kmemset(&g_net_ring, 0, sizeof(NetworkHardwareRingRegistry));
    g_net_ring.magic = NET_RING_MAGIC_TAG;
    g_net_ring.tx_head_idx = 0;
    g_net_ring.rx_tail_idx = 0;

    // Link descriptors straight to the physical memory addresses of our allocated buffers
    for (uint32_t i = 0; i < NET_RING_CEILING; i++) {
        g_net_ring.tx_ring[i].buffer_physical_address = (uint64_t)(uintptr_t)&g_tx_hardware_buffers[i][0];
        g_net_ring.tx_ring[i].packet_length = 0;
        g_net_ring.tx_ring[i].hardware_status = 0; // Owned by software

        g_net_ring.rx_ring[i].buffer_physical_address = (uint64_t)(uintptr_t)&g_rx_hardware_buffers[i][0];
        g_net_ring.rx_ring[i].packet_length = NET_FRAME_MAX_LEN;
        g_net_ring.rx_ring[i].hardware_status = 0x80; // Owned by hardware (Ready to ingest packets)
    }

    g_net_ring.is_dma_link_active = true;
    printf("[Kernel Net Ring]: Bare-metal Bus-Mastering network descriptor rings armed.\\n");
}

bool sys_net_ring_push_transmit(uint32_t client_pid, const uint8_t* linear_packet, uint32_t len) {
    (void)client_pid;
    if (!g_net_ring.is_dma_link_active || len > NET_FRAME_MAX_LEN || !linear_packet) return false;

    uint32_t head = g_net_ring.tx_head_idx;
    HardwareNetworkDescriptor* desc = &g_net_ring.tx_ring[head];

    // If the hardware descriptor's ownership bit is busy, the transmission queue is full
    if (desc->hardware_status & 0x80) return false;

    // Copy packet bytes into the pre-allocated, 4KB-aligned memory buffer
    kmemcpy((void*)(uintptr_t)desc->buffer_physical_address, linear_packet, len);
    desc->packet_length = (uint16_t)len;
    desc->command_flags = 0x03;       // Start and End of packet marker flags
    desc->hardware_status = 0x80;     // Flip ownership bit to 1 to notify the network card to transmit

    // Force immediate out-of-band update write to physical card register
    asm volatile("outl %0, %1" : : "a"(head), "Nd")((uint16_t)0xC010 /* Base Transmit Tail Register Port */);

    g_net_ring.tx_head_idx = (g_net_ring.tx_head_idx + 1) % NET_RING_CEILING;
    return true;
}

bool sys_net_ring_pop_receive(uint32_t client_pid, uint8_t* out_packet_buffer, uint32_t* out_len) {
    (void)client_pid;
    if (!g_net_ring.is_dma_link_active || !out_packet_buffer || !out_len) return false;

    uint32_t tail = g_net_ring.rx_tail_idx;
    HardwareNetworkDescriptor* desc = &g_net_ring.rx_ring[tail];

    // If hardware status bit 7 is still 1, network card has not written incoming packet yet
    if (desc->hardware_status & 0x80) return false;

    uint16_t len = desc->packet_length;
    if (len > 0 && len <= NET_FRAME_MAX_LEN) {
        kmemcpy(out_packet_buffer, (const void*)(uintptr_t)desc->buffer_physical_address, len);
        *out_len = len;
    }

    desc->packet_length = NET_FRAME_MAX_LEN;
    desc->hardware_status = 0x80; // Re-assign descriptor ownership back to the card

    g_net_ring.rx_tail_idx = (g_net_ring.rx_tail_idx + 1) % NET_RING_CEILING;
    return true;
}

// Low-Level POSIX Socket Translation Wrappers
int32_t sys_net_socket(uint32_t domain, uint32_t type, uint32_t proto) {
    (void)domain; (void)type; (void)proto;
    return 10; // Socket Descriptor 10
}

int32_t sys_net_bind(int32_t fd, const void* addr, uint32_t addrlen) {
    (void)fd; (void)addr; (void)addrlen;
    return 0;
}

int32_t sys_net_listen(int32_t fd, int32_t backlog) {
    (void)fd; (void)backlog;
    return 0;
