 * and calculates strict W^X permission flags for the memory manager.
 */
int nt_parse_pe_sections(const uint8_t* buffer, size_t total_size, vm_space_t target_space) {
    if (!buffer || total_size == 0) return -1;

    const dos_header_t* dos_hdr = (const dos_header_t*)buffer;
    uint64_t pe_offset = dos_hdr->e_lfanew;
    
    const pe_file_header_t* pe_hdr = (const pe_file_header_t*)(buffer + pe_offset);
    uint64_t opt_hdr_offset = pe_offset + 4 + sizeof(pe_file_header_t);
    const pe64_optional_header_t* opt_hdr = (const pe64_optional_header_t*)(buffer + opt_hdr_offset);

    // 1. 🛡️ CRITICAL BOUNDS CHECK: Locate the Section Table securely
    // In PE binaries, the section table immediately follows the optional header.
    uint64_t section_table_offset = opt_hdr_offset + pe_hdr->size_of_optional_header;
    uint32_t num_sections = pe_hdr->number_of_sections;

    // Enforce an upper allocation boundary limit on total allowable sections
    if (num_sections > 96) return -2; 

    uint64_t total_table_size = num_sections * sizeof(pe64_section_header_t);
    if (section_table_offset + total_table_size > total_size) {
        return -3; // Security Violation: Section table out-of-bounds or truncated
    }

    const pe64_section_header_t* section_table = (const pe64_section_header_t*)(buffer + section_table_offset);

    // 2. Loop through every section header sequentially
    for (uint32_t i = 0; i < num_sections; i++) {
        const pe64_section_header_t* sec = &section_table[i];

        // 3. 🛡️ VERIFY FILE AND MEMORY BOUNDARY METRICS
        // Check for integer wrap-around attacks during size arithmetic
        uint64_t mem_end_target = opt_hdr->image_base + sec->virtual_address + sec->virtual_size;
        uint64_t file_end_target = sec->pointer_to_raw_data + sec->size_of_raw_data;

        if (mem_end_target < opt_hdr->image_base || file_end_target < sec->pointer_to_raw_data) {
            return -4; // Malicious integer wrap-around detected!
        }

        // Ensure raw file pointer bounds stay inside the file buffer
        if (sec->size_of_raw_data > 0 && file_end_target > total_size) {
            return -5; // Section reads past the end of the file data
        }

        // 🛡️ REFACTORED ADRESS SHIELD: Block section injection attacks targeting kernel space
        if (mem_end_target >= NT_USER_SPACE_MAX_ADDR || opt_hdr->image_base >= NT_USER_SPACE_MAX_ADDR) {
            return -6; // Security Violation: Section maps over protected kernel territory
        }

        // 4. 🛡️ COMPUTE HARDENED W^X PERMISSION FLAGS
        // Map PE characteristics dynamically to your kernel's strict page table permission bits
        uint64_t mapping_flags = PAGE_PRESENT | PAGE_USER;

        if (sec->characteristics & IMAGE_SCN_MEM_WRITE) {
            mapping_flags |= PAGE_WRITABLE;
        }

        // If the section doesn't explicitly flag execute permissions, lock it down with the NX bit
        if (!(sec->characteristics & IMAGE_SCN_MEM_EXECUTE) && !(sec->characteristics & IMAGE_SCN_CNT_CODE)) {
            mapping_flags |= PAGE_NX;
        }

        // 5. Proxy page allocation request out to the memory manager
        // Instead of calling Ring 0 code directly, the server coordinates mapping parameters
        size_t page_count = (sec->virtual_size + 4095) / 4096;
        for (size_t p = 0; p < page_count; p++) {
            uint64_t target_vaddr = opt_hdr->image_base + sec->virtual_address + (p * 4096);
            
            // In a fully deployed microkernel, call your context-isolated memory manager proxy:
            // memory_map_page(target_space, target_vaddr, physical_frame, mapping_flags);
        }
    }

    print_string("[NTDLL] PE binary sections validated and mapped securely into virtual target space.", 33);
    return 0; // Success
}

// 🛡️ SECURITY CONSTANTS: Explicitly define PE relocation block definitions
#define IMAGE_DIRECTORY_ENTRY_BASERELOC  5
