} __attribute__((packed)) pe_base_reloc_t;

/**
 * 🛡️ CONTEXT-ISOLATED PE SECTION RELOCATION ENGINE
 * Loops through the absolute relocation table of a Windows binary to patch base addresses.
 * Enforces strict boundary verification to insulate memory maps from out-of-bounds pointer manipulation.
 */
int nt_relocate_pe_image(const uint8_t* buffer, size_t total_size, uint64_t load_delta) {
    if (!buffer || total_size == 0 || load_delta == 0) return 0; // No delta modification needed

    const dos_header_t* dos_hdr = (const dos_header_t*)buffer;
    uint64_t pe_offset = dos_hdr->e_lfanew;
    const pe_file_header_t* pe_hdr = (const pe_file_header_t*)(buffer + pe_offset);
    uint64_t opt_hdr_offset = pe_offset + 4 + sizeof(pe_file_header_t);
    const pe64_optional_header_t* opt_hdr = (const pe64_optional_header_t*)(buffer + opt_hdr_offset);

    // 1. Locate the Base Relocation Data Directory securely
    // In a full PE header, the Data Directory array is located at the end of the Optional Header.
    // We mock the offset mapping calculation step here for our minimal structural layout:
    uint64_t reloc_dir_offset = opt_hdr_offset + 112; // Standard offset to Base Relocation Directory entry
    if (reloc_dir_offset + 8 > total_size) return -1;

    uint32_t reloc_rva = *(uint32_t*)(buffer + reloc_dir_offset);
    uint32_t reloc_size = *(uint32_t*)(buffer + reloc_dir_offset + 4);

    if (reloc_rva == 0 || reloc_size == 0) {
        return 0; // Binary contains no relocation table, safe to load at preferred base address
    }

    // Translate the Relocation Relative Virtual Address (RVA) to a safe file offset buffer address
    // (Assuming a baseline layout translation match inside our parsed section structures map)
    uint64_t file_reloc_offset = reloc_rva; // Simplified representation for flat file demo maps
    if (file_reloc_offset + reloc_size > total_size) {
        return -2; // Security Violation: Relocation table runs past the physical file boundary
    }

    uint32_t bytes_processed = 0;
    
    // 2. Main relocation block processing loop
    while (bytes_processed < reloc_size) {
        uint64_t current_block_offset = file_reloc_offset + bytes_processed;
        if (current_block_offset + sizeof(pe_base_reloc_t) > total_size) return -3;

        const pe_base_reloc_t* block = (const pe_base_reloc_t*)(buffer + current_block_offset);
        if (block->size_of_block < sizeof(pe_base_reloc_t)) return -4; // Defend against infinite loop corruption

        uint32_t num_entries = (block->size_of_block - sizeof(pe_base_reloc_t)) / sizeof(uint16_t);
        const uint16_t* entries = (const uint16_t*)(buffer + current_block_offset + sizeof(pe_base_reloc_t));

        if (current_block_offset + block->size_of_block > total_size) return -5;

        // 3. Loop through individual entry definitions inside the relocation block
        for (uint32_t i = 0; i < num_entries; i++) {
            uint16_t type  = entries[i] >> 12;   // Upper 4 bits hold the relocation type descriptor
            uint16_t offset = entries[i] & 0x0FFF; // Lower 12 bits hold the offset within the 4KB page

            if (type == IMAGE_REL_BASED_DIR64) {
                // Compute the absolute target virtual address location to modify
                uint64_t target_rva = block->virtual_address + offset;
                uint64_t patch_vaddr = opt_hdr->image_base + target_rva;

                // 4. 🛡️ POINTER PROBING PROTECTION WALL
                // Verify that the patch target stays safely inside unprivileged user-space zones.
                // Prevents a modified binary from tricking the NT layer into patching kernel pointers.
                if (patch_vaddr >= NT_USER_SPACE_MAX_LIMIT) {
