    strcpy(g_pkg_mgr.repos[0].repo_name, "arch-core");
    strcpy(g_pkg_mgr.repos[0].repo_url, "https://geo.mirror.pkgbuild.com/core/os/x86_64");
    g_pkg_mgr.repos[0].pkg_format = PKG_TYPE_PACMAN;
