	__le32 channel;
	__le32 band;
	u8 noise[IWL_MAX_NUM_NOISE_RESULTS];
	u8 reserved[2];
	__le32 active_time;
	__le32 busy_time;
	__le32 tx_time;
	__le32 rx_time;
} __packed; /* SCAN_CHANNEL_SURVEY_NTF_API_S_VER_1 */

#endif /* __iwl_fw_api_scan_h__ */
