cat << '__SECURECURTAIN_EOF__' > "${TARGET_DIR}/sys/kernel/src/linux/linux-6.10.10/drivers/net/wireless/intel/iwlwifi/mei/net.c"
// SPDX-License-Identifier: GPL-2.0-only
