/* Dropping to Ring 3 via x86_64 iretq
 * Stack layout for iretq:
 *   [RSP + 32] = SS (User Data 0x1B)
 *   [RSP + 24] = RSP (User Stack Pointer)
 *   [RSP + 16] = RFLAGS (0x202 = Interrupts Enabled)
 *   [RSP + 8]  = CS (User Code 0x23)
 *   [RSP + 0]  = RIP (User Entry Point)
 */
__attribute__((noreturn))
void ring3_jump(uint64_t entry_point, uint64_t user_rsp) {
    serial_puts("[RING3] Switching CPU privilege level: Ring 0 -> Ring 3 (Userland)...\n");
    serial_puts("[RING3] Target RIP: 0x");
    // Print entry hex address
    char hex[17];
    for (int i = 15; i >= 0; i--) {
        int nibble = (entry_point >> (i * 4)) & 0xF;
        hex[15 - i] = (nibble < 10) ? ('0' + nibble) : ('a' + nibble - 10);
    }
    hex[16] = '\0';
    serial_puts(hex);
    serial_puts(" | Target User RSP: 0x");
    for (int i = 15; i >= 0; i--) {
        int nibble = (user_rsp >> (i * 4)) & 0xF;
        hex[15 - i] = (nibble < 10) ? ('0' + nibble) : ('a' + nibble - 10);
    }
    serial_puts(hex);
    serial_puts("\n");

    __asm__ volatile (
        "cli\n\t"
        // Load User Data segment into segment registers
        "mov $0x1B, %%ax\n\t"
        "mov %%ax, %%ds\n\t"
        "mov %%ax, %%es\n\t"
        "mov %%ax, %%fs\n\t"
        "mov %%ax, %%gs\n\t"

        // Push iretq stack frame
        "pushq $0x1B\n\t"         // SS = User Data Segment (0x18 | 3)
        "pushq %1\n\t"            // RSP = User Stack Pointer
        "pushfq\n\t"              // Push current RFLAGS
        "popq %%rax\n\t"
        "orq $0x200, %%rax\n\t"   // Ensure IF (Interrupt Flag) is enabled (0x200)
        "pushq %%rax\n\t"         // RFLAGS
        "pushq $0x23\n\t"         // CS = User Code Segment (0x20 | 3)
        "pushq %0\n\t"            // RIP = Userland Entry Point

        "iretq\n\t"
        :
        : "r"(entry_point), "r"(user_rsp)
        : "rax", "memory"
    );

    __builtin_unreachable();
}

/* Allocate and map userland stack */
static bool setup_user_stack(void) {
    size_t num_pages = USER_STACK_SIZE / PAGE_SIZE;
    for (size_t i = 0; i < num_pages; i++) {
        uintptr_t virt = USER_STACK_BOTTOM + (i * PAGE_SIZE);
        uintptr_t phys = pmm_alloc_frame();
        if (!phys) {
            serial_puts("[LOADER] Error: Failed to allocate physical frame for user stack!\n");
            return false;
        }

        // Map with User and Writable permissions
        int ret = vmm_map_page(virt, phys, VMM_PAGE_PRESENT | VMM_PAGE_WRITABLE | VMM_PAGE_USER);
        if (ret != 0) {
            serial_puts("[LOADER] Error: Failed to map user stack page!\n");
            return false;
        }

        // Zero the stack page
        uint8_t *page_ptr = (uint8_t *)(KERNEL_VIRTUAL_BASE + phys);
        for (size_t b = 0; b < PAGE_SIZE; b++) page_ptr[b] = 0;
    }
    return true;
}

/* Parse and map 64-bit ELF executable (Linux Persona) */
static struct load_result load_elf64(const uint8_t *data, size_t size) {
    struct load_result res;
    res.success = false;
    res.personality = PERSONALITY_LINUX;

    if (size < sizeof(Elf64_Ehdr)) {
        serial_puts("[LOADER] ELF header truncated!\n");
        return res;
    }

    Elf64_Ehdr *ehdr = (Elf64_Ehdr *)data;

    // Validate ELF magic: 0x7F 'E' 'L' 'F'
    if (ehdr->e_ident[EI_MAG0] != ELF_MAGIC0 ||
        ehdr->e_ident[EI_MAG1] != ELF_MAGIC1 ||
        ehdr->e_ident[EI_MAG2] != ELF_MAGIC2 ||
        ehdr->e_ident[EI_MAG3] != ELF_MAGIC3) {
        serial_puts("[LOADER] Invalid ELF magic signature!\n");
        return res;
    }

    // Verify 64-bit and x86_64
    if (ehdr->e_ident[EI_CLASS] != ELFCLASS64 || ehdr->e_machine != EM_X86_64) {
        serial_puts("[LOADER] Incompatible ELF architecture (expected x86_64 64-bit)!\n");
        return res;
    }

    serial_puts("[LOADER] Valid ELF64 binary confirmed. Loading PT_LOAD segments...\n");

    // Iterate through Program Headers
    Elf64_Phdr *phdrs = (Elf64_Phdr *)(data + ehdr->e_phoff);
    for (uint16_t i = 0; i < ehdr->e_phnum; i++) {
        Elf64_Phdr *ph = &phdrs[i];
        if (ph->p_type != PT_LOAD) continue;

        uint64_t vaddr = ph->p_vaddr;
        uint64_t memsz = ph->p_memsz;
        uint64_t filesz = ph->p_filesz;
        uint64_t offset = ph->p_offset;

        uint64_t page_start = vaddr & ~(PAGE_SIZE - 1);
        uint64_t page_end = (vaddr + memsz + PAGE_SIZE - 1) & ~(PAGE_SIZE - 1);

        for (uint64_t p = page_start; p < page_end; p += PAGE_SIZE) {
            uintptr_t phys = pmm_alloc_frame();
            if (!phys) {
                serial_puts("[LOADER] Out of memory loading segment!\n");
                return res;
            }

            uint64_t flags = VMM_PAGE_PRESENT | VMM_PAGE_USER;
            if (ph->p_flags & PF_W) flags |= VMM_PAGE_WRITABLE;

            vmm_map_page(p, phys, flags);

            // Copy segment data into newly allocated frame
            uint8_t *frame_virt = (uint8_t *)(KERNEL_VIRTUAL_BASE + phys);
            for (size_t b = 0; b < PAGE_SIZE; b++) frame_virt[b] = 0;

            uint64_t seg_start = vaddr;
            uint64_t seg_end = vaddr + filesz;
            uint64_t page_start_addr = p;
            uint64_t page_end_addr = p + PAGE_SIZE;

            uint64_t intersect_start = (seg_start > page_start_addr) ? seg_start : page_start_addr;
            uint64_t intersect_end = (seg_end < page_end_addr) ? seg_end : page_end_addr;

            if (intersect_start < intersect_end) {
                size_t copy_len = intersect_end - intersect_start;
                size_t dest_offset = intersect_start - page_start_addr;
                size_t src_offset = offset + (intersect_start - seg_start);
                for (size_t b = 0; b < copy_len; b++) {
                    frame_virt[dest_offset + b] = data[src_offset + b];
                }
            }
        }
    }

    // Allocate Userland Stack
    if (!setup_user_stack()) {
        return res;
    }

    res.entry_point = ehdr->e_entry;
    res.user_rsp = USER_STACK_TOP - 16; // 16-byte alignment
    res.personality = PERSONALITY_LINUX;
    res.success = true;

    serial_puts("[LOADER] Linux ELF64 binary mapped successfully.\n");
    return res;
}

/* Parse and map 64-bit Windows PE32+ executable (Windows Persona) */
static struct load_result load_pe32plus(const uint8_t *data, size_t size) {
    struct load_result res;
    res.success = false;
    res.personality = PERSONALITY_WINDOWS;

    if (size < sizeof(IMAGE_DOS_HEADER)) {
        serial_puts("[LOADER] PE image smaller than DOS header!\n");
        return res;
    }

    IMAGE_DOS_HEADER *dos = (IMAGE_DOS_HEADER *)data;
    if (dos->e_magic != IMAGE_DOS_SIGNATURE) {
        serial_puts("[LOADER] Missing DOS 'MZ' signature!\n");
        return res;
    }

    if ((size_t)dos->e_lfanew + sizeof(IMAGE_NT_HEADERS64) > size) {
        serial_puts("[LOADER] Corrupt PE: e_lfanew out of bounds!\n");
        return res;
    }

    IMAGE_NT_HEADERS64 *nt = (IMAGE_NT_HEADERS64 *)(data + dos->e_lfanew);
    if (nt->Signature != IMAGE_NT_SIGNATURE) {
        serial_puts("[LOADER] Missing PE signature!\n");
        return res;
    }

    if (nt->FileHeader.Machine != IMAGE_FILE_MACHINE_AMD64) {
        serial_puts("[LOADER] Incompatible PE architecture (expected AMD64 64-bit)!\n");
        return res;
    }

    serial_puts("[LOADER] Valid Windows PE32+ (AMD64) executable identified!\n");
    serial_puts("[LOADER] Subsystem: ");
    if (nt->OptionalHeader.Subsystem == IMAGE_SUBSYSTEM_WINDOWS_GUI) {
        serial_puts("Windows GUI (Native Desktop Windowing)\n");
    } else {
        serial_puts("Windows CUI (Command-line Console)\n");
    }

    uint64_t image_base = nt->OptionalHeader.ImageBase;
    uint32_t entry_rva = nt->OptionalHeader.AddressOfEntryPoint;
    uint16_t num_sections = nt->FileHeader.NumberOfSections;

    IMAGE_SECTION_HEADER *sections = (IMAGE_SECTION_HEADER *)((uint8_t *)&nt->OptionalHeader + nt->FileHeader.SizeOfOptionalHeader);

    // Map each PE Section (.text, .rdata, .data, etc.)
    for (uint16_t i = 0; i < num_sections; i++) {
        IMAGE_SECTION_HEADER *sec = &sections[i];

        uint64_t sec_vaddr = image_base + sec->VirtualAddress;
        uint32_t sec_vsize = sec->VirtualSize ? sec->VirtualSize : sec->SizeOfRawData;
        uint32_t sec_raw_off = sec->PointerToRawData;
        uint32_t sec_raw_size = sec->SizeOfRawData;

        uint64_t p_start = sec_vaddr & ~(PAGE_SIZE - 1);
        uint64_t p_end = (sec_vaddr + sec_vsize + PAGE_SIZE - 1) & ~(PAGE_SIZE - 1);

        for (uint64_t p = p_start; p < p_end; p += PAGE_SIZE) {
            uintptr_t phys = pmm_alloc_frame();
            if (!phys) {
                serial_puts("[LOADER] Out of memory mapping PE section!\n");
                return res;
            }

            // Map as User page with Write and Present
            vmm_map_page(p, phys, VMM_PAGE_PRESENT | VMM_PAGE_WRITABLE | VMM_PAGE_USER);

            uint8_t *frame_virt = (uint8_t *)(KERNEL_VIRTUAL_BASE + phys);
            for (size_t b = 0; b < PAGE_SIZE; b++) frame_virt[b] = 0;

            uint64_t seg_start = sec_vaddr;
            uint64_t seg_end = sec_vaddr + sec_raw_size;
            uint64_t page_start_addr = p;
            uint64_t page_end_addr = p + PAGE_SIZE;

            uint64_t intersect_start = (seg_start > page_start_addr) ? seg_start : page_start_addr;
            uint64_t intersect_end = (seg_end < page_end_addr) ? seg_end : page_end_addr;

            if (intersect_start < intersect_end) {
                size_t copy_len = intersect_end - intersect_start;
                size_t dest_offset = intersect_start - page_start_addr;
                size_t src_offset = sec_raw_off + (intersect_start - seg_start);
                for (size_t b = 0; b < copy_len; b++) {
                    if (src_offset + b < size) {
                        frame_virt[dest_offset + b] = data[src_offset + b];
                    }
                }
            }
        }
    }

    // Inspect PE Import Directory (IAT) if present
    if (nt->OptionalHeader.NumberOfRvaAndSizes > IMAGE_DIRECTORY_ENTRY_IMPORT) {
        IMAGE_DATA_DIRECTORY *import_dir = &nt->OptionalHeader.DataDirectory[IMAGE_DIRECTORY_ENTRY_IMPORT];
        if (import_dir->VirtualAddress && import_dir->Size) {
            serial_puts("[LOADER:PE] PE Import Directory identified (IAT dynamic linking ready).\n");
        }
    }

    // Allocate Userland Stack
    if (!setup_user_stack()) {
        return res;
    }

    res.entry_point = image_base + entry_rva;
    res.user_rsp = USER_STACK_TOP - 16;
    res.personality = PERSONALITY_WINDOWS;
    res.success = true;

    serial_puts("[LOADER] Windows Persona PE32+ successfully mapped into Ring 3.\n");
    return res;
}

/* Universal Binary Auto-Detector and Loader */
struct load_result loader_load_binary(const uint8_t *binary_data, size_t binary_size) {
    struct load_result res;
    res.success = false;

    if (!binary_data || binary_size < 4) {
        serial_puts("[LOADER] Error: Binary buffer is empty or null!\n");
        return res;
    }

    // 1. Detect ELF64 (Linux Persona)
    if (binary_data[0] == ELF_MAGIC0 &&
        binary_data[1] == ELF_MAGIC1 &&
        binary_data[2] == ELF_MAGIC2 &&
        binary_data[3] == ELF_MAGIC3) {
        serial_puts("[LOADER] Autodetected: Linux ELF64 Binary Format\n");
        return load_elf64(binary_data, binary_size);
    }

    // 2. Detect Windows PE32+ (Windows Persona)
    if (binary_data[0] == 'M' && binary_data[1] == 'Z') {
        serial_puts("[LOADER] Autodetected: Windows PE/COFF Executable (MZ Signature)\n");
        return load_pe32plus(binary_data, binary_size);
    }

    serial_puts("[LOADER] Error: Unrecognized executable binary format!\n");
    return res;
}

/* Userland Process Trampoline for the Scheduler */
static void userland_task_trampoline(void) {
    struct task *curr = sched_get_current();
    if (curr && curr->is_user_mode) {
        ring3_jump(curr->user_entry_point, curr->user_rsp);
    }
    sched_exit(0);
}

/* High-level Process Spawner from VFS */
struct process *process_spawn(const char *path, os_personality_t persona_hint) {
    (void)persona_hint;
    serial_puts("[PROC] Spawning process from path: ");
    serial_puts(path);
    serial_puts("\n");

    struct vfs_node *node = vfs_open(path, 0);
    if (!node && path && path[0] != '/') {
        char fallback_path[128] = "/initrd/";
        size_t fi = 8;
        for (size_t pi = 0; path[pi] && fi < sizeof(fallback_path) - 1; pi++) {
            fallback_path[fi++] = path[pi];
        }
        fallback_path[fi] = '\0';
        node = vfs_open(fallback_path, 0);
    }

    if (!node) {
        serial_puts("[PROC] Error: Executable file not found in VFS: ");
        serial_puts(path);
        serial_puts("\n");
        return NULL;
    }

    size_t file_size = (size_t)node->size;
    if (file_size == 0) {
        serial_puts("[PROC] Error: Executable file is 0 bytes!\n");
        return NULL;
    }

    uint8_t *buffer = (uint8_t *)kmalloc(file_size);
    if (!buffer) {
        serial_puts("[PROC] Error: Failed to allocate memory to read binary!\n");
        return NULL;
    }

    size_t read_bytes = vfs_read(node, 0, file_size, buffer);
    if (read_bytes < file_size) {
        serial_puts("[PROC] Warning: Partial read of executable binary.\n");
    }

    // Load binary via Universal Loader
    struct load_result lr = loader_load_binary(buffer, read_bytes);
    kfree(buffer);

    if (!lr.success) {
        serial_puts("[PROC] Error: Failed to load binary image into userland!\n");
        return NULL;
    }

    struct process *p = (struct process *)kmalloc(sizeof(struct process));
    if (!p) {
        return NULL;
    }

    p->personality = lr.personality;
    p->entry_point = lr.entry_point;
    p->user_rsp = lr.user_rsp;
    p->heap_start = 0x0000000040000000ULL; // 1 GB mark
    p->heap_brk = p->heap_start;

    // Create a Preemptible Task in the Scheduler
    struct task *t = sched_create_task(node->name, (task_entry_t)userland_task_trampoline, 5);
    if (t) {
        t->personality = lr.personality;
        t->is_user_mode = true;
        t->user_rsp = lr.user_rsp;
        t->user_entry_point = lr.entry_point;
        // Note: t->entry_point intentionally remains userland_task_trampoline so task_trampoline invokes it!
        p->pid = t->pid;
        p->main_thread = t;
    }

    serial_puts("[PROC] Process PID ");
    serial_putc('0' + (p->pid % 10));
    serial_puts(" created. Persona: ");
    if (p->personality == PERSONALITY_WINDOWS) {
        serial_puts("WINDOWS (Win32 / NT Subsystem)\n");
    } else {
        serial_puts("LINUX (POSIX / System V ABI)\n");
    }

    return p;
}

void process_init(void) {
    serial_puts("[PROC] Initializing Process Manager & Dual-Persona Ring 3 Subsystem...\n");
}
__SECURECURTAIN_EOF__

cat << '__SECURECURTAIN_EOF__' > "${TARGET_DIR}/sys/kernel/src/core/sched.c"
/* SecureCurtain OS - Preemptive Multitasking & Round-Robin Task Scheduler
 * Author: Jared Busby (jb7572)
 * Architecture: x86_64 Freestanding
 */

#include "sched.h"
#include "kernel.h"
#include "heap.h"
#include "vmm.h"
#include "idt.h"

extern void tss_set_rsp0(uint64_t rsp0);

static struct task *ready_queue_head = NULL;
static struct task *ready_queue_tail = NULL;
static struct task *sleeping_queue_head = NULL;

static struct task *current_task = NULL;
static struct task *idle_task = NULL;
static struct task kernel_init_task; // PID 0 (Initial kernel bootstrap context)

static uint64_t next_pid = 0;
static uint64_t global_uptime_ticks = 0;
static uint64_t total_context_switches = 0;

/* Low-level Context Switch in x86_64 Long Mode
 * System V AMD64 ABI registers: rdi = prev_rsp, rsi = next_rsp, rdx = next_cr3
 * Callee-saved registers: rbx, rbp, r12, r13, r14, r15, rflags
 */
__attribute__((naked))
static void cpu_switch_context(uint64_t *prev_rsp, uint64_t next_rsp, uintptr_t next_cr3) {
    __asm__ volatile (
        "push %rbx\n\t"
        "push %rbp\n\t"
        "push %r12\n\t"
        "push %r13\n\t"
        "push %r14\n\t"
        "push %r15\n\t"
        "pushfq\n\t"

        "mov %rsp, (%rdi)\n\t"    // Save current RSP into *prev_rsp
        "mov %rsi, %rsp\n\t"      // Switch RSP to next_rsp

        // Switch address space (CR3) if next_cr3 is provided and different
        "test %rdx, %rdx\n\t"
        "jz 1f\n\t"
        "mov %cr3, %rax\n\t"
        "cmp %rdx, %rax\n\t"
        "je 1f\n\t"
        "mov %rdx, %cr3\n\t"
        "1:\n\t"

        "popfq\n\t"
        "pop %r15\n\t"
        "pop %r14\n\t"
        "pop %r13\n\t"
        "pop %r12\n\t"
        "pop %rbp\n\t"
        "pop %rbx\n\t"
        "ret\n\t"
    );
}

/* Trampoline executed when a newly created task starts for the first time */
static void task_trampoline(void) {
    // Enable hardware interrupts
    __asm__ volatile ("sti");

    if (current_task && current_task->entry_point) {
        current_task->entry_point();
    }

    sched_exit(0);
}

/* Enqueue a task to the tail of the ready queue */
static void enqueue_ready(struct task *t) {
    if (!t) return;
    t->state = TASK_READY;
    t->next = NULL;

    if (!ready_queue_head) {
        ready_queue_head = t;
        ready_queue_tail = t;
    } else {
        ready_queue_tail->next = t;
        ready_queue_tail = t;
    }
}

/* Dequeue the next task from the head of the ready queue */
static struct task *dequeue_ready(void) {
    if (!ready_queue_head) return NULL;

    struct task *t = ready_queue_head;
    ready_queue_head = ready_queue_head->next;
    if (!ready_queue_head) {
        ready_queue_tail = NULL;
    }
    t->next = NULL;
    return t;
}

/* Idle Task Routine (Runs HLT when no other tasks are runnable) */
static void idle_task_routine(void) {
    for (;;) {
        __asm__ volatile ("hlt");
    }
}

struct task *sched_create_task(const char *name, task_entry_t entry, uint64_t priority) {
    struct task *t = (struct task *)kmalloc(sizeof(struct task));
    if (!t) {
        serial_puts("[SCHED] Error: Out of memory allocating TCB!\n");
        return NULL;
    }

    // Allocate thread kernel stack (32 KB)
    void *stack = kmalloc(KERNEL_TASK_STACK_SIZE);
    if (!stack) {
        serial_puts("[SCHED] Error: Out of memory allocating task stack!\n");
        kfree(t);
        return NULL;
    }

    t->pid = next_pid++;
    
    // Copy name safely
    size_t i = 0;
    if (name) {
        while (name[i] && i < 31) {
            t->name[i] = name[i];
            i++;
        }
    }
    t->name[i] = '\0';

    t->state = TASK_READY;
    t->cr3 = 0; // Inherit kernel page tables
    t->priority = (priority > 0 && priority <= 10) ? priority : 5;
    t->time_slice = DEFAULT_TIME_SLICE * t->priority;
    t->ticks_remaining = t->time_slice;
    t->sleep_until = 0;
    t->total_ticks = 0;
    t->stack_base = stack;
    t->stack_size = KERNEL_TASK_STACK_SIZE;
    t->entry_point = entry;
    t->exit_code = 0;
    t->next = NULL;

    // Set up initial stack frame for x86_64 context switch
    uint64_t *stack_top = (uint64_t *)((uintptr_t)stack + KERNEL_TASK_STACK_SIZE);
    // Align to 16 bytes
    stack_top = (uint64_t *)((uintptr_t)stack_top & ~0xFULL);

    // Simulated stack frame for cpu_switch_context:
    // [0] return address (task_trampoline)
    // [1] rflags (0x202 = IF enabled)
    // [2] r15
    // [3] r14
    // [4] r13
    // [5] r12
    // [6] rbp
    // [7] rbx
    *(--stack_top) = (uint64_t)task_trampoline; // Return address for ret
    *(--stack_top) = 0x202;                     // RFLAGS (Interrupts enabled)
    *(--stack_top) = 0;                         // R15
    *(--stack_top) = 0;                         // R14
    *(--stack_top) = 0;                         // R13
    *(--stack_top) = 0;                         // R12
    *(--stack_top) = 0;                         // RBP
    *(--stack_top) = 0;                         // RBX

    t->rsp = (uint64_t)stack_top;

    enqueue_ready(t);

    serial_puts("[SCHED] Created Task PID ");
    serial_putc('0' + (t->pid % 10));
    serial_puts(": ");
    serial_puts(t->name);
    serial_puts("\n");

    return t;
}

void sched_yield(void) {
    __asm__ volatile ("cli");

    struct task *prev = current_task;
    struct task *next = dequeue_ready();

    if (!next) {
        // If ready queue is empty, keep running current task or idle
        if (prev && prev->state == TASK_RUNNING) {
            __asm__ volatile ("sti");
            return;
        }
        next = idle_task;
    }

    if (prev && prev->state == TASK_RUNNING) {
        enqueue_ready(prev);
    }

    current_task = next;
    current_task->state = TASK_RUNNING;
    current_task->ticks_remaining = current_task->time_slice;
    total_context_switches++;

    // Update TSS Ring 0 stack pointer to top of new task's kernel stack
    uint64_t kernel_stack_top = (uint64_t)current_task->stack_base + current_task->stack_size;
    tss_set_rsp0(kernel_stack_top);

    cpu_switch_context(&prev->rsp, next->rsp, next->cr3);

    __asm__ volatile ("sti");
}

void sched_tick(void *frame) {
    (void)frame;
    global_uptime_ticks++;

    if (!current_task) return;

    current_task->total_ticks++;

    // 1. Wake up sleeping tasks whose sleep timer has expired
    struct task **curr = &sleeping_queue_head;
    while (*curr != NULL) {
        struct task *s = *curr;
        if (global_uptime_ticks >= s->sleep_until) {
            *curr = s->next;
            enqueue_ready(s);
        } else {
            curr = &(*curr)->next;
        }
    }

    // 2. Preempt current task if its time slice has expired
    if (current_task->ticks_remaining > 0) {
        current_task->ticks_remaining--;
    }

    if (current_task->ticks_remaining == 0) {
        sched_yield();
    }
}

void sched_sleep(uint64_t ticks) {
    if (ticks == 0) {
        sched_yield();
        return;
    }

    __asm__ volatile ("cli");
    current_task->state = TASK_SLEEPING;
    current_task->sleep_until = global_uptime_ticks + ticks;
    
    // Add to sleeping queue
    current_task->next = sleeping_queue_head;
    sleeping_queue_head = current_task;

    sched_yield();
}

void sched_exit(int exit_code) {
    __asm__ volatile ("cli");

    serial_puts("[SCHED] Task PID ");
    serial_putc('0' + (current_task->pid % 10));
    serial_puts(" (");
    serial_puts(current_task->name);
    serial_puts(") terminated with exit code ");
    serial_putc('0' + (exit_code % 10));
    serial_puts(".\n");

    current_task->state = TASK_ZOMBIE;
    current_task->exit_code = exit_code;

    // Yield to the next runnable task (zombie will never be re-enqueued)
    sched_yield();

    // Should never reach here
    for (;;) {
        __asm__ volatile ("hlt");
    }
}

struct task *sched_get_current(void) {
    return current_task;
}

struct sched_stats sched_get_stats(void) {
    struct sched_stats stats;
    stats.total_tasks = next_pid;
    stats.running_tasks = 1;
    stats.sleeping_tasks = 0;
    stats.total_context_switches = total_context_switches;
    stats.uptime_ticks = global_uptime_ticks;

    struct task *t = sleeping_queue_head;
    while (t) {
        stats.sleeping_tasks++;
        t = t->next;
    }
    return stats;
}

void sched_dump_tasks(void) {
    serial_puts("\n=== SECURECURTAIN OS TASK TABLE ===\n");
    serial_puts("PID | NAME                 | STATE   | PRIO | TICKS\n");
    serial_puts("----+----------------------+---------+------+------\n");

    if (current_task) {
        serial_putc('0' + (current_task->pid % 10));
        serial_puts("   | ");
        serial_puts(current_task->name);
        serial_puts("                 | RUNNING | ");
        serial_putc('0' + (current_task->priority % 10));
        serial_puts("    | ");
        serial_putc('0' + (current_task->total_ticks % 10));
        serial_puts("\n");
    }

    struct task *t = ready_queue_head;
    while (t) {
        serial_putc('0' + (t->pid % 10));
        serial_puts("   | ");
        serial_puts(t->name);
        serial_puts("                 | READY   | ");
        serial_putc('0' + (t->priority % 10));
        serial_puts("    | ");
        serial_putc('0' + (t->total_ticks % 10));
        serial_puts("\n");
        t = t->next;
    }
    serial_puts("===================================\n\n");
}

void sched_init(void) {
    serial_puts("[SCHED] Initializing Preemptive Round-Robin Multitasking Engine...\n");

    ready_queue_head = NULL;
    ready_queue_tail = NULL;
    sleeping_queue_head = NULL;
    total_context_switches = 0;
    global_uptime_ticks = 0;
    next_pid = 0;

    // 1. Initialize bootstrap task (PID 0: Kernel Main)
    kernel_init_task.pid = next_pid++;
    kernel_init_task.name[0] = 'k';
    kernel_init_task.name[1] = 'm';
    kernel_init_task.name[2] = 'a';
    kernel_init_task.name[3] = 'i';
    kernel_init_task.name[4] = 'n';
    kernel_init_task.name[5] = '\0';
    kernel_init_task.state = TASK_RUNNING;
    kernel_init_task.rsp = 0;
    kernel_init_task.cr3 = 0;
    kernel_init_task.priority = 5;
    kernel_init_task.time_slice = DEFAULT_TIME_SLICE * 5;
    kernel_init_task.ticks_remaining = kernel_init_task.time_slice;
    kernel_init_task.sleep_until = 0;
    kernel_init_task.total_ticks = 0;
    kernel_init_task.stack_base = (void *)(KERNEL_VIRTUAL_BASE + 0x100000);
    kernel_init_task.stack_size = 0x20000;
    kernel_init_task.entry_point = NULL;
    kernel_init_task.exit_code = 0;
    kernel_init_task.next = NULL;

    current_task = &kernel_init_task;

    // 2. Spawn idle task (PID 1)
    idle_task = sched_create_task("idle", idle_task_routine, 1);
    // Remove idle task from ready queue so it is only scheduled when no other tasks exist
    ready_queue_head = NULL;
    ready_queue_tail = NULL;

    // 3. Register scheduler timer tick with IDT Vector 32 (APIC / PIT timer)
    idt_register_handler(32, (irq_handler_t)sched_tick);

    serial_puts("[SCHED] Multitasking initialized. PID 0 active, 100Hz preemption armed.\n");
}
__SECURECURTAIN_EOF__

cat << '__SECURECURTAIN_EOF__' > "${TARGET_DIR}/sys/kernel/src/core/smp.c"
/*
 * SecureCurtain OS - Symmetric Multiprocessing (SMP) Subsystem
 * Author: Jared Busby (jb7572)
 *
 * Implements Multi-Core CPU Initialization:
 * - Parses ACPI MADT (Multiple APIC Description Table)
 * - Identifies Local APIC IDs for all Application Processors (APs)
 * - Sets up real-mode AP trampoline at 0x8000
 * - Broadcasts INIT-SIPI-SIPI Inter-Processor Interrupts (IPI) via APIC ICR
 * - Synchronizes CPU core bringup with memory barriers and atomic spinlocks
 */

#include <stdint.h>
#include <stdbool.h>

#define MAX_CPUS 64

/* ACPI MADT Header and Entry Types */
#define ACPI_MADT_TYPE_LOCAL_APIC         0
#define ACPI_MADT_TYPE_IO_APIC            1
#define ACPI_MADT_TYPE_INTERRUPT_OVERRIDE 2

typedef struct __attribute__((packed)) {
    char     signature[4]; /* "APIC" */
    uint32_t length;
    uint8_t  revision;
    uint8_t  checksum;
    char     oem_id[6];
    char     oem_table_id[8];
    uint32_t oem_revision;
    uint32_t creator_id;
    uint32_t creator_revision;
    uint32_t local_apic_address;
    uint32_t flags;
} acpi_madt_header_t;

typedef struct __attribute__((packed)) {
    uint8_t type;
    uint8_t length;
} acpi_madt_entry_header_t;

typedef struct __attribute__((packed)) {
    acpi_madt_entry_header_t header;
    uint8_t  processor_id;
    uint8_t  apic_id;
    uint32_t flags; /* Bit 0: Enabled, Bit 1: Online Capable */
} acpi_madt_local_apic_t;

/* CPU Core Descriptor */
typedef struct {
    uint8_t  apic_id;
    uint8_t  acpi_id;
    bool     is_bsp;        /* Bootstrap Processor (Core 0) */
    bool     is_online;     /* Core successfully booted */
    uint64_t kernel_stack;  /* Dedicated Ring 0 stack pointer */
} cpu_core_t;

static cpu_core_t cpu_cores[MAX_CPUS];
static uint32_t   detected_cpu_count = 0;
static uint32_t   online_cpu_count   = 1; /* BSP starts online */

/* LAPIC Register Offsets */
#define LAPIC_ICR_LOW  0x300
#define LAPIC_ICR_HIGH 0x310

static volatile uint32_t *lapic_base = (volatile uint32_t *)0xFEE00000;

static void lapic_write(uint32_t reg, uint32_t value) {
    lapic_base[reg / 4] = value;
}

static __attribute__((unused)) uint32_t lapic_read(uint32_t reg) {
    return lapic_base[reg / 4];
}

/* Microsecond delay stub using PIT/HPET */
extern void pit_wait_ms(uint32_t ms);

/*
 * smp_parse_madt - Enumerate all physical and logical CPU cores from ACPI
 */
void smp_parse_madt(acpi_madt_header_t *madt) {
    if (!madt) return;

    uint8_t *ptr = (uint8_t *)(madt + 1);
    uint8_t *end = (uint8_t *)madt + madt->length;

    while (ptr < end && detected_cpu_count < MAX_CPUS) {
        acpi_madt_entry_header_t *entry = (acpi_madt_entry_header_t *)ptr;
        if (entry->length == 0) break;

        if (entry->type == ACPI_MADT_TYPE_LOCAL_APIC) {
            acpi_madt_local_apic_t *lapic = (acpi_madt_local_apic_t *)ptr;
            if (lapic->flags & 0x01) { /* Enabled */
                cpu_cores[detected_cpu_count].apic_id = lapic->apic_id;
                cpu_cores[detected_cpu_count].acpi_id = lapic->processor_id;
                cpu_cores[detected_cpu_count].is_bsp = (detected_cpu_count == 0);
                cpu_cores[detected_cpu_count].is_online = (detected_cpu_count == 0);
                detected_cpu_count++;
            }
        }
        ptr += entry->length;
    }
}

/*
 * smp_boot_core - Send INIT-SIPI-SIPI sequence to wake an AP core
 */
void smp_boot_core(uint8_t apic_id, uint8_t trampoline_page) {
    /* 1. Assert INIT IPI */
    lapic_write(LAPIC_ICR_HIGH, (uint32_t)apic_id << 24);
    lapic_write(LAPIC_ICR_LOW, 0x00004500); /* INIT level de-assert */
    pit_wait_ms(10);

    /* 2. Startup IPI (SIPI 1) */
    lapic_write(LAPIC_ICR_HIGH, (uint32_t)apic_id << 24);
    lapic_write(LAPIC_ICR_LOW, 0x00004600 | trampoline_page);
    pit_wait_ms(1);

    /* 3. Startup IPI (SIPI 2) */
    lapic_write(LAPIC_ICR_HIGH, (uint32_t)apic_id << 24);
    lapic_write(LAPIC_ICR_LOW, 0x00004600 | trampoline_page);
    pit_wait_ms(1);
}

/*
 * smp_init - Master SMP Initialization Routine
 */
void smp_init(void) {
    /* Trampoline loaded at 0x8000 -> Page 0x08 */
    uint8_t trampoline_page = 0x08;

    for (uint32_t i = 1; i < detected_cpu_count; ++i) {
        smp_boot_core(cpu_cores[i].apic_id, trampoline_page);
        cpu_cores[i].is_online = true;
        online_cpu_count++;
    }
}

uint32_t smp_get_online_cpu_count(void) {
    return online_cpu_count;
}
__SECURECURTAIN_EOF__

cat << '__SECURECURTAIN_EOF__' > "${TARGET_DIR}/sys/kernel/src/core/syscall.c"
/* SecureCurtain OS - 64-bit SYSCALL/SYSRET ABI & Dispatcher
 * Author: Jared Busby (jb7572)
 * Architecture: x86_64 Long Mode (IA32_LSTAR / IA32_STAR MSRs)
 */

#include "kernel.h"
#include "sched.h"

#define MSR_EFER        0xC0000080
#define MSR_STAR        0xC0000081
#define MSR_LSTAR       0xC0000082
#define MSR_FMASK       0xC0000084

// POSIX Linux Syscall Numbers
#define SYS_LINUX_READ        0
#define SYS_LINUX_WRITE       1
#define SYS_LINUX_OPEN        2
#define SYS_LINUX_CLOSE       3
#define SYS_LINUX_EXIT        60

// Windows NT / Win32 Syscall Numbers (x64)
#define SYS_WIN32_READ_FILE          0x0003
#define SYS_WIN32_WRITE_FILE         0x0008
#define SYS_WIN32_CLOSE              0x000F
#define SYS_WIN32_ALLOC_VIRT_MEM     0x0018
#define SYS_WIN32_FREE_VIRT_MEM      0x001E
#define SYS_WIN32_MAP_VIEW_OF_SECTION 0x0028
#define SYS_WIN32_TERMINATE_PROCESS  0x002C
#define SYS_WIN32_DELAY_EXECUTION    0x0034
#define SYS_WIN32_QUERY_SYS_INFO     0x0036
#define SYS_WIN32_CREATE_FILE        0x0055

static inline uint64_t rdmsr64(uint32_t msr) {
    uint32_t low, high;
    __asm__ volatile ("rdmsr" : "=a"(low), "=d"(high) : "c"(msr));
    return ((uint64_t)high << 32) | low;
}

static inline void wrmsr64(uint32_t msr, uint64_t value) {
    uint32_t low = (uint32_t)value;
    uint32_t high = (uint32_t)(value >> 32);
    __asm__ volatile ("wrmsr" : : "c"(msr), "a"(low), "d"(high));
}

/* Windows NT Subsystem Syscall Dispatcher */
static int64_t win32_syscall_dispatcher(uint64_t sys_num, uint64_t arg1, uint64_t arg2, uint64_t arg3) {
    switch (sys_num) {
        case SYS_WIN32_WRITE_FILE: {
            const char *buf = (const char *)arg2;
            size_t count = (size_t)arg3;
            kprintf("[WIN32:NtWriteFile] ");
            for (size_t i = 0; i < count; i++) {
                kprint_char(buf[i]);
            }
            return 0; // STATUS_SUCCESS
        }
        case SYS_WIN32_READ_FILE:
            return 0; // STATUS_SUCCESS (EOF)
        case SYS_WIN32_CLOSE:
            return 0;
        case SYS_WIN32_ALLOC_VIRT_MEM:
            serial_puts("[WIN32:NtAllocateVirtualMemory] User heap segment provisioned.\n");
            return 0; // STATUS_SUCCESS
        case SYS_WIN32_FREE_VIRT_MEM:
            serial_puts("[WIN32:NtFreeVirtualMemory] User heap memory released.\n");
            return 0; // STATUS_SUCCESS
        case SYS_WIN32_CREATE_FILE:
            serial_puts("[WIN32:NtCreateFile] Handled NT file handle creation request.\n");
            return 0; // STATUS_SUCCESS
        case SYS_WIN32_MAP_VIEW_OF_SECTION:
            serial_puts("[WIN32:NtMapViewOfSection] Section view mapped into user address space.\n");
            return 0; // STATUS_SUCCESS
        case SYS_WIN32_DELAY_EXECUTION:
            serial_puts("[WIN32:NtDelayExecution] Thread sleep quantum dispatched.\n");
            return 0; // STATUS_SUCCESS
        case SYS_WIN32_QUERY_SYS_INFO:
            serial_puts("[WIN32:NtQuerySystemInformation] Returning processor & architecture info.\n");
            return 0; // STATUS_SUCCESS
        case SYS_WIN32_TERMINATE_PROCESS:
            kprintf("[WIN32:NtTerminateProcess] Windows PE process exited code: %lu\n", arg1);
            sched_exit((int)arg1);
            return 0;
        default:
            serial_puts("[WIN32] Unimplemented NT system call service: 0x");
            char hex[9];
            for (int i = 7; i >= 0; i--) {
                int nibble = (sys_num >> (i * 4)) & 0xF;
                hex[7 - i] = (nibble < 10) ? ('0' + nibble) : ('a' + nibble - 10);
            }
            hex[8] = '\0';
            serial_puts(hex);
            serial_puts("\n");
            return -1; // STATUS_NOT_IMPLEMENTED
    }
}

/* Linux POSIX System V Syscall Dispatcher */
static int64_t linux_syscall_dispatcher(uint64_t sys_num, uint64_t arg1, uint64_t arg2, uint64_t arg3) {
    switch (sys_num) {
        case SYS_LINUX_WRITE: {
            int fd = (int)arg1;
            const char *buf = (const char *)arg2;
            size_t count = (size_t)arg3;
            if (fd == 1 || fd == 2) { // stdout or stderr
                for (size_t i = 0; i < count; i++) {
                    kprint_char(buf[i]);
                }
                return count;
            }
            return -1;
        }
        case SYS_LINUX_READ:
            return 0; // EOF for minimal stub
        case SYS_LINUX_OPEN:
            return 3; // Synthetic fd
        case SYS_LINUX_CLOSE:
            return 0;
        case SYS_LINUX_EXIT:
            kprintf("[LINUX:sys_exit] Process exited with status code: %lu\n", arg1);
            sched_exit((int)arg1);
            return 0;
        default:
            return -38; // -ENOSYS: Function not implemented
    }
}

/* Central Dual-Persona Syscall Dispatcher */
int64_t syscall_dispatcher(uint64_t sys_num, uint64_t arg1, uint64_t arg2, uint64_t arg3) {
    struct task *curr = sched_get_current();
    if (curr && curr->personality == PERSONALITY_WINDOWS) {
        return win32_syscall_dispatcher(sys_num, arg1, arg2, arg3);
    }
    return linux_syscall_dispatcher(sys_num, arg1, arg2, arg3);
}

uint64_t syscall_saved_user_rsp = 0;
uint8_t syscall_kernel_stack[16384] __attribute__((aligned(16)));

extern void syscall_entry_stub(void);

__asm__(
    ".global syscall_entry_stub\n\t"
    ".type syscall_entry_stub, @function\n\t"
    "syscall_entry_stub:\n\t"
    "movq %rsp, syscall_saved_user_rsp(%rip)\n\t"
    "leaq syscall_kernel_stack + 16384(%rip), %rsp\n\t"
    "pushq %r11\n\t"
    "pushq %rcx\n\t"
    "pushq %rbp\n\t"
    "pushq %rbx\n\t"
    "pushq %r12\n\t"
    "pushq %r13\n\t"
    "pushq %r14\n\t"
    "pushq %r15\n\t"
    "subq $8, %rsp\n\t"
    "movq %rdx, %rcx\n\t"
    "movq %rsi, %rdx\n\t"
    "movq %rdi, %rsi\n\t"
    "movq %rax, %rdi\n\t"
    "call syscall_dispatcher\n\t"
    "addq $8, %rsp\n\t"
    "popq %r15\n\t"
    "popq %r14\n\t"
    "popq %r13\n\t"
    "popq %r12\n\t"
    "popq %rbx\n\t"
    "popq %rbp\n\t"
    "popq %rcx\n\t"
    "popq %r11\n\t"
    "movq syscall_saved_user_rsp(%rip), %rsp\n\t"
    "sysretq\n\t"
);

void syscall_init(void) {
    serial_puts("[SYSCALL] Initializing x86_64 Fast System Call Extensions...\n");

    // Enable System Call Extensions (SCE, bit 0) in IA32_EFER
    uint64_t efer = rdmsr64(MSR_EFER);
    wrmsr64(MSR_EFER, efer | 1);

    // Setup STAR MSR:
    // Bits 47:32 = Kernel CS (0x08) & Kernel SS (0x10)
    // Bits 63:48 = Base for sysret: 0x0010 (sysret loads SS from STAR[63:48]+8=0x18, CS from STAR[63:48]+16=0x20)
    uint64_t star = ((uint64_t)0x0010 << 48) | ((uint64_t)0x0008 << 32);
    wrmsr64(MSR_STAR, star);

    // Setup LSTAR: Address of ring 0 fast syscall entry stub
    wrmsr64(MSR_LSTAR, (uint64_t)syscall_entry_stub);

    // Setup FMASK: Mask Interrupt Flag (bit 9) to prevent interrupts upon entering syscall
    wrmsr64(MSR_FMASK, 1 << 9);

    serial_puts("[SYSCALL] Fast System Call (LSTAR / STAR) MSRs configured.\n");
}
__SECURECURTAIN_EOF__

