cat << '__SECURECURTAIN_EOF__' > "${TARGET_DIR}/sys/kernel/src/mm/heap.c"
/* SecureCurtain OS - Kernel Heap & Slab Allocator
 * Author: Jared Busby (jb7572)
 * Architecture: x86_64 Freestanding
 */

#include "heap.h"
#include "vmm.h"
#include "pmm.h"
#include "kernel.h"

#define HEAP_START_VIRT   0xFFFFFFFF90000000ULL
#define HEAP_INITIAL_PAGES 16 // 64 KB Initial Kernel Heap

struct heap_block {
    size_t size;
    bool is_free;
    struct heap_block *next;
};

static struct heap_block *head_block = NULL;
static uintptr_t current_heap_break = HEAP_START_VIRT;

void heap_init(void) {
    serial_puts("[HEAP] Initializing Kernel Heap Allocator...\n");

    for (size_t i = 0; i < HEAP_INITIAL_PAGES; i++) {
        uintptr_t phys = pmm_alloc_frame();
        vmm_map_page(current_heap_break, phys, VMM_PAGE_PRESENT | VMM_PAGE_WRITABLE);
        current_heap_break += PAGE_SIZE;
    }

    head_block = (struct heap_block *)HEAP_START_VIRT;
    head_block->size = (HEAP_INITIAL_PAGES * PAGE_SIZE) - sizeof(struct heap_block);
    head_block->is_free = true;
    head_block->next = NULL;

    serial_puts("[HEAP] Kernel Dynamic Heap ready (Base: 0xFFFFFFFF90000000).\n");
}

static void expand_heap(size_t required_bytes) {
    size_t pages_needed = (required_bytes + PAGE_SIZE - 1) / PAGE_SIZE;
    if (pages_needed < 4) pages_needed = 4;

    uintptr_t new_block_virt = current_heap_break;

    for (size_t i = 0; i < pages_needed; i++) {
        uintptr_t phys = pmm_alloc_frame();
        vmm_map_page(current_heap_break, phys, VMM_PAGE_PRESENT | VMM_PAGE_WRITABLE);
        current_heap_break += PAGE_SIZE;
    }

    struct heap_block *new_block = (struct heap_block *)new_block_virt;
    new_block->size = (pages_needed * PAGE_SIZE) - sizeof(struct heap_block);
    new_block->is_free = true;
    new_block->next = NULL;

    // Attach to end of linked list
    struct heap_block *curr = head_block;
    while (curr->next != NULL) {
        curr = curr->next;
    }
    curr->next = new_block;
}

void *kmalloc(size_t size) {
    if (size == 0) return NULL;

    // Align size to 16 bytes
    size = (size + 15) & ~15;

    struct heap_block *curr = head_block;
    while (curr != NULL) {
        if (curr->is_free && curr->size >= size) {
            // Check if block can be split
            if (curr->size >= size + sizeof(struct heap_block) + 16) {
                struct heap_block *split = (struct heap_block *)((uint8_t *)curr + sizeof(struct heap_block) + size);
                split->size = curr->size - size - sizeof(struct heap_block);
                split->is_free = true;
                split->next = curr->next;

                curr->size = size;
                curr->next = split;
            }
            curr->is_free = false;
            return (void *)((uint8_t *)curr + sizeof(struct heap_block));
        }
        curr = curr->next;
    }

    // Heap exhausted, expand memory pool
    expand_heap(size + sizeof(struct heap_block));
    return kmalloc(size);
}

void *kzalloc(size_t size) {
    void *ptr = kmalloc(size);
    if (!ptr) return NULL;

    uint8_t *b = (uint8_t *)ptr;
    for (size_t i = 0; i < size; i++) {
        b[i] = 0;
    }
    return ptr;
}

void kfree(void *ptr) {
    if (!ptr) return;

    struct heap_block *block = (struct heap_block *)((uint8_t *)ptr - sizeof(struct heap_block));
    block->is_free = true;

    // Coalesce adjacent free blocks
    struct heap_block *curr = head_block;
    while (curr != NULL && curr->next != NULL) {
        if (curr->is_free && curr->next->is_free) {
            curr->size += sizeof(struct heap_block) + curr->next->size;
            curr->next = curr->next->next;
        } else {
            curr = curr->next;
        }
    }
}

void *krealloc(void *ptr, size_t new_size) {
    if (!ptr) return kmalloc(new_size);
    if (new_size == 0) {
        kfree(ptr);
        return NULL;
    }

    struct heap_block *block = (struct heap_block *)((uint8_t *)ptr - sizeof(struct heap_block));
    if (block->size >= new_size) return ptr;

    void *new_ptr = kmalloc(new_size);
    if (!new_ptr) return NULL;

    uint8_t *src = (uint8_t *)ptr;
    uint8_t *dst = (uint8_t *)new_ptr;
    for (size_t i = 0; i < block->size; i++) {
        dst[i] = src[i];
    }

    kfree(ptr);
    return new_ptr;
}
__SECURECURTAIN_EOF__

cat << '__SECURECURTAIN_EOF__' > "${TARGET_DIR}/sys/kernel/src/mm/pmm.c"
/* SecureCurtain OS - Physical Memory Manager (PMM) Dynamic Bitmap Allocator
 * Author: Jared Busby (jb7572)
 * Architecture: x86_64 Freestanding Long Mode
 *
 * Fully dynamic physical memory tracking:
 * Scales automatically to the exact maximum physical RAM supported by the host
 * motherboard, UEFI memory map, and CPU memory controller (e.g. 8GB, 64GB, 128GB, 256GB, 512GB, 1TB+).
 */

#include "pmm.h"
#include "kernel.h"
#include "multiboot2.h"

#define FRAMES_PER_BYTE 8

/* Linker symbol marking the physical/virtual end of kernel sections */
extern uint8_t _kernel_end[];

/* Pointer to the dynamically sized bitmap placed immediately after _kernel_end */
static uint8_t *pmm_bitmap = NULL;
static uint64_t max_physical_address = 0;
static uint64_t total_frames = 0;
static uint64_t used_frames = 0;
static uintptr_t bitmap_start_frame = 0;
static size_t bitmap_frame_count = 0;
static size_t bitmap_size_bytes = 0;

static inline void bitmap_set(size_t frame) {
    if (frame < total_frames && pmm_bitmap) {
        pmm_bitmap[frame / FRAMES_PER_BYTE] |= (1 << (frame % FRAMES_PER_BYTE));
    }
}

static inline void bitmap_clear(size_t frame) {
    if (frame < total_frames && pmm_bitmap) {
        pmm_bitmap[frame / FRAMES_PER_BYTE] &= ~(1 << (frame % FRAMES_PER_BYTE));
    }
}

static inline bool bitmap_test(size_t frame) {
    if (frame < total_frames && pmm_bitmap) {
        return (pmm_bitmap[frame / FRAMES_PER_BYTE] & (1 << (frame % FRAMES_PER_BYTE))) != 0;
    }
    return true; // Out-of-bounds treated as reserved/used
}

void pmm_init(uint64_t mem_map_addr, uint64_t mem_map_size) {
    serial_puts("[PMM] Probing Motherboard Memory Map for Dynamic Bitmap Sizing...\n");

    max_physical_address = 0;
    uint64_t reported_usable_ram = 0;

    // --- Pass 1: Discover Highest Physical Address of Usable RAM ---
    if (mem_map_addr != 0 && mem_map_size >= sizeof(struct multiboot_tag_mmap)) {
        struct multiboot_tag_mmap *mmap = (struct multiboot_tag_mmap *)mem_map_addr;
        if (mmap->entry_size > 0) {
            size_t num_entries = (mem_map_size - sizeof(struct multiboot_tag_mmap)) / mmap->entry_size;
            for (size_t i = 0; i < num_entries; i++) {
                struct multiboot_tag_mmap_entry *entry = (struct multiboot_tag_mmap_entry *)((uint8_t *)mmap->entries + (i * mmap->entry_size));
                if (entry->type == 1) { // Usable RAM ONLY
                    uint64_t entry_end = entry->addr + entry->len;
                    if (entry_end > max_physical_address) {
                        max_physical_address = entry_end;
                    }
                    reported_usable_ram += entry->len;
                }
            }
        }
    }

    // Fallback baseline: If no memory map provided or parsed, scale to safe default of 2 GB
    if (max_physical_address == 0) {
        max_physical_address = (2ULL * 1024 * 1024 * 1024); // 2 GB Safe Fallback
        reported_usable_ram = max_physical_address;
    }

    // Place the bitmap safely AFTER the kernel and AFTER the boot initramfs module
    extern struct multiboot_tag_module *boot_module_tag;
    uintptr_t kernel_phys_end = ((uintptr_t)&_kernel_end - KERNEL_VIRTUAL_BASE);
    kernel_phys_end = (kernel_phys_end + PAGE_SIZE - 1) & ~(PAGE_SIZE - 1);

    uintptr_t bitmap_phys_addr = kernel_phys_end;
    if (boot_module_tag && (uintptr_t)boot_module_tag->mod_end > bitmap_phys_addr) {
        bitmap_phys_addr = ((uintptr_t)boot_module_tag->mod_end + PAGE_SIZE - 1) & ~(PAGE_SIZE - 1);
    }

    // Ensure max_physical_address covers the module AND the bitmap itself
    if (bitmap_phys_addr > max_physical_address) {
        max_physical_address = bitmap_phys_addr;
    }

    // Align to 4KB page boundary
    (void)reported_usable_ram;
    max_physical_address = (max_physical_address + PAGE_SIZE - 1) & ~(PAGE_SIZE - 1);
    total_frames = max_physical_address / PAGE_SIZE;

    // Calculate required bitmap storage (1 bit per 4KB frame = 32KB per 1GB RAM)
    bitmap_size_bytes = (total_frames + FRAMES_PER_BYTE - 1) / FRAMES_PER_BYTE;
    bitmap_frame_count = (bitmap_size_bytes + PAGE_SIZE - 1) / PAGE_SIZE;

    // If bitmap extends beyond max_physical_address, expand to cover it
    if (bitmap_phys_addr + bitmap_size_bytes > max_physical_address) {
        max_physical_address = (bitmap_phys_addr + bitmap_size_bytes + PAGE_SIZE - 1) & ~(PAGE_SIZE - 1);
        total_frames = max_physical_address / PAGE_SIZE;
        bitmap_size_bytes = (total_frames + FRAMES_PER_BYTE - 1) / FRAMES_PER_BYTE;
        bitmap_frame_count = (bitmap_size_bytes + PAGE_SIZE - 1) / PAGE_SIZE;
    }

    bitmap_start_frame = bitmap_phys_addr / PAGE_SIZE;
    pmm_bitmap = (uint8_t *)(KERNEL_VIRTUAL_BASE + bitmap_phys_addr);

    // Step A: Mark all frames as used/reserved by default
    for (size_t i = 0; i < bitmap_size_bytes; i++) {
        pmm_bitmap[i] = 0xFF;
    }

    // Step B: Mark usable RAM ranges as free (bit = 0)
    if (mem_map_addr != 0 && mem_map_size >= sizeof(struct multiboot_tag_mmap)) {
        struct multiboot_tag_mmap *mmap = (struct multiboot_tag_mmap *)mem_map_addr;
        if (mmap->entry_size > 0) {
            size_t num_entries = (mem_map_size - sizeof(struct multiboot_tag_mmap)) / mmap->entry_size;
            for (size_t i = 0; i < num_entries; i++) {
                struct multiboot_tag_mmap_entry *entry = (struct multiboot_tag_mmap_entry *)((uint8_t *)mmap->entries + (i * mmap->entry_size));
                if (entry->type == 1) { // Usable RAM
                    uint64_t start_f = entry->addr / PAGE_SIZE;
                    uint64_t count_f = entry->len / PAGE_SIZE;
                    for (uint64_t f = 0; f < count_f && (start_f + f) < total_frames; f++) {
                        bitmap_clear(start_f + f);
                    }
                }
            }
        }
    } else {
        // Clear all frames if running in virtual fallback mode
        for (size_t f = 0; f < total_frames; f++) {
            bitmap_clear(f);
        }
    }

    // Step C: Protect essential system regions
    // 1. Lower 1MB (0x0 - 0x100000: Real-Mode IVT, BIOS BDA, EBDA, Video buffer)
    for (size_t f = 0; f < (1024 * 1024 / PAGE_SIZE); f++) {
        bitmap_set(f);
    }

    // 2. Kernel image (1MB to kernel_phys_end)
    size_t kernel_end_frame = kernel_phys_end / PAGE_SIZE;
    for (size_t f = (1024 * 1024 / PAGE_SIZE); f < kernel_end_frame && f < total_frames; f++) {
        bitmap_set(f);
    }

    // 3. Multiboot2 Initramfs/Ramdisk Module if loaded to prevent overwrites
    if (boot_module_tag) {
        uint64_t start_f = boot_module_tag->mod_start / PAGE_SIZE;
        uint64_t end_f = (boot_module_tag->mod_end + PAGE_SIZE - 1) / PAGE_SIZE;
        for (uint64_t f = start_f; f < end_f && f < total_frames; f++) {
            bitmap_set(f);
        }
    }

    // 4. Dynamic PMM Bitmap itself (bitmap_start_frame to bitmap_start_frame + bitmap_frame_count)
    for (size_t f = bitmap_start_frame; f < (bitmap_start_frame + bitmap_frame_count) && f < total_frames; f++) {
        bitmap_set(f);
    }

    // Calculate initial used frames
    used_frames = 0;
    for (size_t byte_idx = 0; byte_idx < bitmap_size_bytes; byte_idx++) {
        uint8_t byte = pmm_bitmap[byte_idx];
        if (byte == 0xFF) {
            used_frames += 8;
        } else if (byte != 0x00) {
            for (int b = 0; b < 8; b++) {
                if (byte & (1 << b)) used_frames++;
            }
        }
    }

    kprintf("[PMM] Dynamic Bitmap successfully configured.\n");
    kprintf("[PMM] Host Motherboard RAM Capacity: %lu MB (%lu GB)\n",
            max_physical_address / (1024ULL * 1024),
            max_physical_address / (1024ULL * 1024 * 1024));
    kprintf("[PMM] Total 4KB Frames: %lu | Bitmap Size: %lu KB\n",
            total_frames,
            bitmap_size_bytes / 1024);
    kprintf("[PMM] Usable Frames: %lu | Reserved/Used: %lu\n",
            total_frames - used_frames,
            used_frames);
}

uintptr_t pmm_alloc_frame(void) {
    if (!pmm_bitmap) {
        kernel_panic("PMM: Allocator invoked before pmm_init!");
        return 0;
    }

    for (size_t byte_idx = 0; byte_idx < bitmap_size_bytes; byte_idx++) {
        if (pmm_bitmap[byte_idx] != 0xFF) { // At least one free bit in byte
            for (int bit = 0; bit < 8; bit++) {
                if (!(pmm_bitmap[byte_idx] & (1 << bit))) {
                    size_t frame = byte_idx * 8 + bit;
                    if (frame < total_frames) {
                        bitmap_set(frame);
                        used_frames++;
                        return (uintptr_t)(frame * PAGE_SIZE);
                    }
                }
            }
        }
    }
    kernel_panic("PMM: Out of Physical Memory Frames!");
    return 0;
}

void pmm_free_frame(uintptr_t frame_addr) {
    if (!pmm_bitmap) return;
    size_t frame = frame_addr / PAGE_SIZE;
    if (frame < total_frames && bitmap_test(frame)) {
        bitmap_clear(frame);
        if (used_frames > 0) used_frames--;
    }
}

uintptr_t pmm_alloc_frames(size_t count) {
    if (count == 0) return 0;
    if (count == 1) return pmm_alloc_frame();
    if (!pmm_bitmap) return 0;

    size_t contiguous = 0;
    size_t start_frame = 0;
    size_t search_start = bitmap_start_frame + bitmap_frame_count;

    for (size_t f = search_start; f < total_frames; f++) {
        if (!bitmap_test(f)) {
            if (contiguous == 0) start_frame = f;
            contiguous++;
            if (contiguous == count) {
                for (size_t i = 0; i < count; i++) {
                    bitmap_set(start_frame + i);
                    used_frames++;
                }
                return (uintptr_t)(start_frame * PAGE_SIZE);
            }
        } else {
            contiguous = 0;
        }
    }
    kernel_panic("PMM: Failed to allocate contiguous physical frames!");
    return 0;
}

uint64_t pmm_get_total_memory(void) {
    return total_frames * PAGE_SIZE;
}

uint64_t pmm_get_used_memory(void) {
    return used_frames * PAGE_SIZE;
}

uint64_t pmm_get_free_memory(void) {
    return (total_frames > used_frames) ? (total_frames - used_frames) * PAGE_SIZE : 0;
}

uint64_t pmm_get_max_address(void) {
    return max_physical_address;
}

uint64_t pmm_get_total_frames(void) {
    return total_frames;
}

size_t pmm_get_bitmap_size_bytes(void) {
    return bitmap_size_bytes;
}
__SECURECURTAIN_EOF__

cat << '__SECURECURTAIN_EOF__' > "${TARGET_DIR}/sys/kernel/src/mm/vmm.c"
/* SecureCurtain OS - 4-Level PML4 Virtual Memory Manager (VMM)
 * Author: Jared Busby (jb7572)
 * Architecture: x86_64 Long Mode (48-bit Canonical Addressing)
 */

#include "vmm.h"
#include "pmm.h"
#include "kernel.h"

#define PAGE_TABLE_ENTRIES 512
#define PAGE_FRAME_MASK    0x000FFFFFFFFFF000ULL
#define PML4_INDEX(addr) (((addr) >> 39) & 0x1FF)
#define PDPT_INDEX(addr) (((addr) >> 30) & 0x1FF)
#define PD_INDEX(addr)   (((addr) >> 21) & 0x1FF)
#define PT_INDEX(addr)   (((addr) >> 12) & 0x1FF)

static uint64_t *kernel_pml4 = NULL;

static inline uint64_t read_cr2(void) {
    uint64_t cr2;
    __asm__ volatile ("mov %%cr2, %0" : "=r"(cr2));
    return cr2;
}

static inline uint64_t read_cr3(void) {
    uint64_t cr3;
    __asm__ volatile ("mov %%cr3, %0" : "=r"(cr3));
    return cr3;
}

static inline void write_cr3(uint64_t cr3) {
    __asm__ volatile ("mov %0, %%cr3" : : "r"(cr3) : "memory");
}

void vmm_init(void) {
    kprintf("[VMM] Initializing 4-Level Paging Subsystem...\n");

    // Allocate kernel PML4 root table
    uintptr_t pml4_phys = pmm_alloc_frame();
    if (!pml4_phys) {
        kernel_panic("VMM: Out of memory allocating kernel PML4!");
    }
    kernel_pml4 = (uint64_t *)(KERNEL_VIRTUAL_BASE + pml4_phys);

    for (size_t i = 0; i < PAGE_TABLE_ENTRIES; i++) {
        kernel_pml4[i] = 0;
    }

    // 1. Identity-map lower 16MB for BIOS/hardware compatibility (IVT, BDA, VGA buffer)
    for (uintptr_t addr = 0; addr < (16 * 1024 * 1024); addr += PAGE_SIZE) {
        vmm_map_page(addr, addr, VMM_PAGE_PRESENT | VMM_PAGE_WRITABLE);
    }

    // 2. Establish higher-half direct physical mapping window starting at KERNEL_VIRTUAL_BASE (0xFFFFFFFF80000000)
    // Map physical RAM up to 2GB (maximum addressable space in the 2GB higher-half window)
    uint64_t max_phys = pmm_get_max_address();
    uint64_t map_limit = (2ULL * 1024 * 1024 * 1024); // 2 GB Maximum Higher-Half Window
    if (max_phys > 0 && max_phys < map_limit) {
        // Round up to 2MB page directory boundary
        map_limit = (max_phys + (2 * 1024 * 1024 - 1)) & ~(2 * 1024 * 1024 - 1);
        if (map_limit < (256 * 1024 * 1024)) {
            map_limit = (256 * 1024 * 1024); // Minimum 256MB direct map
        }
    }

    kprintf("[VMM] Mapping direct physical higher-half window: 0x0 - 0x%lx (%lu MB)\n",
            map_limit, map_limit / (1024 * 1024));

    for (uintptr_t addr = 0; addr < map_limit; addr += PAGE_SIZE) {
        vmm_map_page(KERNEL_VIRTUAL_BASE + addr, addr, VMM_PAGE_PRESENT | VMM_PAGE_WRITABLE);
    }

    // Switch to new Kernel PML4
    write_cr3(pml4_phys);
    kprintf("[VMM] Kernel PML4 activated (CR3: 0x%lx). Virtual memory initialized.\n", (uint64_t)pml4_phys);
}

int vmm_map_page(uintptr_t virt_addr, uintptr_t phys_addr, uint64_t flags) {
    if (!kernel_pml4) return -1;

    size_t pml4_i = PML4_INDEX(virt_addr);
    size_t pdpt_i = PDPT_INDEX(virt_addr);
    size_t pd_i   = PD_INDEX(virt_addr);
    size_t pt_i   = PT_INDEX(virt_addr);

    // 1. PML4 -> PDPT
    if (!(kernel_pml4[pml4_i] & VMM_PAGE_PRESENT)) {
        uintptr_t new_pdpt = pmm_alloc_frame();
        if (!new_pdpt) return -1;
        kernel_pml4[pml4_i] = new_pdpt | VMM_PAGE_PRESENT | VMM_PAGE_WRITABLE | (flags & VMM_PAGE_USER);
        uint64_t *pdpt_ptr = (uint64_t *)(KERNEL_VIRTUAL_BASE + new_pdpt);
        for (int i = 0; i < PAGE_TABLE_ENTRIES; i++) pdpt_ptr[i] = 0;
    } else if (flags & VMM_PAGE_USER) {
        kernel_pml4[pml4_i] |= VMM_PAGE_USER;
    }

    uint64_t *pdpt = (uint64_t *)(KERNEL_VIRTUAL_BASE + (kernel_pml4[pml4_i] & PAGE_FRAME_MASK));

    // 2. PDPT -> PD
    if (!(pdpt[pdpt_i] & VMM_PAGE_PRESENT)) {
        uintptr_t new_pd = pmm_alloc_frame();
        if (!new_pd) return -1;
        pdpt[pdpt_i] = new_pd | VMM_PAGE_PRESENT | VMM_PAGE_WRITABLE | (flags & VMM_PAGE_USER);
        uint64_t *pd_ptr = (uint64_t *)(KERNEL_VIRTUAL_BASE + new_pd);
        for (int i = 0; i < PAGE_TABLE_ENTRIES; i++) pd_ptr[i] = 0;
    } else if (flags & VMM_PAGE_USER) {
        pdpt[pdpt_i] |= VMM_PAGE_USER;
    }

    uint64_t *pd = (uint64_t *)(KERNEL_VIRTUAL_BASE + (pdpt[pdpt_i] & PAGE_FRAME_MASK));

    // 3. PD -> PT
    if (!(pd[pd_i] & VMM_PAGE_PRESENT)) {
        uintptr_t new_pt = pmm_alloc_frame();
        if (!new_pt) return -1;
        pd[pd_i] = new_pt | VMM_PAGE_PRESENT | VMM_PAGE_WRITABLE | (flags & VMM_PAGE_USER);
        uint64_t *pt_ptr = (uint64_t *)(KERNEL_VIRTUAL_BASE + new_pt);
        for (int i = 0; i < PAGE_TABLE_ENTRIES; i++) pt_ptr[i] = 0;
    } else if (flags & VMM_PAGE_USER) {
        pd[pd_i] |= VMM_PAGE_USER;
    }

    uint64_t *pt = (uint64_t *)(KERNEL_VIRTUAL_BASE + (pd[pd_i] & PAGE_FRAME_MASK));

    // 4. Map PT entry to Physical Address
    pt[pt_i] = (phys_addr & PAGE_FRAME_MASK) | (flags & 0xFFFULL) | VMM_PAGE_PRESENT;

    vmm_invlpg(virt_addr);
    return 0;
}

void vmm_unmap_page(uintptr_t virt_addr) {
    if (!kernel_pml4) return;

    size_t pml4_i = PML4_INDEX(virt_addr);
    size_t pdpt_i = PDPT_INDEX(virt_addr);
    size_t pd_i   = PD_INDEX(virt_addr);
    size_t pt_i   = PT_INDEX(virt_addr);

    if (!(kernel_pml4[pml4_i] & VMM_PAGE_PRESENT)) return;
    uint64_t *pdpt = (uint64_t *)(KERNEL_VIRTUAL_BASE + (kernel_pml4[pml4_i] & PAGE_FRAME_MASK));

    if (!(pdpt[pdpt_i] & VMM_PAGE_PRESENT)) return;
    uint64_t *pd = (uint64_t *)(KERNEL_VIRTUAL_BASE + (pdpt[pdpt_i] & PAGE_FRAME_MASK));

    if (!(pd[pd_i] & VMM_PAGE_PRESENT)) return;
    uint64_t *pt = (uint64_t *)(KERNEL_VIRTUAL_BASE + (pd[pd_i] & PAGE_FRAME_MASK));

    pt[pt_i] = 0;
    vmm_invlpg(virt_addr);
}

uintptr_t vmm_virt_to_phys(uintptr_t virt_addr) {
    if (!kernel_pml4) return 0;

    size_t pml4_i = PML4_INDEX(virt_addr);
    size_t pdpt_i = PDPT_INDEX(virt_addr);
    size_t pd_i   = PD_INDEX(virt_addr);
    size_t pt_i   = PT_INDEX(virt_addr);

    if (!(kernel_pml4[pml4_i] & VMM_PAGE_PRESENT)) return 0;
    uint64_t *pdpt = (uint64_t *)(KERNEL_VIRTUAL_BASE + (kernel_pml4[pml4_i] & PAGE_FRAME_MASK));

    if (!(pdpt[pdpt_i] & VMM_PAGE_PRESENT)) return 0;
    uint64_t *pd = (uint64_t *)(KERNEL_VIRTUAL_BASE + (pdpt[pdpt_i] & PAGE_FRAME_MASK));

    if (!(pd[pd_i] & VMM_PAGE_PRESENT)) return 0;
    uint64_t *pt = (uint64_t *)(KERNEL_VIRTUAL_BASE + (pd[pd_i] & PAGE_FRAME_MASK));

    if (!(pt[pt_i] & VMM_PAGE_PRESENT)) return 0;
    return (pt[pt_i] & PAGE_FRAME_MASK) | (virt_addr & 0xFFF);
}

static uintptr_t next_mmio_virt = 0xFFFFFFFFC0000000ULL;

uintptr_t vmm_map_mmio(uintptr_t phys_addr, size_t size) {
    if (size == 0) size = PAGE_SIZE;
    uintptr_t phys_aligned = phys_addr & ~(PAGE_SIZE - 1);
    size_t offset = phys_addr & (PAGE_SIZE - 1);
    size_t total_size = (size + offset + PAGE_SIZE - 1) & ~(PAGE_SIZE - 1);

    uintptr_t virt = next_mmio_virt;
    next_mmio_virt += total_size;

    for (size_t i = 0; i < total_size; i += PAGE_SIZE) {
        vmm_map_page(virt + i, phys_aligned + i, VMM_PAGE_PRESENT | VMM_PAGE_WRITABLE | VMM_PAGE_NOCACHE);
    }

    return virt + offset;
}

void page_fault_handler(uint64_t fault_addr, uint64_t error_code) {
    uint64_t cr2 = read_cr2();
    kprintf("\n[!] EXCEPTION 14: PAGE FAULT (#PF)\n");
    kprintf("  Fault Virtual Address: 0x%016lx (CR2: 0x%016lx)\n", fault_addr, cr2);
    kprintf("  Error Code: 0x%lx [ ", error_code);
    if (error_code & 1) kprintf("PROTECTION_VIOLATION ");
    else kprintf("NON_PRESENT_PAGE ");
    if (error_code & 2) kprintf("WRITE ");
    else kprintf("READ ");
    if (error_code & 4) kprintf("USER_MODE ");
    else kprintf("KERNEL_MODE ");
    if (error_code & 8) kprintf("RESERVED_BIT ");
    if (error_code & 16) kprintf("INSTRUCTION_FETCH ");
    kprintf("]\n");

    kernel_panic("Unrecoverable Page Fault");
}
__SECURECURTAIN_EOF__

cat << '__SECURECURTAIN_EOF__' > "${TARGET_DIR}/sys/kernel/src/drivers/ahci.c"
/*
 * SecureCurtain OS - SATA Advanced Host Controller Interface (AHCI) Driver
 * Author: Jared Busby (jb7572)
 *
 * Implements AHCI 1.3+ Controller:
 * - Generic Host Control & Port Memory Registers
 * - Command List (32 Command Headers per port)
 * - Received FIS (Frame Information Structure) buffers
 * - Command Table with Physical Region Descriptor Table (PRDT)
 * - DMA Read/Write using ATA READ DMA EXT (0x25) and WRITE DMA EXT (0x35)
 */

#include <stdint.h>
#include <stdbool.h>
#include <stddef.h>

#define SATA_SIG_ATA    0x00000101
#define SATA_SIG_ATAPI  0xEB140101

#define AHCI_DEV_BUSY   0x80
#define AHCI_DEV_DRQ    0x08

/* AHCI Port Registers */
typedef volatile struct {
    uint32_t clb;
    uint32_t clbu;
    uint32_t fb;
    uint32_t fbu;
    uint32_t is;
    uint32_t ie;
    uint32_t cmd;
    uint32_t rsv0;
    uint32_t tfd;
    uint32_t sig;
    uint32_t ssts;
    uint32_t sctl;
    uint32_t serr;
    uint32_t sact;
    uint32_t ci;
    uint32_t sntf;
    uint32_t fbs;
    uint32_t rsv1[11];
    uint32_t vendor[4];
} ahci_port_t;

/* AHCI Generic Host Control */
typedef volatile struct {
    uint32_t cap;
    uint32_t ghc;
    uint32_t is;
    uint32_t pi;
    uint32_t vs;
    uint32_t ccc_ctl;
    uint32_t ccc_pts;
    uint32_t em_loc;
    uint32_t em_ctl;
    uint32_t cap2;
    uint32_t bohc;
    uint8_t  rsv[0xA0 - 0x2C];
    uint8_t  vendor[0x100 - 0xA0];
    ahci_port_t ports[32];
} ahci_hba_memory_t;

/* AHCI Command Header */
typedef struct {
    uint8_t  cfl:5;
    uint8_t  a:1;
    uint8_t  w:1;
    uint8_t  p:1;
    uint8_t  r:1;
    uint8_t  b:1;
    uint8_t  c:1;
    uint8_t  rsv0:1;
    uint8_t  pmp:4;
    uint16_t prdtl;
    volatile uint32_t prdbc;
    uint32_t ctba;
    uint32_t ctbau;
    uint32_t rsv1[4];
} ahci_cmd_header_t;

/* Physical Region Descriptor Table (PRDT) Entry */
typedef struct {
    uint32_t dba;
    uint32_t dbau;
    uint32_t rsv0;
    uint32_t dbc:22;
    uint32_t rsv1:9;
    uint32_t i:1;
} ahci_prdt_entry_t;

static ahci_hba_memory_t *g_abar = NULL;

extern void pit_wait_ms(uint32_t ms);

void ahci_start_cmd(ahci_port_t *port) {
    while (port->cmd & (1 << 15)); /* Wait until CR is 0 */
    port->cmd |= (1 << 4);         /* FRE = 1 */
    port->cmd |= (1 << 0);         /* ST = 1 */
}

void ahci_stop_cmd(ahci_port_t *port) {
    port->cmd &= ~(1 << 0);        /* ST = 0 */
    port->cmd &= ~(1 << 4);        /* FRE = 0 */
    while (port->cmd & (1 << 15)); /* Wait until CR is 0 */
    while (port->cmd & (1 << 14)); /* Wait until FR is 0 */
}

int ahci_init(uint64_t abar_physical_base) {
    g_abar = (ahci_hba_memory_t *)abar_physical_base;

    /* Enable AHCI Mode via GHC register */
    g_abar->ghc |= (1U << 31); /* AHCI Enable */

    uint32_t pi = g_abar->pi;
    for (int i = 0; i < 32; ++i) {
        if (pi & (1 << i)) {
            ahci_port_t *port = &g_abar->ports[i];
            uint32_t ssts = port->ssts;
            uint8_t ipm = (uint8_t)((ssts >> 8) & 0x0F);
            uint8_t det = (uint8_t)(ssts & 0x0F);

            if (det == 3 && ipm == 1) {
                /* Active SATA device present */
                if (port->sig == SATA_SIG_ATA) {
                    ahci_stop_cmd(port);
                    ahci_start_cmd(port);
                }
            }
        }
    }

    return 0;
}
__SECURECURTAIN_EOF__

