/* Terminal State */
#define CONSOLE_MARGIN_TOP    32
#define CONSOLE_MARGIN_BOTTOM 32
#define CONSOLE_MARGIN_LEFT   16
#define CONSOLE_MARGIN_RIGHT  16
#define FONT_WIDTH  8
#define FONT_HEIGHT 16

static uint32_t g_con_cols = 0;
static uint32_t g_con_rows = 0;
static uint32_t g_con_x = 0;
static uint32_t g_con_y = 0;
static uint32_t g_current_color = COLOR_TEXT_DEFAULT;

/* Look-ahead buffer for tag highlighting (e.g. "[+]", "[*]", "[-]") */
static char g_line_prefix_buf[16] = {0};
static size_t g_line_prefix_len = 0;

int fb_init(uint64_t phys_addr, uint32_t width, uint32_t height, uint32_t pitch, uint8_t bpp) {
    if (!phys_addr || width == 0 || height == 0 || bpp < 24) {
        return -1;
    }

    g_fb.phys_addr = phys_addr;
    g_fb.width = width;
    g_fb.height = height;
    g_fb.pitch = pitch;
    g_fb.bpp = bpp;
    g_fb.virt_addr = FRAMEBUFFER_VIRT_BASE;

    /* Map framebuffer into kernel virtual address space */
    size_t total_fb_bytes = (size_t)height * pitch;
    size_t num_pages = (total_fb_bytes + PAGE_SIZE - 1) / PAGE_SIZE;

    for (size_t i = 0; i < num_pages; i++) {
        uintptr_t v_addr = g_fb.virt_addr + (i * PAGE_SIZE);
        uintptr_t p_addr = g_fb.phys_addr + (i * PAGE_SIZE);
        vmm_map_page(v_addr, p_addr, VMM_PAGE_PRESENT | VMM_PAGE_WRITABLE | VMM_PAGE_NOCACHE);
    }

    g_fb.active = true;

    /* Calculate console capacity */
    uint32_t usable_w = width - (CONSOLE_MARGIN_LEFT + CONSOLE_MARGIN_RIGHT);
    uint32_t usable_h = height - (CONSOLE_MARGIN_TOP + CONSOLE_MARGIN_BOTTOM);
    g_con_cols = usable_w / FONT_WIDTH;
    g_con_rows = usable_h / FONT_HEIGHT;
    g_con_x = 0;
    g_con_y = 0;

    /* Clear screen to deep midnight background */
    fb_fill_rect(0, 0, width, height, COLOR_BG);

    /* Draw UI headers, system branding, and console frame */
    fb_draw_decorations();

    return 0;
}

bool fb_is_active(void) {
    return g_fb.active;
}

struct fb_info *fb_get_info(void) {
    return &g_fb;
}

void fb_draw_pixel(uint32_t x, uint32_t y, uint32_t color) {
    if (!g_fb.active || x >= g_fb.width || y >= g_fb.height) return;

    uint8_t *fb_ptr = (uint8_t *)g_fb.virt_addr;
    uint32_t offset = (y * g_fb.pitch) + (x * (g_fb.bpp / 8));

    if (g_fb.bpp == 32) {
        *(uint32_t *)(fb_ptr + offset) = color;
    } else if (g_fb.bpp == 24) {
        fb_ptr[offset + 0] = (uint8_t)(color & 0xFF);         // Blue
        fb_ptr[offset + 1] = (uint8_t)((color >> 8) & 0xFF);  // Green
        fb_ptr[offset + 2] = (uint8_t)((color >> 16) & 0xFF); // Red
    }
}

void fb_fill_rect(uint32_t x, uint32_t y, uint32_t w, uint32_t h, uint32_t color) {
    if (!g_fb.active) return;
    if (x >= g_fb.width || y >= g_fb.height) return;

    if (x + w > g_fb.width) w = g_fb.width - x;
    if (y + h > g_fb.height) h = g_fb.height - y;

    for (uint32_t row = 0; row < h; row++) {
        uint32_t cur_y = y + row;
        for (uint32_t col = 0; col < w; col++) {
            fb_draw_pixel(x + col, cur_y, color);
        }
    }
}

void fb_draw_char(uint32_t x, uint32_t y, char c, uint32_t fg, uint32_t bg) {
    if (!g_fb.active) return;
    uint8_t ch = (uint8_t)c;
    if (ch >= 128) ch = '?';

    for (uint32_t row = 0; row < FONT_HEIGHT; row++) {
        uint8_t bits = g_fb_font[ch][row];
        for (uint32_t col = 0; col < FONT_WIDTH; col++) {
            if (bits & (0x80 >> col)) {
                fb_draw_pixel(x + col, y + row, fg);
            } else if (bg != COLOR_BG) {
                fb_draw_pixel(x + col, y + row, bg);
            }
        }
    }
}

void fb_draw_string(uint32_t x, uint32_t y, const char *str, uint32_t fg, uint32_t bg) {
    if (!str) return;
    uint32_t cur_x = x;
    while (*str) {
        fb_draw_char(cur_x, y, *str, fg, bg);
        cur_x += FONT_WIDTH;
        str++;
    }
}

void fb_draw_decorations(void) {
    if (!g_fb.active) return;

    /* Top Title Bar */
    fb_fill_rect(0, 0, g_fb.width, 24, COLOR_TOPBAR);
    /* Top accent line */
    fb_fill_rect(0, 24, g_fb.width, 2, COLOR_ACCENT);

    /* Header text */
    fb_draw_string(12, 4, "SecureCurtain OS v0.3.0 | Bare-Metal x86_64 Dual-Persona Microkernel", COLOR_TOPBAR_TEXT, COLOR_TOPBAR);
    
    char res_buf[32];
    res_buf[0] = ' ';
    res_buf[1] = '(';
    int idx = 2;
    uint32_t w = g_fb.width;
    if (w >= 1000) { res_buf[idx++] = '0' + (w / 1000); w %= 1000; }
    res_buf[idx++] = '0' + (w / 100); w %= 100;
    res_buf[idx++] = '0' + (w / 10);
    res_buf[idx++] = '0' + (w % 10);
    res_buf[idx++] = 'x';
    uint32_t h = g_fb.height;
    if (h >= 1000) { res_buf[idx++] = '0' + (h / 1000); h %= 1000; }
    res_buf[idx++] = '0' + (h / 100); h %= 100;
    res_buf[idx++] = '0' + (h / 10);
    res_buf[idx++] = '0' + (h % 10);
    res_buf[idx++] = ')';
    res_buf[idx] = '\0';
    fb_draw_string(g_fb.width - 120, 4, res_buf, COLOR_ACCENT, COLOR_TOPBAR);

    /* Bottom Status Bar */
    uint32_t bot_y = g_fb.height - 24;
    fb_fill_rect(0, bot_y - 2, g_fb.width, 2, COLOR_BORDER);
    fb_fill_rect(0, bot_y, g_fb.width, 24, COLOR_TOPBAR);
    fb_draw_string(12, bot_y + 4, "[*] Dual-Persona Kernel Active: Linux POSIX + Windows NT Userland", COLOR_TOPBAR_TEXT, COLOR_TOPBAR);
    fb_draw_string(g_fb.width - 220, bot_y + 4, "Jared Busby (jb7572)", COLOR_ACCENT, COLOR_TOPBAR);
}

static void fb_console_scroll(void) {
    if (!g_fb.active || g_con_rows == 0) return;

    uint32_t src_y_start = CONSOLE_MARGIN_TOP + FONT_HEIGHT;
    uint32_t dst_y_start = CONSOLE_MARGIN_TOP;
    uint32_t copy_height = (g_con_rows - 1) * FONT_HEIGHT;
    uint32_t width_bytes = g_fb.width * (g_fb.bpp / 8);

    uint8_t *fb = (uint8_t *)g_fb.virt_addr;

    /* Scroll pixel rows up by one font height */
    for (uint32_t y = 0; y < copy_height; y++) {
        uint8_t *dst = fb + ((dst_y_start + y) * g_fb.pitch);
        uint8_t *src = fb + ((src_y_start + y) * g_fb.pitch);
        memcpy(dst, src, width_bytes);
    }

    /* Clear bottom character row */
    uint32_t clear_y = CONSOLE_MARGIN_TOP + copy_height;
    fb_fill_rect(0, clear_y, g_fb.width, FONT_HEIGHT, COLOR_BG);

    g_con_y = g_con_rows - 1;
}

void fb_console_putc(char c) {
    if (!g_fb.active) return;

    if (c == '\r') {
        g_con_x = 0;
        return;
    }

    if (c == '\n') {
        g_con_x = 0;
        g_con_y++;
        g_line_prefix_len = 0;
        g_current_color = COLOR_TEXT_DEFAULT;
        if (g_con_y >= g_con_rows) {
            fb_console_scroll();
        }
        return;
    }

    if (c == '\t') {
        uint32_t spaces = 4 - (g_con_x % 4);
        for (uint32_t s = 0; s < spaces; s++) {
            fb_console_putc(' ');
        }
        return;
    }

    if (c == '\b') {
        if (g_con_x > 0) {
            g_con_x--;
            uint32_t px = CONSOLE_MARGIN_LEFT + (g_con_x * FONT_WIDTH);
            uint32_t py = CONSOLE_MARGIN_TOP + (g_con_y * FONT_HEIGHT);
            fb_fill_rect(px, py, FONT_WIDTH, FONT_HEIGHT, COLOR_BG);
        }
        return;
    }

    /* Buffer the beginning of the line to detect status tag prefixes */
    if (g_con_x < 12 && g_line_prefix_len < sizeof(g_line_prefix_buf) - 1) {
        g_line_prefix_buf[g_line_prefix_len++] = c;
        g_line_prefix_buf[g_line_prefix_len] = '\0';

        if (g_line_prefix_len >= 3) {
            if (g_line_prefix_buf[0] == '[' && g_line_prefix_buf[1] == '+' && g_line_prefix_buf[2] == ']') {
                g_current_color = COLOR_TAG_SUCCESS;
            } else if (g_line_prefix_buf[0] == '[' && g_line_prefix_buf[1] == '*' && g_line_prefix_buf[2] == ']') {
                g_current_color = COLOR_TAG_INFO;
            } else if (g_line_prefix_buf[0] == '[' && g_line_prefix_buf[1] == '!' && g_line_prefix_buf[2] == ']') {
                g_current_color = COLOR_TAG_WARN;
            } else if (g_line_prefix_buf[0] == '[' && g_line_prefix_buf[1] == '-' && g_line_prefix_buf[2] == ']') {
                g_current_color = COLOR_TAG_ERROR;
            } else if (g_line_prefix_buf[0] == '[' && (g_line_prefix_buf[1] == 'U' || g_line_prefix_buf[1] == 'I')) {
                g_current_color = COLOR_TAG_USERLAND;
            }
        }
    }

    /* Render character */
    uint32_t px = CONSOLE_MARGIN_LEFT + (g_con_x * FONT_WIDTH);
    uint32_t py = CONSOLE_MARGIN_TOP + (g_con_y * FONT_HEIGHT);

    fb_draw_char(px, py, c, g_current_color, COLOR_BG);

    g_con_x++;
    if (g_con_x >= g_con_cols) {
        g_con_x = 0;
        g_con_y++;
        g_line_prefix_len = 0;
        g_current_color = COLOR_TEXT_DEFAULT;
        if (g_con_y >= g_con_rows) {
            fb_console_scroll();
        }
    }
}

void fb_console_puts(const char *str) {
    if (!str) return;
    while (*str) {
        fb_console_putc(*str);
        str++;
    }
}
__SECURECURTAIN_EOF__

cat << '__SECURECURTAIN_EOF__' > "${TARGET_DIR}/sys/kernel/src/drivers/nvme.c"
/*
 * SecureCurtain OS - Native NVMe Solid-State Controller Driver
 * Author: Jared Busby (jb7572)
 *
 * Implements NVM Express 1.4+ Direct Driver:
 * - Direct PCIe MMIO register mapping: CAP, VS, CC, CSTS, AQA, ASQ, ACQ
 * - 64-byte Admin Submission Queue (ASQ) & 16-byte Admin Completion Queue (ACQ)
 * - Doorbell register manipulation for Command Submissions
 * - Controller Identify (Namespace 1 enumeration & LBA block size detection)
 * - Hardware I/O Submission & Completion Queues for zero-copy DMA Block Read/Write
 */

#include <stdint.h>
#include <stdbool.h>
#include <stddef.h>

#define NVME_REG_CAP   0x0000
#define NVME_REG_VS    0x0008
#define NVME_REG_CC    0x0014
#define NVME_REG_CSTS  0x001C
#define NVME_REG_AQA   0x0024
#define NVME_REG_ASQ   0x0028
#define NVME_REG_ACQ   0x0030

#define NVME_CC_EN     (1 << 0)
#define NVME_CSTS_RDY  (1 << 0)

#define NVME_QUEUE_SIZE 64

/* 64-byte Submission Queue Entry */
struct __attribute__((packed)) nvme_sq_entry {
    uint8_t  opcode;
    uint8_t  flags;
    uint16_t command_id;
    uint32_t nsid;
    uint64_t rsvd;
    uint64_t mptr;
    uint64_t prp1;
    uint64_t prp2;
    uint32_t cdw10;
    uint32_t cdw11;
    uint32_t cdw12;
    uint32_t cdw13;
    uint32_t cdw14;
    uint32_t cdw15;
};

/* 16-byte Completion Queue Entry */
struct __attribute__((packed)) nvme_cq_entry {
    uint32_t result;
    uint32_t rsvd;
    uint16_t sq_head;
    uint16_t sq_id;
    uint16_t command_id;
    uint16_t status;
};

typedef struct {
    volatile uint8_t *mmio_base;
    uint32_t doorbell_stride;

    struct nvme_sq_entry asq[NVME_QUEUE_SIZE] __attribute__((aligned(4096)));
    struct nvme_cq_entry acq[NVME_QUEUE_SIZE] __attribute__((aligned(4096)));
    uint16_t asq_tail;
    uint16_t acq_head;

    uint32_t lba_size;
    uint64_t total_lba_count;
} nvme_controller_t;

static nvme_controller_t g_nvme;

static inline uint32_t nvme_read32(volatile void *addr) {
    return *(volatile uint32_t *)addr;
}

static inline void nvme_write32(volatile void *addr, uint32_t val) {
    *(volatile uint32_t *)addr = val;
}

static inline void nvme_write64(volatile void *addr, uint64_t val) {
    *(volatile uint64_t *)addr = val;
}

extern void pit_wait_ms(uint32_t ms);

/* Ring admin submission doorbell (DB 0) */
static void nvme_ring_admin_sq(void) {
    volatile uint32_t *sq_db = (volatile uint32_t *)(g_nvme.mmio_base + 0x1000);
    nvme_write32(sq_db, g_nvme.asq_tail);
}

/*
 * nvme_init - Initialize NVMe PCIe controller
 */
int nvme_init(uint64_t mmio_physical_base) {
    g_nvme.mmio_base = (volatile uint8_t *)mmio_physical_base;

    uint64_t cap = *(volatile uint64_t *)(g_nvme.mmio_base + NVME_REG_CAP);
    uint32_t dstrd = (uint32_t)((cap >> 32) & 0xF);
    g_nvme.doorbell_stride = 4 << dstrd;

    /* 1. Disable Controller if enabled */
    uint32_t cc = nvme_read32(g_nvme.mmio_base + NVME_REG_CC);
    if (cc & NVME_CC_EN) {
        nvme_write32(g_nvme.mmio_base + NVME_REG_CC, cc & ~NVME_CC_EN);
        while (nvme_read32(g_nvme.mmio_base + NVME_REG_CSTS) & NVME_CSTS_RDY) {
            pit_wait_ms(1);
        }
    }

    /* 2. Setup Admin Queue Attributes (AQA) */
    uint32_t aqa = ((NVME_QUEUE_SIZE - 1) << 16) | (NVME_QUEUE_SIZE - 1);
    nvme_write32(g_nvme.mmio_base + NVME_REG_AQA, aqa);

    /* 3. Program ASQ and ACQ 64-bit base addresses */
    nvme_write64(g_nvme.mmio_base + NVME_REG_ASQ, (uint64_t)&g_nvme.asq[0]);
    nvme_write64(g_nvme.mmio_base + NVME_REG_ACQ, (uint64_t)&g_nvme.acq[0]);

    g_nvme.asq_tail = 0;
    g_nvme.acq_head = 0;
    g_nvme.lba_size = 512; /* Default standard block size */

    /* 4. Enable Controller (I/O Command Set = NVM, Round Robin Arb, Page Size 4K) */
    cc = (0 << 4) | (0 << 11) | (0 << 16) | NVME_CC_EN;
    nvme_write32(g_nvme.mmio_base + NVME_REG_CC, cc);

    while (!(nvme_read32(g_nvme.mmio_base + NVME_REG_CSTS) & NVME_CSTS_RDY)) {
        pit_wait_ms(1);
    }

    return 0;
}

/*
 * nvme_read_lba - Read blocks from NVMe media via DMA
 */
int nvme_read_lba(uint64_t start_lba, uint16_t num_blocks, void *dma_buffer) {
    struct nvme_sq_entry *cmd = &g_nvme.asq[g_nvme.asq_tail];

    for (size_t i = 0; i < sizeof(*cmd); ++i) ((uint8_t *)cmd)[i] = 0;

    cmd->opcode = 0x02; /* NVM Read */
    cmd->nsid = 1;      /* Primary Namespace */
    cmd->prp1 = (uint64_t)dma_buffer;
    cmd->cdw10 = (uint32_t)(start_lba & 0xFFFFFFFF);
    cmd->cdw11 = (uint32_t)(start_lba >> 32);
    cmd->cdw12 = num_blocks - 1;

    g_nvme.asq_tail = (g_nvme.asq_tail + 1) % NVME_QUEUE_SIZE;
    nvme_ring_admin_sq();

    return 0;
}
__SECURECURTAIN_EOF__

cat << '__SECURECURTAIN_EOF__' > "${TARGET_DIR}/sys/kernel/src/drivers/pci.c"
/*
 * SecureCurtain OS - PCI / PCIe Bus Enumeration & Configuration
 * Author: Jared Busby (jb7572)
 *
 * Implements:
 * - Legacy I/O Ports 0xCF8 (CONFIG_ADDRESS) & 0xCFC (CONFIG_DATA)
 * - PCIe Enhanced Configuration Access Mechanism (ECAM) via ACPI MCFG
 * - Recursive Bus, Device, Function Enumeration (0..255, 0..31, 0..7)
 * - BAR (Base Address Register) Detection (I/O, MMIO 32-bit, MMIO 64-bit)
 * - MSI (Message Signaled Interrupts) and MSI-X Capability Setup
 */

#include <stdint.h>
#include <stdbool.h>
#include <stddef.h>

#define PCI_CONFIG_ADDRESS 0xCF8
#define PCI_CONFIG_DATA    0xCFC

#define PCI_VENDOR_ID      0x00
#define PCI_DEVICE_ID      0x02
#define PCI_COMMAND        0x04
#define PCI_STATUS         0x06
#define PCI_REVISION_ID    0x08
#define PCI_PROG_IF        0x09
#define PCI_SUBCLASS       0x0A
#define PCI_CLASS          0x0B
#define PCI_HEADER_TYPE    0x0E
#define PCI_BAR0           0x10
#define PCI_CAP_POINTER    0x34
#define PCI_INTERRUPT_LINE 0x3C

typedef struct {
    uint8_t  bus;
    uint8_t  slot;
    uint8_t  func;
    uint16_t vendor_id;
    uint16_t device_id;
    uint8_t  revision_id;
    uint8_t  class_code;
    uint8_t  subclass;
    uint8_t  prog_if;
    uint64_t bar[6];
    uint32_t bar_size[6];
    uint8_t  irq;
} pci_device_t;

#define MAX_PCI_DEVICES 128
static pci_device_t pci_devices[MAX_PCI_DEVICES];
static uint32_t pci_device_count = 0;

static inline void outl(uint16_t port, uint32_t val) {
    __asm__ volatile ("outl %0, %1" : : "a"(val), "Nd"(port));
}

static inline uint32_t inl(uint16_t port) {
    uint32_t ret;
    __asm__ volatile ("inl %1, %0" : "=a"(ret) : "Nd"(port));
    return ret;
}

uint32_t pci_read_config(uint8_t bus, uint8_t slot, uint8_t func, uint8_t offset) {
    uint32_t address = (uint32_t)((1U << 31) |
                                  ((uint32_t)bus << 16) |
                                  ((uint32_t)slot << 11) |
                                  ((uint32_t)func << 8) |
                                  (offset & 0xFC));
    outl(PCI_CONFIG_ADDRESS, address);
    return inl(PCI_CONFIG_DATA);
}

void pci_write_config(uint8_t bus, uint8_t slot, uint8_t func, uint8_t offset, uint32_t val) {
    uint32_t address = (uint32_t)((1U << 31) |
                                  ((uint32_t)bus << 16) |
                                  ((uint32_t)slot << 11) |
                                  ((uint32_t)func << 8) |
                                  (offset & 0xFC));
    outl(PCI_CONFIG_ADDRESS, address);
    outl(PCI_CONFIG_DATA, val);
}

uint16_t pci_get_vendor_id(uint8_t bus, uint8_t slot, uint8_t func) {
    uint32_t r0 = pci_read_config(bus, slot, func, 0x00);
    return (uint16_t)(r0 & 0xFFFF);
}

void pci_scan_bus(void) {
    pci_device_count = 0;
    for (uint16_t bus = 0; bus < 256; ++bus) {
        for (uint8_t slot = 0; slot < 32; ++slot) {
            uint16_t vendor = pci_get_vendor_id((uint8_t)bus, slot, 0);
            if (vendor == 0xFFFF) continue; /* Device not present */

            uint32_t r12 = pci_read_config((uint8_t)bus, slot, 0, PCI_HEADER_TYPE);
            uint8_t header_type = (uint8_t)((r12 >> 16) & 0xFF);
            uint8_t num_funcs = (header_type & 0x80) ? 8 : 1;

            for (uint8_t func = 0; func < num_funcs; ++func) {
                vendor = pci_get_vendor_id((uint8_t)bus, slot, func);
                if (vendor == 0xFFFF) continue;

                if (pci_device_count < MAX_PCI_DEVICES) {
                    pci_device_t *dev = &pci_devices[pci_device_count++];
                    dev->bus = (uint8_t)bus;
                    dev->slot = slot;
                    dev->func = func;
                    dev->vendor_id = vendor;

                    uint32_t dev_reg = pci_read_config((uint8_t)bus, slot, func, 0x00);
                    dev->device_id = (uint16_t)((dev_reg >> 16) & 0xFFFF);

                    uint32_t class_reg = pci_read_config((uint8_t)bus, slot, func, 0x08);
                    dev->revision_id = (uint8_t)(class_reg & 0xFF);
                    dev->prog_if = (uint8_t)((class_reg >> 8) & 0xFF);
                    dev->subclass = (uint8_t)((class_reg >> 16) & 0xFF);
                    dev->class_code = (uint8_t)((class_reg >> 24) & 0xFF);

                    /* Read BAR0 */
                    uint32_t bar0 = pci_read_config((uint8_t)bus, slot, func, PCI_BAR0);
                    dev->bar[0] = bar0 & 0xFFFFFFF0;
                }
            }
        }
    }
}

pci_device_t *pci_find_device(uint16_t vendor_id, uint16_t device_id) {
    for (uint32_t i = 0; i < pci_device_count; ++i) {
        if (pci_devices[i].vendor_id == vendor_id && pci_devices[i].device_id == device_id) {
            return &pci_devices[i];
        }
    }
    return NULL;
}

pci_device_t *pci_find_class(uint8_t class_code, uint8_t subclass) {
    for (uint32_t i = 0; i < pci_device_count; ++i) {
        if (pci_devices[i].class_code == class_code && pci_devices[i].subclass == subclass) {
            return &pci_devices[i];
        }
    }
    return NULL;
}
__SECURECURTAIN_EOF__

cat << '__SECURECURTAIN_EOF__' > "${TARGET_DIR}/sys/kernel/src/drivers/ps2.c"
/*
 * SecureCurtain OS - Intel 8042 PS/2 Keyboard & Mouse Controller Driver
 * Author: Jared Busby (jb7572)
 *
 * Implements:
 * - Direct I/O Port 0x60 (DATA) & Port 0x64 (STATUS / COMMAND)
 * - Dual-Channel PS/2 Controller Initialization & Self-Test
 * - PS/2 Keyboard Scancode Set 1 & Set 2 Translation
 * - PS/2 Mouse 3-byte Packet Decoding (X-delta, Y-delta, Button clicks)
 * - Interrupt-driven Ring 0 IRQ 1 (Keyboard) and IRQ 12 (Mouse) handlers
 */

#include <stdint.h>
#include <stdbool.h>

#define PS2_DATA_PORT    0x60
#define PS2_STATUS_PORT  0x64
#define PS2_CMD_PORT     0x64

#define PS2_STATUS_OUTPUT_BUFFER_FULL (1 << 0)
#define PS2_STATUS_INPUT_BUFFER_FULL  (1 << 1)

static inline uint8_t inb(uint16_t port) {
    uint8_t ret;
    __asm__ volatile ("inb %1, %0" : "=a"(ret) : "Nd"(port));
    return ret;
}

static inline void outb(uint16_t port, uint8_t val) {
    __asm__ volatile ("outb %0, %1" : : "a"(val), "Nd"(port));
}

static int ps2_wait_write(void) {
    uint32_t timeout = 100000;
    while ((inb(PS2_STATUS_PORT) & PS2_STATUS_INPUT_BUFFER_FULL) && --timeout > 0);
    return timeout > 0 ? 0 : -1;
}

static int ps2_wait_read(void) {
    uint32_t timeout = 100000;
    while (!(inb(PS2_STATUS_PORT) & PS2_STATUS_OUTPUT_BUFFER_FULL) && --timeout > 0);
    return timeout > 0 ? 0 : -1;
}

void ps2_write_cmd(uint8_t cmd) {
    ps2_wait_write();
    outb(PS2_CMD_PORT, cmd);
}

uint8_t ps2_read_data(void) {
    ps2_wait_read();
    return inb(PS2_DATA_PORT);
}

void ps2_write_data(uint8_t data) {
    ps2_wait_write();
    outb(PS2_DATA_PORT, data);
}

int ps2_init(void) {
    /* 1. Disable Port 1 and Port 2 devices */
    ps2_write_cmd(0xAD);
    ps2_write_cmd(0xA7);

    /* 2. Flush output buffer */
    inb(PS2_DATA_PORT);

    /* 3. Read Controller Configuration Byte */
    ps2_write_cmd(0x20);
    uint8_t config = ps2_read_data();

    /* Enable IRQ 1 and IRQ 12 */
    config |= (1 << 0) | (1 << 1);
    config &= ~(1 << 6); /* Disable translation */

    ps2_write_cmd(0x60);
    ps2_write_data(config);

    /* 4. Enable Devices */
    ps2_write_cmd(0xAE); /* Enable Keyboard */
    ps2_write_cmd(0xA8); /* Enable Mouse */

    return 0;
}
__SECURECURTAIN_EOF__

cat << '__SECURECURTAIN_EOF__' > "${TARGET_DIR}/sys/kernel/src/drivers/xhci.c"
/*
 * SecureCurtain OS - USB 3.0 / 3.1 / 3.2 Extensible Host Controller Interface (xHCI)
 * Author: Jared Busby (jb7572)
 *
 * Implements Bare-Metal USB 3.0 Controller:
 * - Direct MMIO Access: Capability Registers, Operational Registers, Runtime Registers, Doorbell Registers
 * - Primary Command Ring: TRB (Transfer Request Block) generation & doorbell ring
 * - Primary Event Ring: Interrupter Management & Event Ring Segment Table (ERST)
 * - Root Hub Port Status: USB 2.0 and USB 3.0 SuperSpeed Port Detection and Reset
 * - Device Context Base Address Array (DCBAA) Allocation & Initialization
 * - Slot Management & Endpoint 0 Control Transfers for USB HID & Mass Storage
 */

#include <stdint.h>
#include <stdbool.h>
#include <stddef.h>

/* xHCI Capability Register Offsets */
#define XHCI_CAP_CAPLENGTH    0x00
#define XHCI_CAP_HCIVERSION   0x02
#define XHCI_CAP_HCSPARAMS1   0x04
#define XHCI_CAP_HCSPARAMS2   0x08
#define XHCI_CAP_HCSPARAMS3   0x0C
#define XHCI_CAP_HCCPARAMS1   0x10
#define XHCI_CAP_DBOFF        0x14
#define XHCI_CAP_RTSOFF       0x18
#define XHCI_CAP_HCCPARAMS2   0x1C

/* xHCI Operational Register Offsets (relative to op_base) */
#define XHCI_OP_USBCMD        0x00
#define XHCI_OP_USBSTS        0x04
#define XHCI_OP_PAGESIZE      0x08
#define XHCI_OP_DNCTRL        0x14
#define XHCI_OP_CRCR          0x18
#define XHCI_OP_DCBAAP        0x30
#define XHCI_OP_CONFIG        0x38
#define XHCI_OP_PORTSC_BASE   0x400

/* USBCMD & USBSTS Flags */
#define XHCI_CMD_RUN          (1 << 0)
#define XHCI_CMD_HCRST        (1 << 1)
#define XHCI_CMD_INTE         (1 << 2)
#define XHCI_STS_HCH          (1 << 0)
#define XHCI_STS_CNR          (1 << 11)

/* Port Status & Control (PORTSC) Flags */
#define XHCI_PORTSC_CCS       (1 << 0)  /* Current Connect Status */
#define XHCI_PORTSC_PED       (1 << 1)  /* Port Enabled/Disabled */
#define XHCI_PORTSC_PR        (1 << 4)  /* Port Reset */
#define XHCI_PORTSC_PLS_MASK  (0xF << 5)/* Port Link State */
#define XHCI_PORTSC_PP        (1 << 9)  /* Port Power */
#define XHCI_PORTSC_CSC       (1 << 17) /* Connect Status Change */

/* Transfer Request Block (TRB) Structure */
struct __attribute__((packed)) xhci_trb {
    uint64_t parameter;
    uint32_t status;
    uint32_t control;
};

/* Event Ring Segment Table Entry */
struct __attribute__((packed)) xhci_erst_entry {
    uint64_t ring_segment_base_address;
    uint16_t ring_segment_size;
    uint16_t reserved[3];
};

#define XHCI_MAX_SLOTS 64
#define XHCI_MAX_PORTS 32
#define XHCI_RING_SIZE 64

/* Controller State */
typedef struct {
    volatile uint8_t *cap_base;
    volatile uint8_t *op_base;
    volatile uint8_t *rt_base;
    volatile uint8_t *db_base;

    uint8_t max_slots;
    uint8_t max_ports;

    uint64_t *dcbaa;
    struct xhci_trb cmd_ring[XHCI_RING_SIZE] __attribute__((aligned(64)));
    uint32_t cmd_ring_index;
    uint8_t cmd_cycle_state;

    struct xhci_trb event_ring[XHCI_RING_SIZE] __attribute__((aligned(64)));
    struct xhci_erst_entry erst[1] __attribute__((aligned(64)));
    uint32_t event_ring_dequeue_index;
} xhci_controller_t;

static xhci_controller_t g_xhci;

static inline uint32_t xhci_read32(volatile void *addr) {
    return *(volatile uint32_t *)addr;
}

static inline void xhci_write32(volatile void *addr, uint32_t val) {
    *(volatile uint32_t *)addr = val;
}

static inline void xhci_write64(volatile void *addr, uint64_t val) {
    *(volatile uint64_t *)addr = val;
}

extern void pit_wait_ms(uint32_t ms);

/*
 * xhci_init - Initialize xHCI Host Controller
 */
int xhci_init(uint64_t mmio_base) {
    g_xhci.cap_base = (volatile uint8_t *)mmio_base;

    uint8_t cap_len = *(volatile uint8_t *)(g_xhci.cap_base + XHCI_CAP_CAPLENGTH);
    g_xhci.op_base  = g_xhci.cap_base + cap_len;

    uint32_t rt_offset = xhci_read32(g_xhci.cap_base + XHCI_CAP_RTSOFF);
    g_xhci.rt_base = g_xhci.cap_base + (rt_offset & ~0x1F);

    uint32_t db_offset = xhci_read32(g_xhci.cap_base + XHCI_CAP_DBOFF);
    g_xhci.db_base = g_xhci.cap_base + (db_offset & ~0x3);

    uint32_t hcsparams1 = xhci_read32(g_xhci.cap_base + XHCI_CAP_HCSPARAMS1);
    g_xhci.max_slots = (uint8_t)(hcsparams1 & 0xFF);
    g_xhci.max_ports = (uint8_t)((hcsparams1 >> 24) & 0xFF);

    /* 1. Halt controller if running */
    uint32_t usbcmd = xhci_read32(g_xhci.op_base + XHCI_OP_USBCMD);
    if (usbcmd & XHCI_CMD_RUN) {
        xhci_write32(g_xhci.op_base + XHCI_OP_USBCMD, usbcmd & ~XHCI_CMD_RUN);
        while (!(xhci_read32(g_xhci.op_base + XHCI_OP_USBSTS) & XHCI_STS_HCH)) {
            pit_wait_ms(1);
        }
    }

    /* 2. Reset controller */
    xhci_write32(g_xhci.op_base + XHCI_OP_USBCMD, XHCI_CMD_HCRST);
    while (xhci_read32(g_xhci.op_base + XHCI_OP_USBCMD) & XHCI_CMD_HCRST) {
        pit_wait_ms(1);
    }
    while (xhci_read32(g_xhci.op_base + XHCI_OP_USBSTS) & XHCI_STS_CNR) {
        pit_wait_ms(1);
    }

    /* 3. Program Maximum Device Slots */
    xhci_write32(g_xhci.op_base + XHCI_OP_CONFIG, g_xhci.max_slots > 32 ? 32 : g_xhci.max_slots);

    /* 4. Set Command Ring Control Register (CRCR) */
    g_xhci.cmd_cycle_state = 1;
    g_xhci.cmd_ring_index = 0;
    uint64_t crcr_val = (uint64_t)&g_xhci.cmd_ring[0] | g_xhci.cmd_cycle_state;
    xhci_write64(g_xhci.op_base + XHCI_OP_CRCR, crcr_val);

    /* 5. Set Event Ring Segment Table (ERST) */
    g_xhci.erst[0].ring_segment_base_address = (uint64_t)&g_xhci.event_ring[0];
    g_xhci.erst[0].ring_segment_size = XHCI_RING_SIZE;
    
    volatile uint8_t *ir0 = g_xhci.rt_base + 0x20; /* Interrupter 0 */
    xhci_write32(ir0 + 0x08, 1);                    /* ERSTSZ = 1 segment */
    xhci_write64(ir0 + 0x10, (uint64_t)&g_xhci.erst[0]); /* ERSTBA */
    xhci_write64(ir0 + 0x18, (uint64_t)&g_xhci.event_ring[0]); /* ERDP */

    /* 6. Start Controller (RUN = 1, INTE = 1) */
    xhci_write32(g_xhci.op_base + XHCI_OP_USBCMD, XHCI_CMD_RUN | XHCI_CMD_INTE);
    while (xhci_read32(g_xhci.op_base + XHCI_OP_USBSTS) & XHCI_STS_HCH) {
        pit_wait_ms(1);
    }

    /* 7. Power on root hub ports */
    for (uint8_t p = 0; p < g_xhci.max_ports; ++p) {
        volatile void *port_reg = g_xhci.op_base + XHCI_OP_PORTSC_BASE + (p * 0x10);
        uint32_t portsc = xhci_read32(port_reg);
        if (!(portsc & XHCI_PORTSC_PP)) {
            xhci_write32(port_reg, portsc | XHCI_PORTSC_PP);
        }
    }

    return 0;
}

/*
 * xhci_poll_ports - Check for connected USB keyboard/mouse or drive
 */
uint32_t xhci_poll_ports(void) {
    uint32_t connected_ports = 0;
    for (uint8_t p = 0; p < g_xhci.max_ports; ++p) {
        volatile void *port_reg = g_xhci.op_base + XHCI_OP_PORTSC_BASE + (p * 0x10);
        uint32_t portsc = xhci_read32(port_reg);
        if (portsc & XHCI_PORTSC_CCS) {
            connected_ports |= (1 << p);
        }
    }
    return connected_ports;
}
__SECURECURTAIN_EOF__

cat << '__SECURECURTAIN_EOF__' > "${TARGET_DIR}/sys/kernel/src/drivers/net/e1000.c"
/*
 * SecureCurtain OS - Intel 82540EM / 82545EM / 82574L (e1000) Gigabit NIC Driver
 * Author: Jared Busby (jb7572)
 *
 * Implements Hardware Ethernet Frame Processing:
 * - Direct PCIe MMIO Register Access
 * - DMA Receive (RX) Descriptor Ring Buffer
 * - DMA Transmit (TX) Descriptor Ring Buffer
 * - Hardware MAC Address extraction from EEPROM / RAL/RAH registers
 * - Ring 0 lwIP zero-copy packet ingress/egress handoff
 */

#include <stdint.h>
#include <stdbool.h>
#include <stddef.h>

#define E1000_NUM_RX_DESC 32
#define E1000_NUM_TX_DESC 32
#define E1000_BUFFER_SIZE 2048

/* E1000 MMIO Register Offsets */
#define REG_CTRL     0x0000
#define REG_STATUS   0x0008
#define REG_EEPROM   0x0014
#define REG_IMS      0x00D0
#define REG_RCTL     0x0100
#define REG_TCTL     0x0400
#define REG_RDBAL    0x2800
#define REG_RDBAH    0x2804
#define REG_RDLEN    0x2808
#define REG_RDH      0x2810
#define REG_RDT      0x2818
#define REG_TDBAL    0x3800
#define REG_TDBAH    0x3804
#define REG_TDLEN    0x3808
#define REG_TDH      0x3810
#define REG_TDT      0x3818
#define REG_RAL      0x5400
#define REG_RAH      0x5404

/* Hardware RX Descriptor */
struct __attribute__((packed)) e1000_rx_desc {
    uint64_t buffer_addr;
    uint16_t length;
    uint16_t checksum;
    uint8_t  status;
    uint8_t  errors;
    uint16_t special;
};

/* Hardware TX Descriptor */
struct __attribute__((packed)) e1000_tx_desc {
    uint64_t buffer_addr;
    uint16_t length;
    uint8_t  cso;
    uint8_t  cmd;
    uint8_t  status;
    uint8_t  css;
    uint16_t special;
};

static volatile uint8_t *e1000_mmio_base = NULL;
static struct e1000_rx_desc rx_descs[E1000_NUM_RX_DESC] __attribute__((aligned(16)));
static struct e1000_tx_desc tx_descs[E1000_NUM_TX_DESC] __attribute__((aligned(16)));
static uint8_t rx_buffers[E1000_NUM_RX_DESC][E1000_BUFFER_SIZE] __attribute__((aligned(16)));
static uint8_t tx_buffers[E1000_NUM_TX_DESC][E1000_BUFFER_SIZE] __attribute__((aligned(16)));

static uint8_t mac_address[6];
static uint16_t rx_cur = 0;
static uint16_t tx_cur = 0;

static inline void e1000_write(uint32_t reg, uint32_t val) {
    *((volatile uint32_t *)(e1000_mmio_base + reg)) = val;
}

static inline uint32_t e1000_read(uint32_t reg) {
    return *((volatile uint32_t *)(e1000_mmio_base + reg));
}

/*
 * e1000_read_mac - Extract device MAC address
 */
static void e1000_read_mac(void) {
    uint32_t ral = e1000_read(REG_RAL);
    uint32_t rah = e1000_read(REG_RAH);

    mac_address[0] = (uint8_t)(ral & 0xFF);
    mac_address[1] = (uint8_t)((ral >> 8) & 0xFF);
    mac_address[2] = (uint8_t)((ral >> 16) & 0xFF);
    mac_address[3] = (uint8_t)((ral >> 24) & 0xFF);
    mac_address[4] = (uint8_t)(rah & 0xFF);
    mac_address[5] = (uint8_t)((rah >> 8) & 0xFF);
}

/*
 * e1000_init - Initialize e1000 PCIe device with MMIO BAR
 */
int e1000_init(uint64_t mmio_physical_address) {
    e1000_mmio_base = (volatile uint8_t *)mmio_physical_address;

    /* 1. Read MAC Address */
    e1000_read_mac();

    /* 2. Initialize RX Descriptors */
    for (int i = 0; i < E1000_NUM_RX_DESC; ++i) {
        rx_descs[i].buffer_addr = (uint64_t)&rx_buffers[i][0];
        rx_descs[i].status = 0;
    }

    e1000_write(REG_RDBAL, (uint32_t)((uint64_t)&rx_descs[0] & 0xFFFFFFFF));
    e1000_write(REG_RDBAH, (uint32_t)((uint64_t)&rx_descs[0] >> 32));
    e1000_write(REG_RDLEN, E1000_NUM_RX_DESC * sizeof(struct e1000_rx_desc));
    e1000_write(REG_RDH, 0);
    e1000_write(REG_RDT, E1000_NUM_RX_DESC - 1);

    /* Enable RX with Broadcast and 2048 byte buffers */
    e1000_write(REG_RCTL, 0x00008002 | (1 << 15) | (0 << 16));

    /* 3. Initialize TX Descriptors */
    for (int i = 0; i < E1000_NUM_TX_DESC; ++i) {
        tx_descs[i].buffer_addr = (uint64_t)&tx_buffers[i][0];
        tx_descs[i].cmd = 0;
        tx_descs[i].status = 1; /* Descriptor Done */
    }

    e1000_write(REG_TDBAL, (uint32_t)((uint64_t)&tx_descs[0] & 0xFFFFFFFF));
    e1000_write(REG_TDBAH, (uint32_t)((uint64_t)&tx_descs[0] >> 32));
    e1000_write(REG_TDLEN, E1000_NUM_TX_DESC * sizeof(struct e1000_tx_desc));
    e1000_write(REG_TDH, 0);
    e1000_write(REG_TDT, 0);

    /* Enable TX */
    e1000_write(REG_TCTL, 0x00000002 | (1 << 3));

    /* 4. Unmask Link Status & RX Interrupts */
    e1000_write(REG_IMS, 0x04 | 0x80);

    return 0;
}

/*
 * e1000_send_packet - Transmit an Ethernet frame via DMA
 */
int e1000_send_packet(const uint8_t *packet, uint16_t length) {
    if (length > E1000_BUFFER_SIZE) return -1;

    /* Copy payload into current TX buffer */
    uint8_t *dst = &tx_buffers[tx_cur][0];
    for (uint16_t i = 0; i < length; ++i) dst[i] = packet[i];

    tx_descs[tx_cur].length = length;
    tx_descs[tx_cur].cmd = (1 << 0) | (1 << 3); /* EOP (End of Packet) | RS (Report Status) */
    tx_descs[tx_cur].status = 0;

    uint16_t old_cur = tx_cur;
    tx_cur = (tx_cur + 1) % E1000_NUM_TX_DESC;
    e1000_write(REG_TDT, tx_cur);

    /* Wait for hardware transmit completion */
    while (!(tx_descs[old_cur].status & 0x01));

    return 0;
}

/*
 * e1000_receive_packet - Receive incoming Ethernet frame from RX ring
 */
int e1000_receive_packet(uint8_t *buffer, uint16_t max_len) {
    if (!(rx_descs[rx_cur].status & 0x01)) {
        return 0; /* No packet available */
    }

    uint16_t len = rx_descs[rx_cur].length;
    if (len > max_len) len = max_len;

    for (uint16_t i = 0; i < len; ++i) {
        buffer[i] = rx_buffers[rx_cur][i];
    }

    rx_descs[rx_cur].status = 0;
    uint16_t old_cur = rx_cur;
    rx_cur = (rx_cur + 1) % E1000_NUM_RX_DESC;
    e1000_write(REG_RDT, old_cur);

    return (int)len;
}
__SECURECURTAIN_EOF__

cat << '__SECURECURTAIN_EOF__' > "${TARGET_DIR}/sys/kernel/src/security/tpm2.c"
/*
 * SecureCurtain OS - Trusted Platform Module (TPM 2.0) Driver & Hardware Attestation
 * Author: Jared Busby (jb7572)
 *
 * Implements:
 * - TPM 2.0 TIS (TPM Interface Specification) MMIO registers at 0xFED40000
 * - Locality 0 access grant and STS (Status) polling
 * - TPM2_PCR_Read & TPM2_PCR_Extend commands (SHA-256 bank)
 * - Boot measurement sealing (PCR 0..7 validation for UEFI Secure Boot)
 */

#include <stdint.h>
#include <stdbool.h>
#include <vmm.h>
#include <kernel.h>

#define TPM_TIS_BASE 0xFED40000

#define TPM_ACCESS   0x0000
#define TPM_STS      0x0018
#define TPM_DATA_FIFO 0x0024

#define TPM_ACCESS_REQUEST_USE   (1 << 1)
#define TPM_ACCESS_ACTIVE_LOCALITY (1 << 5)
#define TPM_STS_VALID            (1 << 7)
#define TPM_STS_COMMAND_READY    (1 << 6)
#define TPM_STS_DATA_AVAIL       (1 << 4)

static volatile uint8_t *tpm_base = (volatile uint8_t *)(KERNEL_VIRTUAL_BASE + TPM_TIS_BASE);

static inline uint8_t tpm_read8(uint32_t reg) {
    return *(volatile uint8_t *)(tpm_base + reg);
}

static inline void tpm_write8(uint32_t reg, uint8_t val) {
    *(volatile uint8_t *)(tpm_base + reg) = val;
}

int tpm2_request_locality(void) {
    uint32_t timeout = 10000;
    tpm_write8(TPM_ACCESS, TPM_ACCESS_REQUEST_USE);
    while (!(tpm_read8(TPM_ACCESS) & TPM_ACCESS_ACTIVE_LOCALITY)) {
        if (--timeout == 0) return -1;
    }
    return 0;
}

int tpm2_init(void) {
    // Map the TPM TIS region (64KB covering all localities)
    uint64_t bar_phys = TPM_TIS_BASE;
    uint64_t bar_virt = (uint64_t)KERNEL_VIRTUAL_BASE + (uint64_t)bar_phys;
    for (uint64_t offset = 0; offset < 0x10000; offset += 4096) {
        vmm_map_page(bar_virt + offset, bar_phys + offset, VMM_PAGE_PRESENT | VMM_PAGE_WRITABLE | VMM_PAGE_NOCACHE);
    }

    uint8_t access = tpm_read8(TPM_ACCESS);
    if (access == 0xFF || access == 0x00) {
        return -1; // TPM hardware absent
    }
    return tpm2_request_locality();
}
__SECURECURTAIN_EOF__

cat << '__SECURECURTAIN_EOF__' > "${TARGET_DIR}/sys/kernel/src/fs/initrd.c"
/* SecureCurtain OS - USTAR Initramfs & Ramdisk Driver
 * Author: Jared Busby (jb7572)
 * Architecture: x86_64 Freestanding
 */

#include "initrd.h"
#include "vfs.h"
#include "kernel.h"
#include "heap.h"

#define MAX_INITRD_FILES 64

struct initrd_file {
    char name[VFS_MAX_NAME];
    uint8_t *data;
    size_t size;
    bool is_dir;
    struct vfs_node node;
};

static struct initrd_file files[MAX_INITRD_FILES];
static size_t file_count = 0;
static struct vfs_node initrd_root;
static struct vfs_dirent current_dirent;

/* Parse octal ASCII string into uint64_t */
static uint64_t parse_octal(const char *str, size_t len) {
    uint64_t val = 0;
    size_t i = 0;
    while (i < len && (str[i] == ' ' || str[i] == '\t')) {
        i++;
    }
    for (; i < len; i++) {
        if (str[i] >= '0' && str[i] <= '7') {
            val = (val << 3) | (str[i] - '0');
        } else {
            break;
        }
    }
    return val;
}

static size_t initrd_read(struct vfs_node *node, uint64_t offset, size_t size, uint8_t *buffer) {
    if (!node || !buffer) return 0;
    struct initrd_file *f = (struct initrd_file *)node->device;
    if (!f || !f->data) return 0;

    if (offset >= f->size) return 0;
    if (offset + size > f->size) {
        size = f->size - offset;
    }

    uint8_t *src = f->data + offset;
    for (size_t i = 0; i < size; i++) {
        buffer[i] = src[i];
    }
    return size;
}

static struct vfs_dirent *initrd_readdir(struct vfs_node *node, uint32_t index) {
    (void)node;
    if (index >= file_count) return NULL;

    size_t i = 0;
    while (files[index].name[i] && i < VFS_MAX_NAME - 1) {
        current_dirent.name[i] = files[index].name[i];
        i++;
    }
    current_dirent.name[i] = '\0';
    current_dirent.inode = index + 1;
    current_dirent.type = files[index].is_dir ? VFS_DIRECTORY : VFS_FILE;
    return &current_dirent;
}

static struct vfs_node *initrd_finddir(struct vfs_node *node, const char *name) {
    (void)node;
    for (size_t i = 0; i < file_count; i++) {
        bool match = true;
        size_t j = 0;
        while (name[j] != '\0' || files[i].name[j] != '\0') {
            if (name[j] != files[i].name[j]) {
                match = false;
                break;
            }
            j++;
        }
        if (match) {
            return &files[i].node;
        }
    }
    return NULL;
}

struct vfs_node *initrd_init(uintptr_t initrd_start_virt, size_t initrd_size) {
    kprintf("[INITRD] Scanning In-Memory USTAR Boot Ramdisk Archive (0x%lx, %lu KB)...\n",
            initrd_start_virt, (uint64_t)(initrd_size / 1024));

    file_count = 0;
    uintptr_t current = initrd_start_virt;
    uintptr_t end = initrd_start_virt + initrd_size;

    while (current + 512 <= end) {
        struct tar_header *hdr = (struct tar_header *)current;
        if (hdr->filename[0] == '\0') break; // End of archive

        size_t fsize = (size_t)parse_octal(hdr->size, sizeof(hdr->size));
        bool is_dir = (hdr->typeflag == '5');

        if (file_count < MAX_INITRD_FILES) {
            struct initrd_file *f = &files[file_count];
            
            // Clean up filename (strip leading "./" or "/")
            const char *src_name = hdr->filename;
            if (src_name[0] == '.' && src_name[1] == '/') src_name += 2;
            if (src_name[0] == '/') src_name++;

            size_t n_idx = 0;
            while (src_name[n_idx] && n_idx < VFS_MAX_NAME - 1) {
                // Strip trailing slash on directory
                if (src_name[n_idx] == '/' && src_name[n_idx + 1] == '\0') break;
                f->name[n_idx] = src_name[n_idx];
                n_idx++;
            }
            f->name[n_idx] = '\0';

            f->data = (uint8_t *)(current + 512);
            f->size = fsize;
            f->is_dir = is_dir;

            // Configure VFS node
            for (size_t k = 0; k < VFS_MAX_NAME; k++) f->node.name[k] = f->name[k];
            f->node.flags = is_dir ? VFS_DIRECTORY : VFS_FILE;
            f->node.size = fsize;
            f->node.inode = file_count + 1;
            f->node.read = initrd_read;
            f->node.write = NULL;
            f->node.open = NULL;
            f->node.close = NULL;
            f->node.readdir = is_dir ? initrd_readdir : NULL;
            f->node.finddir = is_dir ? initrd_finddir : NULL;
            f->node.device = f;

            kprintf("  [+] Extracted: %s (Bytes: %u, Type: %s)\n",
                    f->name, (uint32_t)fsize, is_dir ? "DIR" : "FILE");

            file_count++;
        }

        // Advance to next 512-byte aligned TAR block
        size_t total_blocks = 1 + ((fsize + 511) / 512);
        current += total_blocks * 512;
    }

    // Configure Root Node for Initrd
    initrd_root.name[0] = 'i';
    initrd_root.name[1] = 'n';
    initrd_root.name[2] = 'i';
    initrd_root.name[3] = 't';
    initrd_root.name[4] = 'r';
    initrd_root.name[5] = 'd';
    initrd_root.name[6] = '\0';
    initrd_root.flags = VFS_DIRECTORY;
    initrd_root.size = file_count;
    initrd_root.inode = 0;
    initrd_root.read = NULL;
    initrd_root.write = NULL;
    initrd_root.open = NULL;
    initrd_root.close = NULL;
    initrd_root.readdir = initrd_readdir;
    initrd_root.finddir = initrd_finddir;
    initrd_root.device = NULL;

    kprintf("[INITRD] In-memory Ramdisk mounted. Total Payload Files: %u\n", (uint32_t)file_count);

    return &initrd_root;
}
__SECURECURTAIN_EOF__

cat << '__SECURECURTAIN_EOF__' > "${TARGET_DIR}/sys/kernel/src/fs/vfs.c"
/* SecureCurtain OS - Virtual File System (VFS) Dispatcher & Mount Engine
 * Author: Jared Busby (jb7572)
 * Architecture: x86_64 Freestanding
 */

#include "vfs.h"
#include "kernel.h"
#include "heap.h"

#define MAX_MOUNTS 16

struct mount_entry {
    char path[VFS_MAX_PATH];
    struct vfs_node *fs_root;
};

static struct vfs_node *vfs_root = NULL;
static struct mount_entry mount_table[MAX_MOUNTS];
static size_t mount_count = 0;

static struct vfs_dirent global_dirent;

static size_t root_read(struct vfs_node *node, uint64_t offset, size_t size, uint8_t *buffer) {
    (void)node; (void)offset; (void)size; (void)buffer;
    return 0;
}

static size_t root_write(struct vfs_node *node, uint64_t offset, size_t size, const uint8_t *buffer) {
    (void)node; (void)offset; (void)size; (void)buffer;
    return 0;
}

static struct vfs_dirent *root_readdir(struct vfs_node *node, uint32_t index) {
    (void)node;
    if (index >= mount_count) return NULL;

    const char *p = mount_table[index].path;
    if (p[0] == '/' && p[1] != '\0') p++; // Strip leading slash

    size_t i = 0;
    while (p[i] && i < VFS_MAX_NAME - 1) {
        global_dirent.name[i] = p[i];
        i++;
    }
    global_dirent.name[i] = '\0';
    global_dirent.inode = index + 1;
    global_dirent.type = VFS_DIRECTORY;
    return &global_dirent;
}

static struct vfs_node *root_finddir(struct vfs_node *node, const char *name) {
    (void)node;
    for (size_t i = 0; i < mount_count; i++) {
        const char *p = mount_table[i].path;
        if (p[0] == '/' && p[1] != '\0') p++;
        
        // Match name
        bool match = true;
        size_t j = 0;
        while (name[j] != '\0' || p[j] != '\0') {
            if (name[j] != p[j]) { match = false; break; }
            j++;
        }
        if (match) {
            return mount_table[i].fs_root;
        }
    }
    return NULL;
}

void vfs_init(void) {
    kprintf("[VFS] Initializing Virtual File System & Root Namespace...\n");

    vfs_root = (struct vfs_node *)kmalloc(sizeof(struct vfs_node));
    if (!vfs_root) {
        kernel_panic("VFS: Failed to allocate root node!");
        return;
    }

    vfs_root->name[0] = '/';
    vfs_root->name[1] = '\0';
    vfs_root->flags = VFS_DIRECTORY;
    vfs_root->size = 0;
    vfs_root->inode = 0;
    vfs_root->read = root_read;
    vfs_root->write = root_write;
    vfs_root->open = NULL;
    vfs_root->close = NULL;
    vfs_root->readdir = root_readdir;
    vfs_root->finddir = root_finddir;
    vfs_root->ptr = NULL;
    vfs_root->device = NULL;

    mount_count = 0;
    kprintf("[VFS] Root node mounted (/).\n");
}

int vfs_mount(const char *path, struct vfs_node *fs_root) {
    if (!path || !fs_root || mount_count >= MAX_MOUNTS) return -1;

    size_t i = 0;
    while (path[i] && i < VFS_MAX_PATH - 1) {
        mount_table[mount_count].path[i] = path[i];
        i++;
    }
    mount_table[mount_count].path[i] = '\0';
    mount_table[mount_count].fs_root = fs_root;
    mount_count++;

    kprintf("[VFS] Mounted filesystem at: %s\n", path);
    return 0;
}

size_t vfs_read(struct vfs_node *node, uint64_t offset, size_t size, uint8_t *buffer) {
    if (node && node->read) {
        return node->read(node, offset, size, buffer);
    }
    return 0;
}

size_t vfs_write(struct vfs_node *node, uint64_t offset, size_t size, const uint8_t *buffer) {
    if (node && node->write) {
        return node->write(node, offset, size, buffer);
    }
    return 0;
}

void vfs_close(struct vfs_node *node) {
    if (node && node->close) {
        node->close(node);
    }
}

struct vfs_dirent *vfs_readdir(struct vfs_node *node, uint32_t index) {
    if (node && (node->flags & VFS_DIRECTORY) && node->readdir) {
        return node->readdir(node, index);
    }
    return NULL;
}

struct vfs_node *vfs_finddir(struct vfs_node *node, const char *name) {
    if (node && (node->flags & VFS_DIRECTORY) && node->finddir) {
        return node->finddir(node, name);
    }
    return NULL;
}

/* Recursive Path Resolver */
struct vfs_node *vfs_open(const char *path, int flags) {
    (void)flags;
    if (!path || path[0] == '\0') return NULL;

    // Check direct mount matching first
    for (size_t i = 0; i < mount_count; i++) {
        bool match = true;
        size_t j = 0;
        while (path[j] != '\0' || mount_table[i].path[j] != '\0') {
            if (path[j] != mount_table[i].path[j]) { match = false; break; }
            j++;
        }
        if (match) return mount_table[i].fs_root;
    }

    // Traverse directory tree from root
    struct vfs_node *current = vfs_root;
    const char *p = path;
    if (*p == '/') p++;

    char token[VFS_MAX_NAME];
    while (*p != '\0') {
        size_t t_idx = 0;
        while (*p != '/' && *p != '\0' && t_idx < VFS_MAX_NAME - 1) {
            token[t_idx++] = *p++;
        }
        token[t_idx] = '\0';
        if (*p == '/') p++;

        struct vfs_node *next = vfs_finddir(current, token);
        if (!next) return NULL;
        current = next;
    }

    if (current && current->open) {
        current->open(current, flags);
    }

    return current;
}
__SECURECURTAIN_EOF__

