    uint16_t      next_cmd_id;
    uint64_t      total_sectors_read;
    uint64_t      total_sectors_written;
    uint64_t      cache_hits;
    uint64_t      cache_misses;
    NvmeCacheLine lru_cache[NVME_CACHE_LINES];
} NvmeControllerRegistry;

