int stm32_dfsdm_get_buff_cb(struct iio_dev *iio_dev,
			    int (*cb)(const void *data, size_t size,
				      void *private),
			    void *private);
int stm32_dfsdm_release_buff_cb(struct iio_dev *iio_dev);

#endif
