cat << '__SECURECURTAIN_EOF__' > "${TARGET_DIR}/sys/kernel/include/linux/linux-6.10.10/include/linux/dma/qcom-gpi-dma.h"
/* SPDX-License-Identifier: GPL-2.0 */
/*
