	struct auxiliary_device aux_dev;
	struct pci_dev *vf_pdev;
	u16 client_id;
};

int pds_client_adminq_cmd(struct pds_auxiliary_dev *padev,
			  union pds_core_adminq_cmd *req,
			  size_t req_len,
			  union pds_core_adminq_comp *resp,
			  u64 flags);
#endif /* _PDSC_AUXBUS_H_ */
