#define MAX_FW_RULES   128
#define MAX_CONN_TRACK 1024
#define MAX_LOG_BUFFER 512

extern uint64_t native_get_system_time(void);

// Active security scanning arrays
static hips_rule_t hips_rules[MAX_HIPS_RULES];
static uint32_t    hips_rule_count = 0;

#define MAX_HIPS_ALERTS 128
static hips_alert_t hips_alerts[MAX_HIPS_ALERTS];
static uint32_t     hips_alert_head = 0;

// Stateful memory arrays
static fw_rule_t      firewall_rules[MAX_FW_RULES];
static uint32_t       rule_count = 0;

typedef struct {
    uint32_t src_ip;
    uint32_t dest_ip;
    uint16_t src_port;
    uint16_t dest_port;
    uint32_t state;
    uint64_t last_seen;
} conn_entry_t;

static conn_entry_t   state_table[MAX_CONN_TRACK];
static fw_log_entry_t log_ring_buffer[MAX_LOG_BUFFER];
static uint32_t       log_head = 0;

/**
 * Basic substring finder running inside user space (Subsystem version of strstr)
 */
static int hips_find_pattern(const uint8_t* payload, size_t payload_len, const char* pattern, size_t pattern_len) {
    if (pattern_len > payload_len || pattern_len == 0) return -1;
    for (size_t i = 0; i <= payload_len - pattern_len; i++) {
        if (memcmp(&payload[i], pattern, pattern_len) == 0) {
            return (int)i; // Found a malicious string match at this index offset
        }
    }
    return -1;
}

/**
 * Deep Packet Inspection (DPI) Hook. Processes incoming network payloads.
 * Returns false if an exploit signature matches a High severity block rule.
 */
bool hips_inspect_payload(uint32_t src_ip, const uint8_t* raw_payload, size_t payload_len) {
    if (payload_len == 0 || hips_rule_count == 0) return true;

    // Scan the packet payload against every single active signature rule
    for (uint32_t i = 0; i < hips_rule_count; i++) {
        int match_idx = hips_find_pattern(raw_payload, payload_len, hips_rules[i].pattern, hips_rules[i].pattern_len);
        
        if (match_idx != -1) {
            // Malicious Payload Detected! Log the security alert instantly.
            hips_alert_t* alert = &hips_alerts[hips_alert_head % MAX_HIPS_ALERTS];
            alert->timestamp    = native_get_system_time();
            alert->src_ip       = src_ip;
            alert->signature_id = hips_rules[i].signature_id;
            memcpy(alert->matched_payload, hips_rules[i].pattern, hips_rules[i].pattern_len);
            alert->matched_payload[hips_rules[i].pattern_len] = '␀';
            hips_alert_head++;

            // If severity is configured to High (3), forcefully DROP the packet
            if (hips_rules[i].severity == 3) {
                return false; 
            }
        }
    }
    return true; // Safe packet
}

/**
 * Log a packet event into the ring buffer for the Logging GUI to scrape
 */
void fw_log_packet(uint32_t sip, uint32_t dip, uint16_t sport, uint16_t dport, uint8_t proto, uint8_t action, uint8_t flags) {
    fw_log_entry_t* entry = &log_ring_buffer[log_head % MAX_LOG_BUFFER];
    entry->timestamp = native_get_system_time();
    entry->src_ip    = sip;
    entry->dest_ip   = dip;
    entry->src_port  = sport;
    entry->dest_port = dport;
    entry->protocol  = proto;
    entry->action    = action;
    entry->tcp_flags = flags; // Assign the raw TCP flags into the entry block
    log_head++;
}

/**
 * Fast-path packet sanitation filter. Evaluates illegal combinations of TCP flags.
 * Returns true if the flag layout is safe, returns false if it is a malicious scan.
 */
static bool fw_validate_tcp_flags(uint8_t flags) {
    
    // 1. SCAN DETECTION: NULL Scan Detection
    // An incoming packet with absolutely no flags set is an illegal state.
    if (flags == 0) {
        return false; 
    }

    // 2. SCAN DETECTION: Xmas Scan Detection
    // An incoming packet cannot have FIN, PSH, and URG all set simultaneously.
    if ((flags & (TCP_FLAG_FIN | TCP_FLAG_PSH | TCP_FLAG_URG)) == (TCP_FLAG_FIN | TCP_FLAG_PSH | TCP_FLAG_URG)) {
        return false;
    }

    // 3. SCAN DETECTION: SYN-FIN Scan Detection
    // A packet cannot be attempting to start a connection (SYN) and end it (FIN) at the same time.
    if ((flags & TCP_FLAG_SYN) && (flags & TCP_FLAG_FIN)) {
        return false;
    }

    // 4. SCAN DETECTION: SYN-RST Scan Detection
    // A packet cannot attempt to open a stream (SYN) and abruptly reset it (RST) simultaneously.
    if ((flags & TCP_FLAG_SYN) && (flags & TCP_FLAG_RST)) {
        return false;
    }

    // 5. STATE CONSTRAINTS: Safe Packet
    // The flag profile matches legal communication rules. Proceed to state tracking.
    return true;
}

/**
 * Upgraded Stateful Engine Hook matching raw TCP flag verification.
 */
bool fw_inspect_packet(uint32_t sip, uint32_t dip, uint16_t sport, uint16_t dport, uint8_t proto, uint8_t tcp_flags) {
    
    // 1. SEPARATION: If the protocol is TCP, execute the flag validation rule instantly
    if (proto == 6) { // 6 = TCP Protocol Identifier
        if (!fw_validate_tcp_flags(tcp_flags)) {
            // Instantly register the malicious drop event to your logging GUI buffer
            fw_log_packet(sip, dip, sport, dport, proto, FW_REASON_BAD_FLAGS, tcp_flags);
            return false; // Force DROP packet immediately before it touches the OS stack
        }
    }

    // Extract if it is a standard connection attempt for your state table
    bool is_tcp_syn = (proto == 6) && (tcp_flags == TCP_FLAG_SYN);

    // 1. STATEFUL EVALUATION: Check if this packet belongs to an ALREADY ESTABLISHED outbound connection
    for (uint32_t i = 0; i < MAX_CONN_TRACK; i++) {
        if (state_table[i].state == STATE_ESTABLISHED) {
            // Match the reverse flow (Incoming reply to an outgoing stream)
            if (state_table[i].src_ip == dip && state_table[i].dest_ip == sip &&
                state_table[i].src_port == dport && state_table[i].dest_port == sport) {
                return true; // Packet allowed immediately via State tracking
            }
        }
    }

    // 2. STATIC RULE EVALUATION: If it's a NEW connection request (TCP SYN), validate against rule lists
    for (uint32_t i = 0; i < rule_count; i++) {
        if (firewall_rules[i].protocol == proto &&
            (firewall_rules[i].dest_port == dport || firewall_rules[i].dest_port == 0)) { // 0 = Any
            
            if (firewall_rules[i].action == FW_ACTION_ALLOW) {
                // If allowed and it's a new outbound connection, create an entry in our State Table
                if (is_tcp_syn) {
                    for (uint32_t c = 0; c < MAX_CONN_TRACK; c++) {
                        if (state_table[c].state == 0) { // Free slot
                            state_table[c].src_ip   = sip;
                            state_table[c].dest_ip  = dip;
                            state_table[c].src_port = sport;
                            state_table[c].dest_port = dport;
                            state_table[c].state    = STATE_ESTABLISHED;
                            break;
                        }
                    }
                }
                return true;
            } else {
                fw_log_packet(sip, dip, sport, dport, proto, FW_ACTION_DROP, tcp_flags);
                return false; // Force block via rule
            }
        }
    }

    // Default Sandbox Security Policy: Drop and log everything else (Implicit Deny)
    fw_log_packet(sip, dip, sport, dport, proto, FW_ACTION_DROP, tcp_flags);
    return false;
}

/**
 * Handle incoming HIPS IPC messages inside network daemon main loop:
 * - HIPS_CMD_UPDATE_SIGNATURES: Bulk receive updated signature tables
 * - HIPS_CMD_GET_ALERTS: Send back active HIPS security alerts memory buffer
 */
void network_handle_hips_ipc(uint32_t cmd, const uint8_t* payload, size_t payload_len, uint32_t sender_pid) {
    if (cmd == HIPS_CMD_UPDATE_SIGNATURES) {
        uint32_t incoming_count = payload_len / sizeof(hips_rule_t);
        if (incoming_count <= MAX_HIPS_RULES) {
            memcpy(hips_rules, payload, payload_len);
            hips_rule_count = incoming_count;
        }
    } else if (cmd == HIPS_CMD_GET_ALERTS) {
        // Send back HIPS alert entries array
    }
}
