typedef struct {
    char     zone_name[32];
    int32_t  base_utc_offset_seconds;
    uint8_t  dst_rule_type; // 0=None, 1=US, 2=EU, 3=Southern Hemisphere (NZ/AU)
    uint32_t map_btn_x;
    uint32_t map_btn_y;
