void gfx_draw_filled_rect(uint32_t x, uint32_t y, uint32_t w, uint32_t h, uint32_t color) {
    uint32_t scaled_x = sys_scale_coordinate_value(x);
    uint32_t scaled_y = sys_scale_coordinate_value(y);
    uint32_t scaled_w = sys_scale_coordinate_value(w);
    uint32_t scaled_h = sys_scale_coordinate_value(h);

    uint32_t active_aperture = 600; 
    uint32_t my_pid = 100;

    for (uint32_t curr_y = 0; curr_y < scaled_h; curr_y++) {
        for (uint32_t curr_x = 0; curr_x < scaled_w; curr_x++) {
            sys_gop_blit_pixel_stream(active_aperture, my_pid, scaled_x + curr_x, scaled_y + curr_y, color);
        }
    }
}

void gfx_draw_string(uint32_t x, uint32_t y, const char* text, uint32_t color) {
    if (!text) return;
    uint32_t cursor_x = x;

    while (*text) {
        uint8_t ascii_idx = (uint8_t)*text;
        if (ascii_idx >= 128) ascii_idx = '?';
        
        // Loop sequentially over the 16 vertical pixel scanlines of the character bitmap
        for (uint32_t row = 0; row < 16; row++) {
            uint8_t bits = g_kfont_bitmap[ascii_idx][row];
            
            // Sweep horizontally bit-by-bit across the 8 columns of the character row
            for (uint32_t col = 0; col < 8; col++) {
                if (bits & (0x80 >> col)) {
                    uint32_t s_x = sys_scale_coordinate_value(cursor_x + col);
                    uint32_t s_y = sys_scale_coordinate_value(y + row);
                    sys_gop_blit_pixel_stream(600, 100, s_x, s_y, color);
                }
            }
        }
        cursor_x += 10; // Slide text column advance space
        text++;
    }
}

void render_hardware_rejection_error_window(void) {
    const HardwareValidationReport* r = sys_get_hardware_gate_report();

    gfx_draw_filled_rect(0, 0, 3840, 2160, 0x1E0A0A); 

    gfx_draw_string(100, 100, "=========================================================================", 0xFFFFFF);
    gfx_draw_string(100, 140, "  FATAL ERROR: BARE-METAL HARDWARE SPECIFICATION COMPLIANCE FAILURE       ", 0xFF3333);
    gfx_draw_string(100, 180, "=========================================================================", 0xFFFFFF);
    gfx_draw_string(100, 240, "This custom operating system requires strict baseline metrics to deploy.", 0xCCCCCC);
    gfx_draw_string(100, 280, "The installation has been securely halted to prevent data loss or crashes.", 0xCCCCCC);

    char ram_log[128];
    char cpu_lbl[128];
    char gpu_lbl[128];
    char disk_lbl[128];
    char display_lbl[128];

    ksnprintf(ram_log, sizeof(ram_log), " -> Physical Onboard RAM  : %llu MB / 16384 MB Min -> [%s]", r->detected_ram_mb, r->ram_passed ? "PASSED" : "FAILED");
    ksnprintf(cpu_lbl, sizeof(cpu_lbl), " -> CPU Generation Tier   : %s -> [%s]", r->detected_cpu_model, r->cpu_passed ? "PASSED" : "FAILED");
    ksnprintf(gpu_lbl, sizeof(gpu_lbl), " -> Graphics Accelerator  : %s -> [%s]", r->detected_gpu_desc, r->gpu_passed ? "PASSED" : "FAILED (Separate GPU Required)");
    ksnprintf(disk_lbl, sizeof(disk_lbl), " -> Encryption Drive Space : %u GB / 931 GB Min   -> [%s]", r->detected_disk_gb, r->disk_passed ? "PASSED" : "FAILED");
    ksnprintf(display_lbl, sizeof(display_lbl), " -> Display Output Link   : %ux%u / 720p Min    -> [%s]", r->detected_width, r->detected_height, r->display_passed ? "PASSED" : "FAILED");

    gfx_draw_string(120, 360, ram_log, r->ram_passed ? 0x3CD070 : 0xFF3333);
    gfx_draw_string(120, 410, cpu_lbl, r->cpu_passed ? 0x3CD070 : 0xFF3333);
    gfx_draw_string(120, 460, gpu_lbl, r->gpu_passed ? 0x3CD070 : 0xFF3333);
    gfx_draw_string(120, 510, disk_lbl, r->disk_passed ? 0x3CD070 : 0xFF3333);
    gfx_draw_string(120, 560, display_lbl, r->display_passed ? 0x3CD070 : 0xFF3333);

    gfx_draw_string(100, 600, "Please upgrade target components before attempting re-installation loops.", 0x8A9FB4);
}
__SECURECURTAIN_EOF__

cat << '__SECURECURTAIN_EOF__' > "${TARGET_DIR}/sys/subsystems/lockscreen/lockdown_policy.c"
#include "lock_screen.h"
#include "../../kernel/include/security_audit.h"
#include "../../kernel/include/pm_core.h"
#include "../../kernel/include/fw_injector.h"
#include <stdint.h>
#include <stdbool.h>
#include <string.h>

#define ALERT_THRESHOLD_COUNT 3
#define SLIDING_WINDOW_MS     10000 // 10-second evaluating window

static uint64_t g_alert_timestamps[ALERT_THRESHOLD_COUNT];
static uint32_t g_alert_history_ptr = 0;
static bool     g_lockdown_triggered = false;

extern uint64_t get_system_uptime_ms(void);
extern void lock_system_display(void);
extern void commit_security_audit_entry(uint32_t event_id, const char* user, const char* description);
extern bool g_is_system_locked; // Track lock screen state visibility

// Exposing an architecture helper that translates IP string representations into raw integers
extern uint32_t parse_ipv4_string_to_int(const char* ip_str);
extern const char* query_last_detected_attacker_ip(void);

// Evaluates threat vectors to enforce immediate hardware or display isolation
void evaluate_lockdown_policy(uint32_t event_id, uint32_t severity) {
    if (severity != 2) return;

    // ESCALATION RULE: If an exploit occurs while the terminal display is ALREADY locked down,
    // invoke the immediate hardware panic containment loops.
    if (g_is_system_locked) {
        if (event_id == EVENT_IPS_MALFORMED_HEADER || event_id == EVENT_AUTH_FAILURE) {
            execute_kernel_security_panic("Sustained Attack Matrix Post-Lockdown");
        }
    }

    if (g_lockdown_triggered) return;

    uint64_t current_time = get_system_uptime_ms();

    // 1. Append time marker directly into our rolling circular buffer
    g_alert_timestamps[g_alert_history_ptr] = current_time;
    g_alert_history_ptr = (g_alert_history_ptr + 1) % ALERT_THRESHOLD_COUNT;

    // 2. Audit the historical window parameters
    uint32_t violations_in_window = 0;
    for (uint32_t i = 0; i < ALERT_THRESHOLD_COUNT; i++) {
        if (g_alert_timestamps[i] != 0 && (current_time - g_alert_timestamps[i]) <= SLIDING_WINDOW_MS) {
            violations_in_window++;
        }
    }

    // 3. Breach Verified: Trigger immediate defensive isolation protocols
    if (violations_in_window >= ALERT_THRESHOLD_COUNT) {
        g_lockdown_triggered = true;

        // Fetch the offending IP address from the security tracker logs
        const char* attacker_ip_str = query_last_detected_attacker_ip();
        uint32_t numeric_ip = parse_ipv4_string_to_int(attacker_ip_str);

        // Inject a hard block rule into the firewall packet filters automatically
        inject_firewall_block_rule(numeric_ip);

        commit_security_audit_entry(EVENT_SECURITY_LOCKDOWN, "POLICY_DAEMON", "AUTOMATIC BLOCKOUT ENFORCED.");
        lock_system_display();
    }
}

// Reset lock tracking once an authorized admin clears the lockdown state
void reset_lockdown_policy_state(void) {
    g_lockdown_triggered = false;
    memset(g_alert_timestamps, 0, sizeof(g_alert_timestamps));
    g_alert_history_ptr = 0;
}
__SECURECURTAIN_EOF__

cat << '__SECURECURTAIN_EOF__' > "${TARGET_DIR}/sys/subsystems/lockscreen/pm_timer_thread.c"
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h> // For sleep/usleep system wrappers
#include "lock_screen.h"
#include "pm_core.h"
#include "../../kernel/include/ssd_mirror.h"

// External access to the operational variables initialized in your GUI stack
extern PowerConfig g_pm_settings;
extern uint64_t g_last_user_activity_tick;
extern bool g_is_system_locked;

extern uint64_t get_system_uptime_ms(void);
extern int32_t sys_power_management(uint32_t state);

static bool g_run_timer_loop = true;
static uint64_t g_last_mirror_sync_ms = 0;

// The main entry path running inside its own isolated Ring 3 thread context
void power_monitoring_thread_entry(void) {
    g_last_mirror_sync_ms = get_system_uptime_ms();
    while (g_run_timer_loop) {
        uint64_t current_time_ms = get_system_uptime_ms();

        if (current_time_ms - g_last_mirror_sync_ms >= SSD_SYNC_INTERVAL_MS) {
            trigger_two_hour_mirror_sync(); // Run deep corruption check and mirror data
            g_last_mirror_sync_ms = current_time_ms; // Reset synchronization interval window
        }
        
        // Calculate the accurate duration of absolute user inactivity in minutes
        uint32_t idle_seconds = (uint32_t)((current_time_ms - g_last_user_activity_tick) / 1000);
        uint32_t idle_minutes = idle_seconds / 60;

        // Condition 1: Enforce Automatic Display Isolation Lock
        if (!g_is_system_locked && idle_minutes >= g_pm_settings.minutes_to_lock) {
            lock_system_display();
        }

        // Condition 2: Step sequentially through chronological low-power degradations
        if (idle_minutes >= g_pm_settings.minutes_to_poweroff) {
            sys_power_management(POWER_STATE_OFF);
        } 
        else if (idle_minutes >= g_pm_settings.minutes_to_hibernate) {
            sys_power_management(POWER_STATE_HIBERNATE);
        } 
        else if (idle_minutes >= g_pm_settings.minutes_to_hybrid) {
            sys_power_management(POWER_STATE_HYBRID);
        } 
        else if (idle_minutes >= g_pm_settings.minutes_to_sleep) {
            sys_power_management(POWER_STATE_SLEEP);
        }

        // Suspend execution block for 1 second (1000ms) to conserve CPU cycles
        // Maps down to your microkernel's native sleep/yield system calls
        sleep(1); 
    }
}

// Orderly shutdown mechanism for the tracking loop if the subsystem resets
void terminate_power_monitoring_thread(void) {
    g_run_timer_loop = false;
}
__SECURECURTAIN_EOF__

cat << '__SECURECURTAIN_EOF__' > "${TARGET_DIR}/sys/subsystems/lockscreen/rescue_egg.c"
#include "../../kernel/include/user_space.h"
#include "../../kernel/include/security_audit.h"
#include "rescue_egg.h"
#include <stdio.h>
#include <string.h>

#define EGG_X1 10
#define EGG_Y1 740 // Positioned inconspicuously near the lower baseline boundary frame mapping
#define EGG_W  24
#define EGG_H  24

bool g_rescue_terminal_active = false;
static char g_rescue_input_stream[128] = {0};
static uint32_t g_rescue_input_len = 0;

extern void gfx_draw_filled_rect(uint32_t x, uint32_t y, uint32_t w, uint32_t h, uint32_t color);
extern void gfx_draw_string(uint32_t x, uint32_t y, const char* text, uint32_t color);
extern void request_ui_composition_refresh(void);

// Verification routine to confirm the Easter Egg coordinate collision boundary boxes
bool evaluate_rescue_egg_cursor_override(uint32_t mx, uint32_t my, uint32_t* forced_cursor_type) {
    if (mx >= EGG_X1 && mx <= EGG_X1 + EGG_W && my >= EGG_Y1 && my <= EGG_Y1 + EGG_H) {
        *forced_cursor_type = 0; // HARD OVERRIDE: Enforce flat standard arrow shape, completely blocking pointer swaps
        return true; 
    }
    return false;
}

void render_rescue_egg_graphic_element(void) {
    // Draw an innocuous micro geometric wireframe grid pattern that looks purely ornamental
    gfx_draw_filled_rect(EGG_X1,      EGG_Y1,      EGG_W, 2, 0x333540); // Subtle gray accent baseline design
    gfx_draw_filled_rect(EGG_X1 + 4,  EGG_Y1 + 6,  2, 2, 0x22242D);
    gfx_draw_filled_rect(EGG_X1 + 12, EGG_Y1 + 12, 2, 2, 0x22242D);

    if (g_rescue_terminal_active) {
        // Render raw zero-trace terminal panel frame directly onto lower layout segments
        uint32_t tx = 40, ty = 500;
        gfx_draw_filled_rect(tx, ty, 560, 220, 0x050508);
        gfx_draw_filled_rect(tx, ty, 560, 4, 0xFFA726); // Alert highlighting line
        
        gfx_draw_string(tx + 16, ty + 16, "=== CRITICAL ARCHITECTURAL RECOVERY SHELL ENTRY VIA INTERCEPT ===", 0xFFA726);
        gfx_draw_string(tx + 16, ty + 46, "ACCOUNT LOCKOUT BYPASS DETECTED. PROVIDE SEQUENTIAL VERIFICATION BLOCK:", 0xBBBBBB);
        
        // Typing parameter window entry container fields
        gfx_draw_string(tx + 16, ty + 84, "Challenge String Packet Seq -> ", 0x8A8D9A);
        
        // Obfuscate character feedback metrics via masking blocks to keep inputs fully hidden
        char masked_dots[128] = {0};
        for (uint32_t i = 0; i < g_rescue_input_len; i++) masked_dots[i] = '#';
        gfx_draw_string(tx + 260, ty + 84, masked_dots, 0x00FF00);
        
        gfx_draw_string(tx + 16, ty + 124, "Input Layout Format Rule: [OldPassword][CaseSensitiveAlphanumericPIN]x3", 0x555A64);
        gfx_draw_string(tx + 16, ty + 154, "Provide token challenge loop packet stream and hit [ENTER] key.", 0x555A64);
    }
}

void process_rescue_egg_double_click(uint32_t mx, uint32_t my) {
    if (mx >= EGG_X1 && mx <= EGG_X1 + EGG_W && my >= EGG_Y1 && my <= EGG_Y1 + EGG_H) {
        g_rescue_terminal_active = true;
        memset(g_rescue_input_stream, 0, sizeof(g_rescue_input_stream));
        g_rescue_input_len = 0;
        printf("[Rescue Intercept]: Triggered raw zero-trace emergency terminal console.\\n");
        request_ui_composition_refresh();
    }
}

void process_rescue_terminal_keyboard_input(uint32_t key_code) {
    if (!g_rescue_terminal_active) return;

    if (key_code == 0x0D) { // ENTER key pressed -> Validate Challenge sequence parameters
        // Verification verification sequence structure template mapping check:
        // Expected structure validation formula: "password123" + "aB3xPin" + "aB3xPin" + "aB3xPin"
        const char* expected_recovery_token = "password123aB3xPinaB3xPinaB3xPin";

        if (strcmp(g_rescue_input_stream, expected_recovery_token) == 0) {
            printf("[Rescue Engine]: EMERGENCY RECOVERY VALIDATION SEQUENCE PASSED 3/3 TIMES SUCCESSFULLY.\\n");
            
            // Re-open and revive the locked SuperAdmin account profile nodes inside kernel space variables
            extern MultiTenantControlRegistry g_user_manager;
            for (uint32_t i = 0; i < g_user_manager.registered_users_count; i++) {
                if (g_user_manager.user_registry[i].privilege_tier == 3) {
                    g_user_manager.user_registry[i].is_locked_out = false; // RESET ACCOUNT LOCKOUT SWITCH
                    g_user_manager.user_registry[i].consecutive_violations_count = 0;
                    
                    // Provision fresh replacement credential markers baseline records safely
                    strcpy(g_user_manager.user_registry[i].username, "Administrator");
                    break;
                }
            }
            
            commit_security_audit_entry(EVENT_SECURITY_LOCKDOWN, "RESCUE_EGG", "EMERGENCY CLEARANCE OVERRIDE CHALLENGE PASSED. Admin account successfully re-activated.");
            
            // Cleanly minimize and exit the shell interface like it was never there
            g_rescue_terminal_active = false;
            memset(g_rescue_input_stream, 0, sizeof(g_rescue_input_stream));
            g_rescue_input_len = 0;
            
            // Pop open an overlay modal dialogue text field to complete password reconfiguration updates
            extern void show_ui_alert(const char* message);
            show_ui_alert("Recovery Complete. Admin account restored. Update login password fields immediately.");
        } else {
            // Sequence entry discrepancy mismatch detected: increment alarm triggers
            commit_security_audit_entry(EVENT_AUTH_FAILURE, "RESCUE_EGG", "CRITICAL WARNING: Malicious or incorrect emergency override challenge submission.");
            g_rescue_terminal_active = false; // Discard workspace layout on infraction
            memset(g_rescue_input_stream, 0, sizeof(g_rescue_input_stream));
            g_rescue_input_len = 0;
        }
        request_ui_composition_refresh();
    }
    else if (key_code == 0x08) { // Backspace key processing
        if (g_rescue_input_len > 0) {
            g_rescue_input_stream[--g_rescue_input_len] = '\\0';
            request_ui_composition_refresh();
        }
    }
    else if (g_rescue_input_len < 127) {
        g_rescue_input_stream[g_rescue_input_len++] = (char)key_code;
        request_ui_composition_refresh();
    }
}
