cat << '__SECURECURTAIN_EOF__' > "${TARGET_DIR}/sys/subsystems/chat/secure_chat_gui.c"
#include "secure_chat.h"
#include <string.h>
#include <stdio.h>

extern void gfx_draw_filled_rect(uint32_t x, uint32_t y, uint32_t w, uint32_t h, uint32_t color);
extern void gfx_draw_string(uint32_t x, uint32_t y, const char* text, uint32_t color);
extern void encapsulate_and_encrypt_tunnel_stream(const uint8_t* plaintext_ip_packet, uint32_t length);
extern uint64_t get_system_uptime_ms(void);
extern void request_ui_composition_refresh(void);

static char g_chat_input_box[CHAT_BUFFER_MAX_LEN] = {0};
static uint32_t g_chat_input_len = 0;

// Local message caching queues to display conversations
static SecureChatMessage g_chat_history[8];
static uint32_t        g_chat_history_count = 0;

void init_secure_chat_app(void) {
    memset(g_chat_input_box, 0, CHAT_BUFFER_MAX_LEN);
    g_chat_input_len = 0;
    g_chat_history_count = 0;
}

void render_chat_window_frame(void) {
    uint32_t cx = 400, cy = 120;
    uint32_t cw = 360, ch = 300;

    // 1. Draw central workspace card container window
    gfx_draw_filled_rect(cx, cy, cw, ch, 0x1A1D24);
    gfx_draw_filled_rect(cx, cy, cw, 28, 0x2A303D); // Header block
    gfx_draw_string(cx + 12, cy + 8, "VPN Shielded Encrypted Chat Core", 0xFFFFFF);

    // 2. Render Historical Chat Log Output Strings
    for (uint32_t i = 0; i < g_chat_history_count; i++) {
        uint32_t line_y = cy + 40 + (i * 24);
        uint32_t color = (g_chat_history[i].sender_id == 0x1) ? 0x4A90E2 : 0x3CD070; // Blue (Self) vs Green (Peer)
        
        char formatted_line[160];
        snprintf(formatted_line, sizeof(formatted_line), "<Node-%d>: %s", g_chat_history[i].sender_id, g_chat_history[i].message_text);
        gfx_draw_string(cx + 12, line_y, formatted_line, color);
    }

    // 3. Render Interactive Text Entry Field Input Box
    uint32_t input_box_y = cy + ch - 40;
    gfx_draw_filled_rect(cx + 12, input_box_y, cw - 24, 24, 0x111318);
    
    if (g_chat_input_len == 0) {
        gfx_draw_string(cx + 20, input_box_y + 6, "Type private message and hit [ENTER]...", 0x555A64);
    } else {
        gfx_draw_string(cx + 20, input_box_y + 6, g_chat_input_box, 0xFFFFFF);
    }
}

void process_chat_keyboard_input(uint32_t key_code) {
    if (key_code == 0x0D) { // Enter key pressed -> Dispatch over secure channel
        if (g_chat_input_len == 0) return;

        SecureChatMessage outbound_msg;
        outbound_msg.sender_id = 0x1; // Local Node Designation ID
        outbound_msg.timestamp_ms = get_system_uptime_ms();
        strncpy(outbound_msg.message_text, g_chat_input_box, CHAT_BUFFER_MAX_LEN - 1);

        // Append locally to chat history list view cache
        if (g_chat_history_count < 8) {
            memcpy(&g_chat_history[g_chat_history_count++], &outbound_msg, sizeof(SecureChatMessage));
        }

        // Direct serialization: Stream raw plaintext message payload straight into the Ring 0 VPN tunnel
        encapsulate_and_encrypt_tunnel_stream((const uint8_t*)&outbound_msg, sizeof(SecureChatMessage));

        // Flush entry fields
        memset(g_chat_input_box, 0, CHAT_BUFFER_MAX_LEN);
        g_chat_input_len = 0;
        request_ui_composition_refresh();
    } 
    else if (key_code == 0x08) { // Backspace handling
        if (g_chat_input_len > 0) {
            g_chat_input_box[--g_chat_input_len] = '\\0';
            request_ui_composition_refresh();
        }
    } 
    else if (g_chat_input_len < (CHAT_BUFFER_MAX_LEN - 1)) {
        g_chat_input_box[g_chat_input_len++] = (char)key_code;
        request_ui_composition_refresh();
    }
}

void receive_inbound_tunnel_chat_msg(const SecureChatMessage* incoming_msg) {
    // Intercepts decapsulated data streams peeled out of the VPN loopback adapters
    if (g_chat_history_count >= 8) {
        // Shift cache buffer contents to scroll out old messages
        for(uint32_t s = 1; s < 8; s++) g_chat_history[s-1] = g_chat_history[s];
        g_chat_history_count = 7;
    }
    memcpy(&g_chat_history[g_chat_history_count++], incoming_msg, sizeof(SecureChatMessage));
    request_ui_composition_refresh();
}
__SECURECURTAIN_EOF__

cat << '__SECURECURTAIN_EOF__' > "${TARGET_DIR}/sys/subsystems/vfs/ntfs_directory.c"
#include <stddef.h>
#include <stdbool.h>
#include <string.h>
#include "ntfs_structures.h"
#include "../win32/win32_string.h" // Holds your convert_utf16_to_utf8 string utility

/**
 * Traverses an $INDEX_ROOT attribute block to resolve a target filename to its MFT record index.
 * 
 * @param index_root_attr  Pointer to the start of the resident $INDEX_ROOT attribute.
 * @param target_name      The standard null-terminated UTF-8 name string you are looking for.
 * @return                 The 64-bit target MFT Record Index identifier, or 0 if not found.
 */
uint64_t ntfs_resolve_directory_entry(const uint8_t* index_root_attr, const char* target_name) {
    if (!index_root_attr || !target_name) return 0;

    const ntfs_attr_header_t* attr = (const ntfs_attr_header_t*)index_root_attr;
    if (attr->type != NTFS_ATTR_INDEX_ROOT || attr->non_resident != 0) {
        return 0; // Guard clause: Must be a resident Index Root structural layout
    }

    // Advance past the standard Resident Attribute header to reach the internal values
    uintptr_t value_start = (uintptr_t)index_root_attr + ((const ntfs_attr_resident_t*)attr)->value_offset;
    
    // Jump past the root header block to land on the sub-index header block
    const ntfs_index_header_t* index_hdr = (const ntfs_index_header_t*)(value_start + sizeof(ntfs_index_root_header_t));
    
    // Locate the first index entry item using the offset parameter
    uintptr_t current_entry_ptr = (uintptr_t)index_hdr + index_hdr->entries_offset;
    size_t scanned_bytes = index_hdr->entries_offset;

    // Iterate through the index entry array
    while (scanned_bytes < index_hdr->index_length) {
        const ntfs_index_entry_t* entry = (const ntfs_index_entry_t*)current_entry_ptr;

        // Break if we reach the end of the entry table descriptor block
        if (entry->entry_length == 0 || (entry->flags & 0x02)) {
            break; 
        }

        // Parse filename string metadata if the block contains valid data streams
        if (entry->stream_length > 0 && entry->name_length > 0) {
            char current_utf8_filename[256];
            
            // Translate the NTFS target directory UTF-16 wide string entry into native UTF-8
            convert_utf16_to_utf8(entry->file_name, current_utf8_filename, entry->name_length);

            // Compare entry name against our desired VFS path string asset target
            if (strcmp(current_utf8_filename, target_name) == 0) {
                return entry->indexed_file_mft; // Success: Found matching MFT path node reference!
            }
        }

        // If the B-Tree entry points to a sub-node child cluster and target isn't here,
        // a production driver would extract the child cluster VCN value from the trailing bytes
        // of this entry block and recursively search the $INDEX_ALLOCATION cluster list.

        // Advance loop pointers forward to the next index segment
        scanned_bytes     += entry->entry_length;
        current_entry_ptr += entry->entry_length;
    }

    return 0; // The requested filename asset does not exist inside this directory root node
}
__SECURECURTAIN_EOF__

cat << '__SECURECURTAIN_EOF__' > "${TARGET_DIR}/sys/subsystems/vfs/ntfs_overflow.c"
#include <stddef.h>
#include <stdbool.h>
#include <string.h>
#include "ntfs_structures.h"
#include "../win32/win32_string.h" // Holds your convert_utf16_to_utf8 string utility

/**
 * Parses an external 4096-byte Index Allocation Buffer block to locate a filename.
 * 
 * @param buffer          Pointer to the 4096-byte raw buffer read from the disk partition.
 * @param target_name     The standard null-terminated UTF-8 filename target string.
 * @param out_next_vcn    Output variable populated with the next child cluster VCN if a B-Tree traversal is required.
 * @param is_child_node   Output flag set to true if the search hit a sub-node branching vector.
 * @return                The 64-bit target MFT Record Index identifier, or 0 if not found/needs traversal.
 */
uint64_t ntfs_parse_index_allocation_block(const uint8_t* buffer, const char* target_name, uint64_t* out_next_vcn, bool* is_child_node) {
    if (!buffer || !target_name || !out_next_vcn || !is_child_node) return 0;

    *is_child_node = false;

    // 1. Verify structural layout validity via Magic Check
    const ntfs_index_buffer_t* idx_block = (const ntfs_index_buffer_t*)buffer;
    if (idx_block->magic != 0x58444E49) { // Compares against "INDX" ASCII encoding
        return 0; // Invalid or corrupt index allocation cluster payload
    }

    // 2. Identify the absolute baseline pointer to the first index entry structure
    // We add the offset parameters directly relative to the inner structural header block position
    uintptr_t current_entry_ptr = (uintptr_t)&idx_block->header + idx_block->header.entries_offset;
    size_t scanned_bytes = idx_block->header.entries_offset;

    // 3. Scan entries sequentially up to the length boundary declared by the index block header
    while (scanned_bytes < idx_block->header.index_length) {
        const ntfs_index_entry_t* entry = (const ntfs_index_entry_t*)current_entry_ptr;

        // Check if we hit the terminating structural padding entry token of the array list
        if (entry->entry_length == 0 || (entry->flags & 0x02)) {
            // 4. B-TREE ENTRY EVALUATION: Does this terminal boundary point to an internal sub-node branch?
            if (entry->flags & 0x01) {
                // The 64-bit Virtual Cluster Number (VCN) of the child node is stored at the absolute end of the entry block
                *out_next_vcn = *(uint64_t*)((uintptr_t)entry + entry->entry_length - 8);
                *is_child_node = true;
            }
            break;
        }

        // 5. NAME MATCH ROUTINE: Dissect entry strings if metadata streams are populated
        if (entry->stream_length > 0 && entry->name_length > 0) {
            char current_utf8_filename[256];
            
            // Translate the NTFS target multi-byte UTF-16 wide string entry into native UTF-8
            convert_utf16_to_utf8(entry->file_name, current_utf8_filename, entry->name_length);

            // Compare entry name against our desired path target string asset
            int cmp_result = strcmp(target_name, current_utf8_filename);
            if (cmp_result == 0) {
                return entry->indexed_file_mft; // Success: Found matching MFT path node reference!
            }
            
            // Optimization Check: Since the entries are sorted alphabetically inside the B-Tree,
            // if our target string sorts *before* the current entry name string, we know our asset
            // cannot exist further down this array line. It must reside in a lower sub-node branch.
            if (cmp_result < 0 && (entry->flags & 0x01)) {
                *out_next_vcn = *(uint64_t*)((uintptr_t)entry + entry->entry_length - 8);
                *is_child_node = true;
                break;
            }
        }

        // Advance loop pointers forward to the next index segment boundary position
        scanned_bytes     += entry->entry_length;
        current_entry_ptr += entry->entry_length;
    }

    return 0; // Not found on this block page layer
}
__SECURECURTAIN_EOF__

cat << '__SECURECURTAIN_EOF__' > "${TARGET_DIR}/sys/subsystems/vfs/ntfs_parser.c"
#include <stdint.h>
#include <stdbool.h>
#include <stddef.h>
#include <string.h>
#include "ntfs_structures.h"

/**
 * Decodes compressed NTFS Data Runs into sequential absolute disk clusters.
 * 
 * @param run_stream       Pointer to the start of the byte array encoding the data runs.
 * @param stream_limit     Max boundary checkpoint to prevent memory runaway.
 * @param out_start_lcn    Output table to store decoded absolute starting clusters.
 * @param out_run_length   Output table to store decoded run lengths.
 * @return                 The total count of fragmented data segments parsed.
 */
size_t ntfs_decode_data_runs(const uint8_t* run_stream, size_t stream_limit, uint64_t* out_start_lcn, uint64_t* out_run_length) {
    size_t stream_idx = 0;
    size_t segment_count = 0;
    int64_t current_lcn = 0; // Accumulates relative cluster offsets over time

    while (stream_idx < stream_limit) {
        uint8_t header = run_stream[stream_idx++];
        
        // A header byte of 0x00 marks the end of the Data Run list
        if (header == 0x00) {
            break;
        }

        uint8_t length_bytes = header & 0x0F;        // Low 4 bits
        uint8_t offset_bytes = (header >> 4) & 0x0F; // High 4 bits

        // Safety verification bounds check
        if (stream_idx + length_bytes + offset_bytes > stream_limit) {
            break;
        }

        // 1. Extract the variable-length Cluster Length variable
        uint64_t run_length = 0;
        for (int i = 0; i < length_bytes; i++) {
            run_length |= ((uint64_t)run_stream[stream_idx++]) << (i * 8);
        }

        // 2. Extract the variable-length signed Cluster Offset (LCN)
        int64_t relative_lcn_offset = 0;
        for (int i = 0; i < offset_bytes; i++) {
            relative_lcn_offset |= ((int64_t)run_stream[stream_idx++]) << (i * 8);
        }

        // Sign-extend the relative LCN if the highest bit of the extracted offset is negative
        if (offset_bytes > 0 && (relative_lcn_offset & (1ULL << ((offset_bytes * 8) - 1)))) {
            for (int i = offset_bytes; i < 8; i++) {
                relative_lcn_offset |= (0xFFULL << (i * 8));
            }
        }

        // 3. Accumulate absolute tracking vector (Offsets are relative to the previous run)
        current_lcn += relative_lcn_offset;

        // 4. Save the calculated segment details into the VFS lookup table
        out_start_lcn[segment_count]  = (uint64_t)current_lcn;
        out_run_length[segment_count] = run_length;
        segment_count++;
    }

    return segment_count;
}

/**
 * Upgraded MFT Record Dissector. Seamlessly handles both Resident and Non-Resident $DATA.
 */
size_t ntfs_read_file_data(const uint8_t* mft_buffer, uint64_t* out_clusters, uint64_t* out_lengths, bool* is_non_resident) {
    const ntfs_mft_record_header_t* record = (const ntfs_mft_record_header_t*)mft_buffer;
    if (record->magic != 0x454C4946) return 0;

    uintptr_t current_attr_offset = (uintptr_t)mft_buffer + record->attrs_offset;
    size_t processed_bytes = record->attrs_offset;

    while (processed_bytes < record->bytes_in_use) {
        const ntfs_attr_header_t* attr = (const ntfs_attr_header_t*)current_attr_offset;
        if (attr->type == NTFS_ATTR_TERMINATOR || attr->length == 0) break;

        if (attr->type == NTFS_ATTR_DATA) {
            if (attr->non_resident == 0) {
                // Handle Resident Data (Small files mapped inside previous step)
                *is_non_resident = false;
                return attr->length;
            } 
            else {
                // Handle Non-Resident Data (Large Files split across clusters)
                *is_non_resident = true;
                const ntfs_attr_non_resident_t* non_res_attr = (const ntfs_attr_non_resident_t*)attr;
                
                // Point directly to where the encoded Data Run byte stream begins
                const uint8_t* run_stream_start = (const uint8_t*)((uintptr_t)non_res_attr + non_res_attr->run_offset);
                size_t stream_limit_size = non_res_attr->header.length - non_res_attr->run_offset;

                // Fire the data run decompressor engine
                return ntfs_decode_data_runs(run_stream_start, stream_limit_size, out_clusters, out_lengths);
            }
        }
        processed_bytes     += attr->length;
        current_attr_offset += attr->length;
    }
    return 0;
}

/**
 * Parses a single 1024-byte raw MFT record buffer to extract resident file data.
 */
size_t ntfs_parse_mft_resident_data(const uint8_t* mft_buffer, uint8_t* out_data, size_t max_size) {
    if (!mft_buffer || !out_data) return 0;

    const ntfs_mft_record_header_t* record = (const ntfs_mft_record_header_t*)mft_buffer;
    if (record->magic != 0x454C4946) {
        return 0;
    }

    uintptr_t current_attr_offset = (uintptr_t)mft_buffer + record->attrs_offset;
    size_t processed_bytes = record->attrs_offset;

    while (processed_bytes < record->bytes_in_use) {
        const ntfs_attr_header_t* attr = (const ntfs_attr_header_t*)current_attr_offset;

        if (attr->type == NTFS_ATTR_TERMINATOR || attr->length == 0) {
            break;
        }

        if (attr->type == NTFS_ATTR_DATA) {
            if (attr->non_resident == 0) {
                const ntfs_attr_resident_t* resident_attr = (const ntfs_attr_resident_t*)attr;
                const uint8_t* raw_payload_ptr = (const uint8_t*)((uintptr_t)resident_attr + resident_attr->value_offset);
                
                size_t bytes_to_copy = resident_attr->value_length;
                if (bytes_to_copy > max_size) {
                    bytes_to_copy = max_size;
                }

                memcpy(out_data, raw_payload_ptr, bytes_to_copy);
                return bytes_to_copy;
            } 
            else {
                return 0; 
            }
        }

        processed_bytes      += attr->length;
        current_attr_offset += attr->length;
    }

    return 0;
}

__SECURECURTAIN_EOF__

cat << '__SECURECURTAIN_EOF__' > "${TARGET_DIR}/sys/subsystems/vfs/ntfs_structures.h"
#pragma once
#include <stdint.h>

// MFT Attribute Identifiers
#define NTFS_ATTR_STANDARD_INFO 0x10
#define NTFS_ATTR_FILE_NAME     0x30
#define NTFS_ATTR_DATA          0x80
#define NTFS_ATTR_TERMINATOR    0xFFFFFFFF

// The 1024-byte primary MFT Record Header block definition
typedef struct {
    uint32_t magic;                  // Layout must equal "FILE" (0x454C4946)
    uint16_t usa_offset;             // Update Sequence Array layout offset
    uint16_t usa_count;              // Size of Update Sequence Array
    uint64_t lsn;                    // Log File Sequence Number
    uint16_t sequence_number;        // Record generation counter index
    uint16_t hard_link_count;        // Directory link tracking tally
    uint16_t attrs_offset;           // Absolute byte offset to the first attribute
    uint16_t flags;                  // 0x01 = Record In Use, 0x02 = Directory
    uint32_t bytes_in_use;           // True byte length used by the structure
    uint32_t bytes_allocated;         // Always 1024 bytes per standard MFT block
    uint64_t base_mft_record;        // Reference handle linkage if split
    uint16_t next_attr_id;           // Identifier for next allocation tag
} __attribute__((packed)) ntfs_mft_record_header_t;

// Unified Header prefixed onto every sub-attribute block inside an MFT record
typedef struct {
    uint32_t type;                   // e.g., NTFS_ATTR_DATA (0x80)
    uint32_t length;                 // Total byte length of this attribute block
    uint8_t  non_resident;           // 0 = Resident (In MFT), 1 = Non-Resident (On Disk)
    uint8_t  name_length;            // Length of optional attribute name string
    uint16_t name_offset;            // Offset byte array marker to the name string
    uint16_t flags;                  // Compression or Encryption tokens
    uint16_t attribute_id;           // Tracking index signature
} __attribute__((packed)) ntfs_attr_header_t;

// Layout details if the data is small enough to stay inside the 1024-byte MFT record
typedef struct {
    ntfs_attr_header_t header;
    uint32_t value_length;           // Exact size of raw data payload content
    uint16_t value_offset;           // Absolute byte offset marker to the payload data
    uint8_t  resident_flags;         // Indexed buffer markers
    uint8_t  reserved;
} __attribute__((packed)) ntfs_attr_resident_t;

// Layout details used when file data is pushed out onto external disk clusters
typedef struct {
    ntfs_attr_header_t header;
    uint64_t starting_vcn;           // Starting Virtual Cluster Number (VCN)
    uint64_t ending_vcn;             // Ending VCN for this attribute stream
    uint16_t run_offset;             // Byte offset from attr head to the Data Runs
    uint16_t compression_unit_size;  // 0 means uncompressed
    uint32_t padding;
    uint64_t allocated_size;         // Total allocated size on disk
    uint64_t data_size;              // True file byte size 
    uint64_t initialized_size;       // Initialized stream data length
} __attribute__((packed)) ntfs_attr_non_resident_t;

#define NTFS_ATTR_INDEX_ROOT       0x90
#define NTFS_ATTR_INDEX_ALLOCATION 0xA0

// Primary layout block inside an $INDEX_ROOT attribute
typedef struct {
    uint32_t attribute_type;      // Always 0x30 ($FILE_NAME) for directories
    uint32_t collation_rule;       // Sorting behavior (usually case-insensitive)
    uint32_t index_block_size;     // Size of allocated index blocks (usually 4096 bytes)
    uint8_t  clusters_per_block;   // Size in clusters
    uint8_t  padding[3];
} __attribute__((packed)) ntfs_index_root_header_t;

// Standard Header for an Index Header block (found in both Root and Allocation records)
typedef struct {
    uint32_t entries_offset;       // Byte offset from this header to the first index entry
    uint32_t index_length;         // Total size of entries in bytes
    uint32_t allocated_size;       // Allocated tracking envelope size
    uint8_t  flags;                // 0x01 = Has sub-nodes (Large directory B-Tree)
    uint8_t  padding[3];
} __attribute__((packed)) ntfs_index_header_t;

// The actual entry containing individual filename metadata
typedef struct {
    uint64_t indexed_file_mft;     // The MFT record index mapping to this file/folder
    uint16_t entry_length;         // Size of this individual index entry block
    uint16_t stream_length;        // Size of the internal filename attribute
    uint16_t flags;                // 0x01 = Points to a sub-node child cluster
    uint16_t padding;
    // --- Stream Content (Only present if entry_length > 16) ---
    uint64_t parent_mft_record;    // Parent folder MFT reference
    uint64_t creation_time;
    uint64_t altered_time;
    uint64_t mft_changed_time;
    uint64_t read_time;
    uint64_t allocated_size;
    uint64_t real_size;
    uint32_t file_flags;
    uint8_t  name_length;          // Character length of the filename
    uint8_t  name_type;            // POSIX, Win32, or DOS namespace
    uint16_t file_name[1];         // UTF-16 variable-length filename string buffer
} __attribute__((packed)) ntfs_index_entry_t;

// The 4096-byte external Index Buffer primary block definition
typedef struct {
    uint32_t magic;               // Layout must equal "INDX" (0x58444E49)
    uint16_t usa_offset;          // Update Sequence Array layout offset
    uint16_t usa_count;           // Size of Update Sequence Array
    uint64_t lsn;                 // Log File Sequence Number
    uint64_t index_vcn;           // Virtual Cluster Number (VCN) of this block inside the allocation stream
    ntfs_index_header_t header;   // Standard index header (exposes entries_offset and index_length)
} __attribute__((packed)) ntfs_index_buffer_t;
