cat << '__SECURECURTAIN_EOF__' > "${TARGET_DIR}/sys/userland/windows/init.c"
/* SecureCurtain OS - Native Windows Persona Ring 3 Init Payload
 * Author: Jared Busby (jb7572)
 * Architecture: x86_64 Microsoft x64 Calling Convention & NT Syscall ABI
 */

#include <stdint.h>
#include <stddef.h>

// Windows NT Status Codes
#define STATUS_SUCCESS                   0x00000000L

// Windows NT System Call Numbers (x64)
#define NT_READ_FILE                     0x0003
#define NT_WRITE_FILE                    0x0008
#define NT_CLOSE                         0x000F
#define NT_ALLOCATE_VIRTUAL_MEMORY       0x0018
#define NT_FREE_VIRTUAL_MEMORY           0x001E
#define NT_MAP_VIEW_OF_SECTION           0x0028
#define NT_TERMINATE_PROCESS             0x002C
#define NT_DELAY_EXECUTION               0x0034
#define NT_QUERY_SYSTEM_INFORMATION      0x0036
#define NT_CREATE_FILE                   0x0055

/* Windows x64 NT Syscall Dispatcher:
 * In Windows NT x64:
 *   - RCX is copied to R10 (because syscall clobbers RCX)
 *   - EAX holds the NT Service System Call Index
 *   - RDX, R8, R9 hold args 2, 3, 4
 *   - 32-byte shadow stack space allocated by caller
 */
static inline int64_t nt_syscall4(uint32_t ssn, uint64_t a1, uint64_t a2, uint64_t a3, uint64_t a4) {
    int64_t status;
    __asm__ volatile (
        "movq %1, %%r10\n\t"     // arg1 -> r10
        "movq %2, %%rax\n\t"     // ssn -> rax
        "syscall\n\t"
        : "=a"(status)
        : "r"(a1), "r"((uint64_t)ssn), "d"(a2), "r"(a3), "r"(a4)
        : "rcx", "r10", "r11", "memory"
    );
    return status;
}

static inline void nt_terminate(uint64_t exit_status) {
    __asm__ volatile (
        "movq %0, %%r10\n\t"
        "movq %1, %%rax\n\t"
        "syscall\n\t"
        :
        : "r"(exit_status), "r"((uint64_t)NT_TERMINATE_PROCESS)
        : "rcx", "r10", "r11", "memory"
    );
    while (1);
}

static size_t win_strlen(const char *str) {
    size_t len = 0;
    while (str[len]) len++;
    return len;
}

static void win_write_console(const char *msg) {
    nt_syscall4(NT_WRITE_FILE, 1, (uint64_t)msg, win_strlen(msg), 0);
}

void mainCRTStartup(void) {
    win_write_console("[USERLAND:WIN32] Hello from Windows Persona User Mode (Ring 3)!\n");
    win_write_console("[USERLAND:WIN32] Subsystem: Win32 CUI / NT Executive\n");
    win_write_console("[USERLAND:WIN32] Testing NtAllocateVirtualMemory heap request...\n");

    // Request virtual memory heap block
    nt_syscall4(NT_ALLOCATE_VIRTUAL_MEMORY, (uint64_t)-1, 0x0000000050000000ULL, 0x10000, 0x3000);

    win_write_console("[USERLAND:WIN32] Native NT Service NtWriteFile verified.\n");
    win_write_console("[USERLAND:WIN32] Calling NtTerminateProcess (STATUS_SUCCESS)...\n");

    nt_terminate(STATUS_SUCCESS);
}
__SECURECURTAIN_EOF__

cat << '__SECURECURTAIN_EOF__' > "${TARGET_DIR}/sys/userland/linux/init.c"
/* SecureCurtain OS - Native Linux Persona Ring 3 Init Payload
 * Author: Jared Busby (jb7572)
 * Architecture: x86_64 System V AMD64 ABI
 */

#include <stdint.h>
#include <stddef.h>

#define SYS_READ   0
#define SYS_WRITE  1
#define SYS_OPEN   2
#define SYS_CLOSE  3
#define SYS_EXIT   60

/* Direct x86_64 System V Syscall Stub */
static inline int64_t sys_call3(uint64_t num, uint64_t arg1, uint64_t arg2, uint64_t arg3) {
    int64_t ret;
    __asm__ volatile (
        "syscall"
        : "=a"(ret)
        : "a"(num), "D"(arg1), "S"(arg2), "d"(arg3)
        : "rcx", "r11", "memory"
    );
    return ret;
}

static inline void sys_exit(int code) {
    __asm__ volatile (
        "syscall"
        :
        : "a"(SYS_EXIT), "D"(code)
        : "rcx", "r11", "memory"
    );
    while (1);
}

static size_t str_len(const char *s) {
    size_t len = 0;
    while (s[len]) len++;
    return len;
}

static void print_msg(const char *msg) {
    sys_call3(SYS_WRITE, 1, (uint64_t)msg, str_len(msg));
}

void _start(void) {
    print_msg("[USERLAND:LINUX] Hello from SecureCurtain Ring 3 User Space!\n");
    print_msg("[USERLAND:LINUX] Executing inside isolated unprivileged mode.\n");
    print_msg("[USERLAND:LINUX] Memory protection active: Ring 0 Kernel data is inaccessible.\n");
    print_msg("[USERLAND:LINUX] POSIX sys_write syscall executed successfully via IA32_LSTAR.\n");
    print_msg("[USERLAND:LINUX] Process initialization test complete. Exiting cleanly (status 0)...\n");

    sys_exit(0);
}
__SECURECURTAIN_EOF__

cat << '__SECURECURTAIN_EOF__' > "${TARGET_DIR}/sys/boot/boot.asm"
; =========================================================================
; SECURE PROTOTYPE OS: BARE-METAL 64-BIT LONG-MODE BOOTLOADER INITIATOR
; =========================================================================
bits 32                         ; Initial entry from stage-1 bootloader in 32-bit protected mode
global boot_entry
extern kernel_init              ; Our native 64-bit C kernel entry path function

section .boot
align 4
multiboot_header:
    dd 0x1BADB002               ; Multiboot magic identifier token
    dd 0x00000003               ; Flags: align modules, provide memory map
    dd -(0x1BADB002 + 0x00000003) ; Checksum verification calculation

boot_entry:
    cli                         ; 1. Disable legacy hardware interrupts immediately
    mov esp, stack_top          ; Establish initial basic boot stack pointer context

    ; 2. Verify CPU long-mode compatibility via extended CPUID feature queries
    mov eax, 0x80000000
    cpuid
    cmp eax, 0x80000001
    jb .no_long_mode            ; Abort if CPU lacks extended function queries
    
    mov eax, 0x80000001
    cpuid
    test edx, 1 << 29           ; Test Bit 29: Long Mode LM-bit indicator flag
    jz .no_long_mode            ; Abort if CPU hardware lacks 64-bit support

    ; 3. Construct Identity-Mapped temporary 4-Level Page Tables in RAM
    ; Zero out the page directories spaces first
    mov edi, boot_p4
    mov ecx, 4096 * 3
    xor eax, eax
    rep stosb

    ; Link PML4 (Level 4) entry 0 directly to the Page Directory Pointer Table (PDPT)
    mov eax, boot_p3
    or eax, 0x3                 ; Present bit + Read/Write bit flags active
    mov [boot_p4], eax

    ; Link PDPT (Level 3) entry 0 directly to the Page Directory Table (PDT)
    mov eax, boot_p2
    or eax, 0x3                 ; Present + Read/Write
    mov [boot_p3], eax

    ; Populate PDT (Level 2) to map the initial 2MB of memory as a massive page block
    mov eax, 0x00000000
    or eax, 0x83                ; Present + Read/Write + Huge Page Bit (Bit 7)
    mov [boot_p2], eax

    ; 4. Load the Level 4 Page Table pointer into the CR3 control register
    mov eax, boot_p4
    mov cr3, eax

    ; 5. Enable Physical Address Extension (PAE) in the CR4 control register
    mov eax, cr4
    or eax, 1 << 5              ; Set Bit 5: PAE operation flag bitmask
    mov cr4, eax

    ; 6. Switch model specific registers to enable long-mode execution paths
    mov ecx, 0xC0000080         ; EFER MSR register tracking index code
    rdmsr
    or eax, 1 << 8              ; Set Bit 8: LME Long Mode Enable flag bitmask
    wrmsr

    ; 7. Enable Paging inside the CR0 control register to finalize transition
    mov eax, cr0
    or eax, 1 << 31             ; Set Bit 31: PG Paging activation bitmask
    mov cr0, eax

    ; 8. Load a temporary 64-bit Global Descriptor Table (GDT) layout matrix
    lgdt [gdt64_pointer]
    jmp 0x08:.long_mode_jump     ; Far jump code segment reload descriptor mapping

bits 64
.long_mode_jump:
    mov ax, 0x10                ; Overwrite data segments tracking registers contexts
    mov ds, ax
    mov es, ax
    mov fs, ax
    mov gs, ax
    mov ss, ax

    ; 9. Transfer complete baseline control straight into your 64-bit microkernel init
    call kernel_init

.halt_loop:
    hlt                         ; Safety fallback loop boundary trap
    jmp .halt_loop

.no_long_mode:
    ; Hardware failsafe: Flash error colors to legacy VGA text memory space and halt
    mov dword [0xB8000], 0x4F524F45 ; Print "ER" red on white string footprints
    hlt
    jmp .no_long_mode

section .gdt
align 8
gdt64_base:
    dq 0x0000000000000000       ; Null descriptor slot
.code_slot:
    dq 0x00209A0000000000       ; 64-bit Kernel Code Segment descriptor (Conforming, Executable)
.data_slot:
    dq 0x0000920000000000       ; 64-bit Data Segment descriptor (Read/Write layout)
gdt64_pointer:
    dw $ - gdt64_base - 1
    dq gdt64_base

section .bss
align 4096
boot_p4: resb 4096
boot_p3: resb 4096
boot_p2: resb 4096
stack_bottom:
    resb 16384                  ; Allocate a distinct 16KB system boot stack workspace
stack_top:
__SECURECURTAIN_EOF__

cat << '__SECURECURTAIN_EOF__' > "${TARGET_DIR}/sys/boot/uefi_crt0.s"
; =========================================================================
; SECURE PROTOTYPE OS: BARE-METAL UEFI C-RUNTIME ENTRY INITIALIZATION STUB
; =========================================================================
bits 64
global _start
extern kernel_main              ; Our native 64-bit C kernel core entry path function

section .text
_start:
    ; 1. UEFI firmware transfers control here in 64-Bit Long Mode.
    ; According to Microsoft x64 MS-ABI conventions:
    ;   %rcx = EFI_HANDLE (ImageHandle)
    ;   %rdx = EFI_SYSTEM_TABLE* (SystemTable)
    
    cli                         ; Disable legacy hardware interrupts immediately
    
    ; 2. Enforce absolute 16-byte stack alignment required by physical x86-64 hardware
    mov rbp, rsp                ; Preserve the firmware stack frame anchor
    and rsp, -16                ; Clear the lower 4 bits to force 16-byte alignment boundaries
    sub rsp, 32                 ; Allocate standard 32-byte MS-ABI "Shadow Space" / scratch pad

    ; 3. Preserve the critical UEFI firmware boot parameters
    ; Move them into non-volatile callee-saved registers so kernel sub-initializers can query them
    mov rbx, rcx                ; rbx = ImageHandle
    mov r12, rdx                ; r12 = SystemTablePointer

    ; 4. Pass the verified parameters directly down to your native C microkernel entry point
    ; Re-populate %rcx and %rdx to match MS-ABI argument expectations for the called C function
    mov rcx, rbx
    mov rdx, r12
    call kernel_main

.efi_halt_trap:
    ; Hardware failsafe fallback loop boundary trap if the kernel returns control
    hlt
    jmp .efi_halt_trap

section .data
align 16
; UEFI-compliant metadata allocations can be stationed here if doing low-level relocations
