SYS_DIR = WORKSPACE_ROOT / "sys"
NETWORK_DIR = SYS_DIR / "subsystems" / "network"
LINUX_DIR = SYS_DIR / "kernel" / "src" / "linux"
LINUX_INC_DIR = SYS_DIR / "kernel" / "include" / "linux"
